CARDIO.register({"item":"233","meta":{"num":233,"short":"Valvulopathies","title":"Valvulopathies","section":"II","chapter":8,"pages":"193-247","sdd":[{"num":18,"label":"Découverte d'anomalies à l'auscultation cardiaque"},{"num":20,"label":"Découverte d'anomalies à l'auscultation pulmonaire"},{"num":21,"label":"Asthénie"},{"num":22,"label":"Diminution de la diurèse"},{"num":44,"label":"Hyperthermie/fièvre"},{"num":50,"label":"Malaise/perte de connaissance"},{"num":160,"label":"Détresse respiratoire aiguë"},{"num":161,"label":"Douleur thoracique"},{"num":162,"label":"Dyspnée"},{"num":165,"label":"Palpitations"},{"num":166,"label":"Tachycardie"},{"num":178,"label":"Demande/prescription raisonnée et choix d'un examen diagnostique"},{"num":185,"label":"Réalisation et interprétation d'un électrocardiogramme (ECG)"},{"num":190,"label":"Hémoculture positive"},{"num":203,"label":"Élévation de la protéine C-réactive (CRP)"},{"num":230,"label":"Rédaction de la demande d'un examen d'imagerie"},{"num":231,"label":"Demande d'un examen d'imagerie"},{"num":232,"label":"Demande d'explication d'un patient sur le déroulement, les risques et les bénéfices attendus d'un examen d'imagerie"},{"num":233,"label":"Identifier/reconnaître les différents examens d'imagerie (type/fenêtre/séquences/incidences/injection)"},{"num":239,"label":"Explication préopératoire et recueil de consentement d'un geste invasif diagnostique ou thérapeutique"},{"num":247,"label":"Prescription d'une rééducation"},{"num":248,"label":"Prescription et suivi d'un traitement par anticoagulant et/ou antiagrégant"},{"num":253,"label":"Prescrire des diurétiques"},{"num":255,"label":"Prescrire un anti-infectieux"},{"num":258,"label":"Prévention de la douleur liée aux soins"},{"num":259,"label":"Évaluation et prise en charge de la douleur aiguë"},{"num":271,"label":"Prescription et surveillance d'une voie d'abord vasculaire"},{"num":279,"label":"Consultation de suivi d'une pathologie chronique"},{"num":285,"label":"Consultation de suivi et éducation thérapeutique d'un patient avec antécédents cardiovasculaires"},{"num":300,"label":"Consultation pré-anesthésique"},{"num":311,"label":"Prévention des infections liées aux soins"},{"num":314,"label":"Prévention des risques liés au tabac"},{"num":320,"label":"Prévention des maladies cardiovasculaires"},{"num":324,"label":"Modification thérapeutique du mode de vie (sommeil, activité physique, alimentation, etc.)"},{"num":328,"label":"Annonce d'une maladie chronique"},{"num":334,"label":"Demande de traitement et investigation inappropriés"},{"num":335,"label":"Évaluation de l'aptitude au sport et rédaction d'un certificat de non-contre-indication"},{"num":339,"label":"Prescrire un arrêt de travail"},{"num":342,"label":"Rédaction d'une ordonnance/d'un courrier médical"},{"num":352,"label":"Expliquer un traitement au patient (adulte/enfant/adolescent)"},{"num":354,"label":"Évaluation de l'observance thérapeutique"},{"num":355,"label":"Organisation de la sortie d'hospitalisation"}]},"objectives":[{"id":"233-obj-01","rank":"A","rubric":"Définition","title":"Définition de l'insuffisance mitrale (IM), du rétrécissement aortique (RA), de l'insuffisance aortique (IA), du rétrécissement mitral (RM)","desc":""},{"id":"233-obj-02","rank":"A","rubric":"Étiologies","title":"Connaître les principales étiologies des valvulopathies (IM, RA, IA, RM)","desc":""},{"id":"233-obj-03","rank":"A","rubric":"Diagnostic positif","title":"Signes fonctionnels et examen clinique (auscultation) de l'IM, RA, IA, RM","desc":""},{"id":"233-obj-04","rank":"A","rubric":"Examens complémentaires","title":"Connaître la valeur primordiale de l'échocardiographie dans l'IM, l'IA, le RA et le RM","desc":"Diagnostic positif, diagnostic du mécanisme et de l'étiologie, diagnostic de sévérité"},{"id":"233-obj-05","rank":"B","rubric":"Physiopathologie","title":"Mécanismes et conséquences physiopathologiques de l'IM, l'IA, du RA, du RM","desc":""},{"id":"233-obj-06","rank":"B","rubric":"Examens complémentaires","title":"Connaître l'intérêt de l'ECG, de la radiographie thoracique, de l'épreuve d'effort dans les valvulopathies","desc":""},{"id":"233-obj-07","rank":"B","rubric":"Suivi et/ou pronostic","title":"Évolutions et complications de l'IM, du RA, de l'IA, du RM","desc":""},{"id":"233-obj-08","rank":"B","rubric":"Prise en charge","title":"Principes du traitement chirurgical de l'IM, du RA, de l'IA, du RM","desc":"Plastie ou remplacement valvulaire"},{"id":"233-obj-09","rank":"B","rubric":"Prise en charge","title":"Principe des traitements percutanés de l'IM, du RA, du RM","desc":"TAVI, savoir que cette alternative percutanée existe pour l'IM (MitraClip®)"},{"id":"233-obj-10","rank":"B","rubric":"Prise en charge","title":"Principales indications de traitement chirurgical de l'IM, du RA, du RM et de l'IA","desc":""},{"id":"233-obj-11","rank":"B","rubric":"Prise en charge","title":"Principales indications de traitement percutané du RA et de l'IM","desc":""},{"id":"233-obj-12","rank":"B","rubric":"Prise en charge","title":"Modalités du traitement médical de l'IA","desc":"Bêtabloquant dans le Marfan"}],"course":{"sections":[{"id":"233-sec-01","title":"Rétrécissement aortique : définition, anatomie et physiopathologie","rank":"A","objectives":["233-obj-01","233-obj-05"],"content":"### Définition\n\n- Le **RA est la valvulopathie la plus fréquente** : obstacle à l'éjection du VG, siégeant le plus souvent sur la valve aortique elle-même.\n- Cause dominante : **RA dégénératif du sujet de plus de 65 ans**.\n- Autres obstacles à l'éjection (hors chapitre) : rétrécissement supra-aortique, rétrécissement sous-aortique (diaphragme), obstruction dynamique des cardiomyopathies obstructives.\n\n### Rappel anatomique\n\n- Valve normalement **tricuspide** : 3 cusps (sigmoïdes) — antérodroite, antérogauche, non coronaire — chacune en regard d'un sinus de Valsalva ; ouverture **passive** selon le gradient VG–aorte.\n- Vieillissement et processus pathologiques → cusps épaissies, rigides, calcifiées → mobilité restreinte.\n- **Bicuspidie** (1–2 % de la population) : fusion ou défaut de séparation embryologique de 2 cusps ; anomalie congénitale qui favorise le RA.\n\n### Physiopathologie [B]\n\nLa réduction de l'orifice crée une résistance à l'éjection avec 3 conséquences :\n\n1. **Gradient de pression VG–aorte** : normalement 2 à 5 mmHg (courbes de pression VG et aortique quasi superposables). En cas de RA, la PVG dépasse la PAo ; le gradient augmente avec la sévérité → **gradient moyen de 40 mmHg = RA serré**.\n2. **Hypertrophie pariétale concentrique** : l'hyperpression intra-VG élève la contrainte pariétale (postcharge) selon la loi de Laplace (contrainte = pression × diamètre / épaisseur). Hypertrophie des cardiomyocytes, fibrose et remaniement de la matrice normalisent la contrainte → la FEVG reste **longtemps normale**. Si l'hypertrophie est insuffisante : chute de la FEVG et insuffisance cardiaque. Une fibrose intramyocardique (ischémie relative : les coronaires n'irriguent pas tout le myocarde hypertrophié) peut empêcher la récupération complète après levée de l'obstacle.\n3. **Dysfonction diastolique** : baisse de compliance et relaxation ralentie → élévation des pressions de remplissage transmises aux veines et capillaires pulmonaires → congestion. La **systole atriale** devient indispensable au remplissage : le passage en **FA est mal toléré** (poussée d'insuffisance cardiaque).\n\n> [B] Trois maîtres mots : gradient, hypertrophie, dysfonction diastolique. La performance systolique globale est préservée pendant des années.","keyPoints":["Le RA est la valvulopathie la plus fréquente, surtout dégénérative après 65 ans.","Valve normale = 3 cusps ; bicuspidie chez 1–2 % de la population, facteur favorisant de RA.","Gradient VG–aorte normal de 2–5 mmHg ; un gradient moyen de 40 mmHg définit le RA serré.","L'hypertrophie concentrique normalise la contrainte pariétale (Laplace) et préserve longtemps la FEVG.","La dysfonction diastolique rend la systole atriale essentielle : la FA décompense le RA."],"pitfalls":["Une FEVG normale n'exclut pas un RA serré : la performance systolique est longtemps conservée.","La fibrose myocardique peut rendre la dysfonction VG partiellement irréversible même après remplacement valvulaire."],"src":"p. 195-197"},{"id":"233-sec-02","title":"Rétrécissement aortique : étiologies","rank":"A","objectives":["233-obj-02"],"content":"### RA congénital : la bicuspidie\n\n- Valve à **2 sigmoïdes** au lieu de 3 ; **étiologie la plus fréquente entre 30 et 65 ans**.\n- Bien tolérée dans l'enfance et l'adolescence ; malformation « évolutive » aboutissant à un RA à l'âge adulte.\n- Souvent associée à un **anévrisme de l'aorte ascendante** à rechercher systématiquement, plus rarement à une **coarctation**.\n- **Dépistage familial** des apparentés du 1er degré : transmission possiblement autosomique dominante à pénétrance variable (gènes des protéines élastiques de la média aortique, dont la fibrilline comme dans le Marfan).\n- Présentations multiples : certaines formes donnent une IA, d'autres un RA.\n- Forme la plus fréquente : **type I avec raphé** (fusion des sigmoïdes antérogauche et antérodroite).\n\n### RA acquis\n\n| Étiologie | Caractéristiques |\n|---|---|\n| **Dégénératif (maladie de Mönckeberg)** | De loin le plus fréquent chez le sujet âgé (> 65–70 ans) ; prévalence croissant avec l'âge ; calcifications à la base des valvules qui se rigidifient ; valve d'autant plus calcifiée que la sténose est sévère ; physiopathologie proche de l'athérosclérose |\n| **Post-rhumatismal** | Devenu rare, encore rencontré chez les migrants ; RA généralement associé à une IA et à une atteinte mitrale (RM + IM) |\n\n> **À retenir** : bicuspidie dans la majorité des cas **avant 65–70 ans**, RA dégénératif dans la majorité des cas **après** cette limite d'âge.","keyPoints":["Deux étiologies dominent : bicuspidie (avant 65–70 ans) et RA dégénératif de Mönckeberg (après).","La bicuspidie impose de rechercher un anévrisme de l'aorte ascendante et de dépister les apparentés du 1er degré.","Le RA post-rhumatismal est rare (migrants) et s'accompagne d'une IA et d'une atteinte mitrale.","Le RA dégénératif est calcifié, d'autant plus que la sténose est sévère."],"pitfalls":["Ne pas oublier de mesurer l'aorte devant une bicuspidie : l'anévrisme associé est fréquent.","La bicuspidie peut aussi se manifester par une IA et non seulement par un RA."],"src":"p. 197-198"},{"id":"233-sec-03","title":"Rétrécissement aortique : signes fonctionnels et examen clinique","rank":"A","objectives":["233-obj-03"],"content":"### Circonstances de découverte\n\n- Souffle entendu en consultation.\n- Symptômes d'effort.\n- Complication : insuffisance cardiaque.\n- Échocardiographie faite pour une autre raison.\n\n### Signes fonctionnels\n\nLe RA reste **longtemps asymptomatique** (plusieurs années), puis apparaissent les **3 maîtres symptômes, tous à l'effort** :\n\n1. **dyspnée** d'effort ;\n2. **angor** d'effort ;\n3. **syncope** d'effort.\n\nLeur apparition marque une **cassure évolutive** et un **mauvais pronostic sans traitement**. L'interrogatoire est minutieux : le patient a souvent réduit ses activités pour ne plus être gêné et se déclare à tort asymptomatique → chercher une diminution progressive des efforts par rapport aux mois ou années précédents.\n\n### Palpation\n\n- **Frémissement** au foyer aortique, perçu avec le plat de la main, patient penché en avant en fin d'expiration → RA hémodynamiquement significatif, souffle d'intensité **4/6**.\n- Formes évoluées : choc de pointe élargi, dévié en bas et à gauche (dilatation du VG).\n\n### Auscultation (souvent suffisante au diagnostic)\n\n- Souffle **mésosystolique, éjectionnel**, intense, **rude et râpeux**, maximal au **2e espace intercostal droit**, **irradiant dans les vaisseaux du cou** ; tonalité parfois plus musicale au foyer pulmonaire ou à la pointe ; **se renforce après une diastole longue** ; forme **losangique** (maximum en mésosystole).\n- Association possible à un souffle d'IA : « **maladie aortique** ».\n- **Abolition de B2** dans les RA serrés calcifiés.\n- RA évolué à bas débit : souffle atténué, voire quasi inaudible.","keyPoints":["Triade d'effort du RA : dyspnée, angor, syncope — leur apparition impose de traiter.","Souffle mésosystolique éjectionnel râpeux au 2e EIC droit irradiant aux carotides, renforcé après une diastole longue.","B2 aboli = argument pour un RA serré calcifié.","Frémissement palpatoire = RA significatif avec souffle 4/6.","Interroger sur la réduction progressive des activités : beaucoup de patients se disent asymptomatiques à tort."],"pitfalls":["Un souffle faible n'exclut pas un RA serré : à bas débit il peut devenir presque inaudible.","Un patient qui a limité ses efforts peut paraître asymptomatique."],"src":"p. 198-199"},{"id":"233-sec-04","title":"Rétrécissement aortique : examens complémentaires","rank":"A","objectives":["233-obj-04","233-obj-06"],"content":"### Radiographie thoracique [B]\n\nNormale, ou dans le RA évolué : dilatation du VG (cardiomégalie), surcharge pulmonaire (IC gauche).\n\n### ECG [B]\n\nNormal si RA peu évolué. RA serré : **HVG de type surcharge systolique +++** (T négatives asymétriques en précordiales gauches) — son absence n'exclut pas un RA serré ; hypertrophie atriale gauche ; troubles de conduction (**BBG, BAV 1**) ; FA (RA évolué, moins fréquente que dans les atteintes mitrales).\n\n### ETT : l'examen clé\n\n1. **Confirmer** : valve remaniée, calcifiée, ouverture réduite en 2D ; vitesses augmentées en doppler continu (> 2,5 m/s).\n2. **Quantifier** :\n\n| Paramètre | Normal | RA serré |\n|---|---|---|\n| Vmax (doppler continu) | ≈ 1 m/s | **> 4 m/s** (dépend du débit) |\n| Gradient moyen VG–Ao | 2–5 mmHg | **> 40 mmHg** |\n| Surface aortique | 2–3,5 cm² | **< 1 cm² ou < 0,6 cm²/m²** ; critique si ≤ 0,75 cm² ou < 0,4 cm²/m² |\n\nLa planimétrie 2D (ETT ou mieux ETO) est réservée aux rares cas de sévérité douteuse.\n\n> **RA serré à bas gradient** : gradient < 40 mmHg possible si bas débit, c'est-à-dire **volume d'éjection systolique ≤ 35 mL/m²**, FEVG préservée ou non. Écho sous **faible dose de dobutamine** : si la surface dépasse 1 cm², il s'agit d'une **pseudosténose** à surveiller et traiter comme une insuffisance cardiaque.\n\n3. **Retentissement** : hypertrophie et dilatation du VG, FEVG ([B] un remplacement peut se discuter chez l'asymptomatique si FEVG < 55 % imputable au seul RA ; strain et IRM à la recherche de fibrose en cas de doute) ; débit cardiaque longtemps conservé ; PAP longtemps normale, ne s'élevant qu'au stade de dysfonction VG.\n4. **Autres valves et aorte** : atteinte mitrale surtout ; IT fonctionnelle par HTP chronique (dilatation du VD) ; **mesure de l'aorte** indispensable en cas de bicuspidie (ETO, angioscanner ou IRM) pour décider d'un geste aortique associé.\n\n### Cathétérisme et coronarographie\n\n- Cathétérisme habituellement **inutile** (données fournies par l'écho) ; seule indication : discordance clinique/écho, patients peu échogènes.\n- **Coronarographie préopératoire** : homme > 40 ans ou femme ménopausée même sans facteur de risque ; quel que soit l'âge si facteurs de risque coronarien, angor d'effort ou insuffisance cardiaque (l'angor fonctionnel du RA est cliniquement indiscernable d'une coronaropathie).\n\n### Scanner [B]\n\n- Coroscanner en remplacement de la coronarographie : place controversée (calcifications coronaires fréquentes chez l'âgé).\n- Scanner cardiaque **systématique avant TAVI** : taille de l'anneau et du culot aortique, distance des ostia coronaires, diamètres et tortuosités des axes ilio-fémoraux, subclaviers, carotidiens (voie d'abord).\n- Mesure de l'aorte ascendante si l'ETT est insuffisante.\n- **Score calcique valvulaire** en cas de discordance (surface < 1 cm² mais gradient < 40 mmHg avec bonne FEVG) : RA serré si **> 2 000 UA chez l'homme, > 1 200 UA chez la femme**.\n\n### Épreuve d'effort [B]\n\nIndiquée dans le **RA serré asymptomatique** pour vérifier objectivement l'absence de symptôme (patients adaptés qui ne font plus d'effort) : niveau d'effort atteint, **élévation inadéquate ou baisse de la PA** à l'effort.","keyPoints":["RA serré : Vmax > 4 m/s, gradient moyen > 40 mmHg, surface < 1 cm² ou < 0,6 cm²/m².","Surface critique : ≤ 0,75 cm² ou < 0,4 cm²/m².","Bas gradient avec VES ≤ 35 mL/m² : écho de stress sous dobutamine pour distinguer RA serré et pseudosténose.","L'ECG montre typiquement une HVG systolique, mais un ECG normal n'exclut pas un RA serré.","Coronarographie préopératoire : homme > 40 ans, femme ménopausée, facteurs de risque, angor ou IC.","Scanner systématique avant TAVI ; score calcique > 2 000 UA (homme) ou > 1 200 UA (femme) en faveur d'un RA serré.","L'épreuve d'effort sert à démasquer les symptômes d'un RA serré dit asymptomatique."],"pitfalls":["Se fier au seul gradient : un RA serré peut avoir un gradient bas si le débit est bas.","Faire une épreuve d'effort à un RA serré symptomatique : elle n'est préconisée que chez l'asymptomatique.","Oublier de mesurer l'aorte ascendante devant une bicuspidie."],"src":"p. 200-204"},{"id":"233-sec-05","title":"Rétrécissement aortique : évolution, complications et traitement","rank":"B","objectives":["233-obj-07","233-obj-08","233-obj-09","233-obj-10","233-obj-11"],"content":"### Évolution et complications\n\nLongue phase asymptomatique ; l'apparition de symptômes ou de complications est de mauvais pronostic sans traitement et impose une indication thérapeutique :\n\n- insuffisance cardiaque ;\n- **FA, mal tolérée** (perte de la systole atriale) ;\n- troubles de conduction ;\n- **mort subite +++**, surtout dans le RA serré symptomatique ;\n- endocardite (rare) ; hyperexcitabilité ventriculaire (rare) ;\n- **embolies calcaires** systémiques (rares) : cérébrales, rénales, coronaires, artère centrale de la rétine (cécité transitoire) ;\n- **anémie ferriprive** par angiodysplasies intestinales ± anomalie acquise du facteur von Willebrand (**syndrome de Heyde**).\n\n### Possibilités thérapeutiques\n\n| Option | Points clés |\n|---|---|\n| **RVA chirurgical – prothèse mécanique** | Anticoagulation à vie ; longue durabilité ; sujet jeune |\n| **RVA chirurgical – bioprothèse** | Pas d'anticoagulant ; patient > 65 ans ; dégénérescence en 10–15 ans |\n| **TAVI** | Bioprothèse implantée par voie fémorale ou apicale ; risque chirurgical élevé ou intermédiaire avec gain fonctionnel attendu ; décision obligatoire en **Heart Team** (âge, fragilité, comorbidités, souhaits) ; dépasse désormais la chirurgie en nombre en France ; recommandé chez les **inopérables ou à risque quel que soit l'âge** et en **1re intention > 75 ans** quel que soit le risque si voie fémorale possible |\n| **Valvuloplastie au ballon** | Dilatation sans prothèse ; quasi abandonnée (resténose précoce) ; reste indiquée avant une chirurgie non cardiaque urgente à risque chez un RA serré symptomatique |\n\n### Indications\n\n1. **RA serré symptomatique** : traitement systématique (RVA ou TAVI), pratiquement **sans limite d'âge**, si l'état général est conservé et sans autre pathologie engageant le pronostic à court terme.\n2. **RA serré asymptomatique à FEVG normale** : surveillance, sauf intervention si :\n   - épreuve d'effort anormale ;\n   - RA très serré (**Vmax > 5 m/s**) ;\n   - aggravation rapide de la sténose ;\n   - **FEVG < 55 %**.\n3. **RA avec dysfonction VG (FE < 35 %)** : risque opératoire accru mais pronostic le plus mauvais chez les non-opérés ; écho de stress sous dobutamine (réserve contractile, exclusion d'une pseudosténose : surface < 1 cm² au repos devenant > 1 cm²).\n\n### Bilan préopératoire [A]\n\nÉvaluer le risque opératoire : imagerie coronaire (coronarographie ou coroscanner) ; scanner ou IRM de l'aorte si dilatation (bicuspidie) [B] et pour le score calcique, IRM pour la fibrose dans les cas difficiles ; **échodoppler des troncs supra-aortiques** ; foyers infectieux ORL et dentaires (radiographie des sinus, panoramique) ; comorbidités (rein, poumon) ; avis gériatrique chez le très âgé.\n\n> **Inacceptable** : oublier l'éducation (prévention de l'endocardite, consultation urgente si symptômes d'effort) ; ne pas évoquer l'endocardite devant une fièvre ; ne pas adresser au spécialiste un RA symptomatique, un souffle modifié ou le suivi annuel.","keyPoints":["Complications du RA : IC, FA mal tolérée, troubles conductifs, mort subite, embolies calcaires, syndrome de Heyde.","Tout RA serré symptomatique se traite (RVA ou TAVI), quasi sans limite d'âge.","RA serré asymptomatique : opérer si épreuve d'effort anormale, Vmax > 5 m/s, progression rapide ou FEVG < 55 %.","TAVI : inopérables ou à risque à tout âge, et 1re intention après 75 ans si la voie fémorale est possible.","Bioprothèse après 65 ans (dégénérescence en 10–15 ans) ; prothèse mécanique chez le jeune (anticoagulation à vie).","Bilan préopératoire : coronaires, aorte si bicuspidie, TSA, foyers infectieux, comorbidités, gériatrie."],"pitfalls":["Refuser un traitement au seul motif de l'âge : le RA serré symptomatique se traite pratiquement sans limite d'âge.","La valvuloplastie au ballon n'est pas un traitement de fond : resténose précoce.","Une FE < 35 % ne contre-indique pas l'intervention : les non-opérés ont le pire pronostic."],"src":"p. 204-207"},{"id":"233-sec-06","title":"Insuffisance mitrale : définition, classification de Carpentier et physiopathologie","rank":"A","objectives":["233-obj-01","233-obj-05"],"content":"### Définition\n\nL'IM est un **défaut d'étanchéité** de la valve mitrale entraînant un reflux du VG vers l'atrium gauche (AG) **en systole**.\n\n### Anatomie\n\n2 feuillets (antérieur = grande valve, postérieur = petite valve) insérés sur un anneau fibreux, réunis par 2 commissures (antéroexterne, postéro-interne), amarrés au VG par des cordages issus de 2 piliers appartenant au myocarde. En systole, les feuillets s'affrontent **dans le plan de l'anneau**.\n\n### Classification de Carpentier (mouvement des feuillets en systole)\n\n| Type | Jeu valvulaire | Exemples |\n|---|---|---|\n| **I** | Normal, feuillets dans le plan de l'anneau | Perforation, fente ; IM **atriale** par dilatation de l'anneau (AG très dilaté, FA permanente) |\n| **II** | Exagéré : un feuillet dépasse le plan vers l'AG | **Prolapsus** des IM dystrophiques (coaptation dans l'AG) |\n| **IIIa** | Restreint en systole **et** diastole | RAA, radiothérapie, IM médicamenteuses |\n| **IIIb** | Restreint en systole seulement | IM secondaire des cardiopathies dilatées ou ischémiques (piliers éloignés, traction des cordages) |\n\n[B] L'IM peut résulter d'une atteinte isolée ou conjointe de l'anneau, des feuillets, des cordages ou des piliers (déplacés par un VG sphérique).\n\n### Physiopathologie [B]\n\nLe volume régurgité dépend de la **taille de l'orifice régurgitant**, du **gradient VG–AG** et de la **durée de la systole**.\n\n**En aval (VG)** : surcharge volumique → dilatation du VG (il reçoit le sang des veines pulmonaires + le volume régurgité) ; épaississement pariétal compensateur = **hypertrophie excentrique**, insuffisante quand le VG devient sphérique → dysfonction, fibrose, récupération limitée. La **FEVG est surestimée** (VG déchargé dans l'AG) : on parle de **dysfonction dès FEVG < 60 %**.\n\n> Correction recommandée même chez l'asymptomatique si **DTS VG > 40 mm et/ou FEVG < 60 %**.\n\n**En amont (AG, poumon)** : dilatation de l'AG avec **risque de FA** ; **HTP post-capillaire** (au cathétérisme : PAPO > 15 mmHg, onde V de reflux), fonction du volume régurgité et de la compliance de l'AG et des veines pulmonaires.\n- IM chronique primaire : AG dilaté et compliant → pression atriale et PAP longtemps normales malgré une fuite importante ; la PAP monte quand la compliance est dépassée.\n- **IM aiguë** : AG non dilaté, compliance inadaptée → **HTP immédiate et importante**.","keyPoints":["IM = reflux systolique VG → AG par défaut d'étanchéité mitrale.","Carpentier : type I jeu normal, type II excès (prolapsus), type IIIa restriction systolo-diastolique (RAA), type IIIb restriction systolique (IM secondaire).","La FEVG est surestimée dans l'IM : dysfonction dès 60 %.","Retentissement VG justifiant la correction : DTS > 40 mm et/ou FEVG < 60 %.","HTP post-capillaire : PAPO > 15 mmHg avec onde V ; brutale et sévère dans l'IM aiguë.","La dilatation de l'AG expose à la FA."],"pitfalls":["Une FEVG à 60 % dans une IM sévère est déjà une dysfonction ventriculaire.","Ne pas confondre IM atriale (type I, anneau dilaté) et IM ventriculaire (type IIIb, piliers déplacés)."],"src":"p. 209-211"},{"id":"233-sec-07","title":"Insuffisance mitrale : étiologies et causes d'IM aiguë","rank":"A","objectives":["233-obj-02"],"content":"### Deux familles\n\n- **IM primaire (organique)** : lésion des feuillets ou des cordages.\n- **IM secondaire (fonctionnelle)** : feuillets normaux, anomalie du **ventricule** (déplacement des piliers) ou de l'**anneau** dilaté par un AG dilaté (IM atriale).\n\n### IM primaire dystrophique (Carpentier II) — cause la plus fréquente des fuites sévères\n\n- Élongation ou **rupture de cordages** ± excès de tissu → **prolapsus**.\n- **Ballonnisation** : bombement systolique d'un feuillet trop ample dans l'AG, bord libre restant dans le plan de l'anneau. **Prolapsus** : l'extrémité du feuillet passe en arrière du plan.\n- Atteinte de la valve postérieure, antérieure ou des deux.\n- **Dégénérescence myxoïde (maladie de Barlow)** : excès de tissu, valves redondantes épaissies, hypermobilité, ruptures de cordages par traction.\n- **Dégénérescence fibroélastique** (plus fréquente) : sujets plus âgés, surtout hommes, valve postérieure ; tissu adapté à l'orifice ; mécanisme = rupture de cordages.\n- [B] Parfois dans un Marfan ou un Ehlers-Danlos.\n\n### IM secondaire (Carpentier IIIb)\n\nIM **ischémique** (classiquement après infarctus inférieur avec séquelle de cinétique inférieure) et IM par **dilatation/dysfonction du VG** quelle qu'en soit la cause.\n\n### IM primaire rhumatismale et apparentées (Carpentier IIIa)\n\n- Rare dans les pays développés, endémique dans les pays en développement.\n- Associée le plus souvent à un **RM** (sténose + IM = **maladie mitrale**) et à une atteinte aortique.\n- Valves épaissies, rétractées ; cordages raccourcis, ruptures possibles.\n- Apparentées : IM **médicamenteuses** (dérivés de l'ergot de seigle, anorexigènes retirés : fenfluramine, benfluorex), **radiothérapie**.\n\n### Autres\n\n- **IM atriale** (type I) : dilatation de l'anneau sur AG très dilaté, plus rare.\n- **Endocardite** : plus de la moitié sur lésion préexistante (prolapsus, autre IM) ; lésions végétantes et mutilantes ; ruptures de cordages (II) ou perforations/déchirures (I), surtout de la valve antérieure.\n- IM **ischémique aiguë** : dysfonction ou rupture de pilier → choc, fuite massive, **urgence chirurgicale**.\n- **CMH obstructive** : feuillet antérieur aspiré dans la chambre de chasse (SAM), fuite parfois sévère.\n- Congénitale (fente de la valve antérieure, canal atrioventriculaire) ; traumatisme fermé du thorax (très rare).\n- Dystrophies conjonctivo-élastiques (Marfan, Ehlers-Danlos, pseudoxanthome élastique) ; lupus avec syndrome des antiphospholipides ; calcifications dégénératives de l'anneau.\n\n### Causes d'IM aiguë\n\n1. **Rupture de cordages** : dégénérescence myxoïde ou fibroélastique, endocardite, traumatisme — possible **OAP unilatéral** par fuite « directionnelle » vers un seul poumon.\n2. **Infarctus** : rupture de pilier, restriction aiguë sur akinésie segmentaire, dysfonction ischémique de pilier.\n3. Traumatisme thoracique.\n4. **Perforation par endocardite**.\n\n> L'IM aiguë est le plus souvent grave sur le plan hémodynamique : **urgence vitale**.","keyPoints":["IM primaire = valve malade (feuillets, cordages) ; IM secondaire = valve saine, ventricule ou anneau malade.","L'IM dystrophique par prolapsus (type II) est la première cause de fuite mitrale sévère.","Barlow = excès de tissu myxoïde ; dégénérescence fibroélastique = rupture de cordage chez l'homme âgé, valve postérieure.","IM rhumatismale (IIIa) : maladie mitrale (RM + IM), atteinte aortique associée ; IM médicamenteuses et post-radiques apparentées.","IM aiguë : rupture de cordage, rupture ou dysfonction de pilier post-infarctus, traumatisme, perforation d'endocardite.","L'endocardite survient dans plus de la moitié des cas sur une valve déjà lésée."],"pitfalls":["Un OAP unilatéral peut révéler une IM aiguë par rupture de cordage (fuite directionnelle).","La rupture de pilier post-infarctus est une urgence chirurgicale : ne pas la traiter comme une simple décompensation."],"src":"p. 211-214"},{"id":"233-sec-08","title":"Insuffisance mitrale : clinique et examens complémentaires","rank":"A","objectives":["233-obj-03","233-obj-04","233-obj-06"],"content":"### Circonstances et signes fonctionnels\n\n- Découverte : souffle systématique ; palpitations, dyspnée ou asthénie d'effort ; complication (**OAP, FA**) ; fièvre prolongée (endocardite).\n- Absents si IM modérée ; une IM sévère peut rester asymptomatique. Dyspnée d'effort lente et progressive ± asthénie ; tardivement dyspnée de repos, orthopnée, dyspnée paroxystique nocturne. L'**OAP est tardif et grave**.\n\n### Examen clinique\n\n- Palpation : frémissement systolique apical ; choc de pointe dévié et abaissé si VG dilaté.\n- **Souffle holosystolique de régurgitation**, de B1 à B2 (peut le dépasser), maximal à la **pointe / apexo-axillaire**, en **jet de vapeur**, doux parfois rude, d'intensité souvent mais pas toujours proportionnelle à la fuite, **irradiant à l'aisselle** — sauf prolapsus du feuillet postérieur (jet vers le septum interatrial et l'aorte : irradiation vers la base) ; **ne se renforce pas après une diastole longue**.\n- **Prolapsus** : clic mésosystolique (mise en tension des cordages) puis souffle méso-télésystolique ou télésystolique.\n- IM importante : B3, roulement mésodiastolique d'hyperdébit, éclat de B2 pulmonaire (HTP), souffle d'IT fonctionnelle ; crépitants.\n\n> Le souffle des **IM secondaires** est discret voire inaudible et mal corrélé à la sévérité.\n\n### ECG et radiographie [B]\n\n- ECG longtemps normal : HAG, HVG, FA, HVD si HTP sévère.\n- Radiographie : cardiomégalie (VG), dilatation de l'AG (arc moyen gauche convexe, débord de l'arc inférieur droit), signes d'HTP/IC (dilatation des artères pulmonaires, redistribution vers les sommets, lignes de Kerley, œdème alvéolaire).\n\n### ETT : examen clé (diagnostic positif, étiologique, sévérité et retentissement)\n\n- **Positif** : signal holosystolique en arrière du plancher mitral (doppler pulsé, continu, couleur).\n- **Étiologique** : mécanisme selon Carpentier. **ETO** : mécanismes et faisabilité d'une plastie (souvent en préopératoire) ; **obligatoire pour l'endocardite** (végétations fines), ruptures partielles de cordages, segments prolabés.\n- **Sévérité** : méthode **PISA** → surface de l'orifice régurgitant (SOR) ; 4 grades ; IM **significative = moyenne ou importante**.\n\n| Grade (IM primaire) | SOR (mm²) | Volume régurgité (mL) |\n|---|---|---|\n| I minime | < 20 | < 30 |\n| II modérée | 20–29 | 30–44 |\n| III moyenne | 30–39 | 45–59 |\n| IV importante | ≥ 40 | ≥ 60 |\n\n- **Retentissement** : DTS VG **> 40 mm**, FEVG **< 60 %**, volume AG **≥ 60 mL/m²**, PAP systolique **≥ 50 mmHg** (à confirmer au cathétérisme droit).\n- **IM secondaire** : seuil de sévérité **SOR ≥ 30 mm²** ; à évaluer plusieurs fois, **après optimisation du traitement de l'IC** (fuite « accordéon » selon la volémie).\n- **Tricuspide** : fuite même non sévère avec **anneau > 40 mm** en 4 cavités → annuloplastie tricuspide associée.\n\n### Coronaires, cathétérisme, effort\n\n- **Coroscanner** [A] si faible probabilité prétest.\n- Coronarographie : suspicion d'ischémie, baisse de FEVG, homme > 40 ans ou femme ménopausée, facteurs de risque.\n- Ventriculographie abandonnée ; cathétérisme droit parfois utile (débit par thermodilution, pressions droites).\n- [B] Épreuve d'effort, VO2, écho d'effort : indications imprécises ; démasquer les symptômes, apprécier la fuite et les pressions pulmonaires à l'effort.","keyPoints":["Souffle apexo-axillaire holosystolique en jet de vapeur, irradiant à l'aisselle, non renforcé après diastole longue.","Prolapsus : clic mésosystolique puis souffle télésystolique ; irradiation possible vers la base si feuillet postérieur.","IM primaire importante (grade IV) : SOR ≥ 40 mm², volume régurgité ≥ 60 mL ; IM secondaire sévère dès SOR ≥ 30 mm².","Retentissement : DTS > 40 mm, FEVG < 60 %, AG ≥ 60 mL/m², PAPs ≥ 50 mmHg.","ETO obligatoire pour l'endocardite ; utile pour planifier la plastie.","Anneau tricuspide > 40 mm → annuloplastie tricuspide lors de la chirurgie mitrale."],"pitfalls":["Quantifier une IM secondaire chez un patient en surcharge : la fuite varie avec la volémie.","Un souffle discret n'exclut pas une IM secondaire sévère.","Le souffle d'IM ne se renforce pas après une diastole longue, contrairement au RA."],"src":"p. 214-219"},{"id":"233-sec-09","title":"Insuffisance mitrale : évolution, complications et traitement","rank":"B","objectives":["233-obj-07","233-obj-08","233-obj-09","233-obj-10","233-obj-11"],"content":"### Évolution naturelle [A]\n\nDépend de la sévérité, de l'étiologie, de la rapidité d'installation, de la fonction VG et des lésions associées (coronaropathie). IM progressive : bien tolérée, IC tardive → **suivi régulier, ETT annuelle** si IM significative asymptomatique. IM brutale (rupture de cordage, endocardite, infarctus) : mal tolérée, OAP rapide.\n\n### Complications\n\n- Rupture de cordage (prolapsus ; RAA, CMH) ; **endocardite** aggravant la fuite.\n- **FA / flutter** : décompensation ; favorisés par la dilatation de l'AG ; justifient une chirurgie précoce chez l'asymptomatique. Troubles du rythme ventriculaire plus rares (dysfonction VG) ; [B] prolapsus avec **disjonction annulaire** (femme jeune, ESV, T négatives précordiales) exceptionnellement cause de mort subite.\n- [A] Insuffisance cardiaque : tardive (chronique), rapide (aiguë), favorisée par un trouble du rythme.\n\n### Surveillance et traitement médical\n\n- IM grade I–II : réévaluation clinique et écho régulière ; prévention de l'endocardite (hygiène cutanée, soins dentaires ; **pas d'antibioprophylaxie**).\n- **IM secondaire** : d'abord traitement de l'IC (médicaments, resynchronisation si QRS larges) ; intervention (plutôt percutanée) si échec.\n- IM primaire : pas de traitement de fond ; diurétiques-vasodilatateurs en poussée ; IM aiguë avec choc → **chirurgie urgente** ; anticoagulation si FA ; bêtabloquants si Marfan (risque de dissection).\n\n### Chirurgie\n\n- **Plastie reconstructrice = traitement idéal** : respecte l'appareil sous-valvulaire, moins de dysfonction VG, moindre morbimortalité, moindre risque d'endocardite ; indiquée dans les prolapsus ± rupture ; possible mais difficile (récidive) dans certaines IM rhumatismales ou ischémiques ; chirurgien expérimenté ; pas toujours réalisable.\n- **Remplacement** si valve trop remaniée : prothèse **mécanique** (anticoagulants, longue durée ; jeune ou FA associée) ou **bioprothèse** (pas d'anticoagulant, dégénérescence ; âgé, CI aux anticoagulants, désir de grossesse). **> 70 ans → bio, < 65 ans → mécanique.**\n- [B] **Percutané** : clip bord à bord (ESC 2021), IM primaire ou secondaire, uniquement si haut risque ou CI chirurgicale ; « clinique des valves » et **Heart Team** (niveau 1 ESC 2021).\n- **Bilan préopératoire** [A] : coronaires (coronarographie/coroscanner), échodoppler des TSA, foyers ORL et dentaires (sinus, panoramique), comorbidités (rein, poumon), avis gériatrique.\n\n### Indications [B]\n\n- **IM aiguë mal tolérée → chirurgie urgente.**\n- **IM primaire grade III–IV symptomatique** → chirurgie, plastie de préférence (possible même si dysfonction VG). Si plastie impossible : remplacement si **FE > 30 %** ; **FE < 30 % → remplacement contre-indiqué** (la FE chute de 10–15 % en postopératoire) → traitement médical ou transplantation si jeune. Clip si inopérable ou haut risque avec critères écho, procédure non futile. IM secondaire importante persistant sous traitement optimal → clip si IC pas trop avancée.\n- **IM primaire grade III–IV asymptomatique** → chirurgie si au moins un signe : **DTS > 40 mm** avec rupture de cordage, **FEVG < 60 %**, **PAPs > 50 mmHg** au repos, **FA** (même paroxystique) ou **AG > 60 mL/m²** en rythme sinusal. Sinon **écho tous les 6 mois** et chirurgie dès apparition d'un retentissement, de symptômes ou de FA.","keyPoints":["On opère les IM primaires importantes (grade III–IV) symptomatiques, en privilégiant la plastie.","Asymptomatique : opérer si DTS > 40 mm, FEVG < 60 %, PAPs > 50 mmHg, FA ou AG > 60 mL/m².","Remplacement valvulaire contre-indiqué si FE < 30 % ; la plastie reste envisageable.","IM grade I–II : simple surveillance ; autres cas non opérés : clinique et écho tous les 6 mois.","IM secondaire : traiter l'insuffisance cardiaque d'abord (médicaments, resynchronisation), clip ou chirurgie si échec.","Choix de prothèse : bioprothèse après 70 ans, mécanique avant 65 ans.","Le clip percutané ne se discute qu'en cas de haut risque ou de contre-indication chirurgicale."],"pitfalls":["Remplacer la valve avec une FE < 30 % : la chute postopératoire de FE expose à une dysfonction VG sévère.","Prescrire une antibioprophylaxie systématique : seule l'hygiène cutanée et dentaire est recommandée.","Attendre les symptômes chez un patient en FA ou avec retentissement VG : la chirurgie est déjà indiquée."],"src":"p. 219-223"},{"id":"233-sec-10","title":"Insuffisance aortique : définition, anatomie et physiopathologie","rank":"A","objectives":["233-obj-01","233-obj-05"],"content":"### Définition\n\nL'IA (régurgitation ou fuite aortique) est un **reflux de sang de l'aorte vers le VG en diastole**. Valvulopathie **peu fréquente**, dont la prévalence augmente avec l'âge.\n\n### Rappel anatomique\n\n- **Racine aortique** : anneau (insertion des cusps), sinus de Valsalva (les commissures s'insèrent à la jonction entre deux sinus), jonction sinotubulaire, aorte initiale.\n- Valve **tricuspide** (cusps antérodroite, antérogauche, non coronaire) ; **bicuspidie** chez 1–2 % de la population (fusion embryologique de 2 cusps), cusps souvent épaissies et rigides.\n\n### Physiopathologie [B]\n\nTrois acteurs : **VG, valve, circulation systémique (aorte)**. L'IA est longtemps bien tolérée.\n\n**IA chronique**\n- Volume de fuite lié à la taille de l'orifice régurgitant, à la **durée de la diastole** et au gradient diastolique aorte–VG.\n- **Surcharge mixte** du VG : **volumétrique** (volume régurgité → ↑ volume télédiastolique, précharge) et **barométrique** (volume d'éjection = normal + régurgité → ↑ pression systolique aortique, postcharge).\n- Loi de Laplace (T = P × r / 2e) : r ↑ par la régurgitation, P ↑ par la postcharge, e ↑ progressivement pour normaliser la contrainte → **hypertrophie excentrique**, plus marquée (dilatation et hypertrophie) que dans l'IM ; remodelage maladaptatif → destruction cardiomyocytaire, fibrose interstitielle.\n- Fonction systolique normale au début ; grande compliance → pressions de remplissage normales pendant des années malgré une forte dilatation ; puis baisse de la FE, ↑ des pressions de remplissage, IC d'effort puis de repos. VG très dilaté ou FE abaissée → remodelage possiblement **irréversible** après chirurgie.\n- Aorte : ↑ **PA systolique** (volume d'éjection, compliance aortique) et ↓ **PA diastolique** si fuite importante → ↑ pression pulsée → **hyperpulsatilité artérielle**.\n- Coronaires : perfusion surtout diastolique → ↓ ; IA sévère → « vol » coronarien diastolique → angor de repos ou d'effort, ischémie, fibrose.\n\n**IA aiguë**\n- Surtout **endocardite infectieuse** : fuite volumineuse brutale sur un VG non dilaté de compliance normale → élévation brutale des pressions de remplissage → AG, circulation pulmonaire → **OAP**.\n- Souvent **peu audible**.\n- Circulation coronaire particulièrement pénalisée (↑ contrainte diastolique, ↓ PA diastolique).","keyPoints":["IA = reflux diastolique aorte → VG ; valvulopathie peu fréquente, longtemps bien tolérée.","Surcharge mixte : volumétrique (précharge) et barométrique (postcharge) → hypertrophie excentrique plus marquée que dans l'IM.","Pression pulsée élargie (PAS élevée, PAD basse) → hyperpulsatilité artérielle.","La baisse de PAD compromet la perfusion coronaire : angor possible sans coronaropathie.","IA aiguë (endocardite) : VG non dilaté → OAP brutal, souffle parfois peu audible.","Un VG très dilaté ou une FE abaissée annoncent un remodelage irréversible."],"pitfalls":["Des pressions de remplissage normales n'excluent pas une IA chronique sévère très dilatée.","Le remodelage de l'IA est excentrique, pas concentrique comme dans le RA."],"src":"p. 224-227"},{"id":"233-sec-11","title":"Insuffisance aortique : étiologies","rank":"A","objectives":["233-obj-02"],"content":"Trois mécanismes selon la **mobilité des cusps** (normale, excessive, restreinte), parfois associés ; on cherche une lésion organique des cusps et/ou une dilatation de la racine aortique.\n\n| Type 1 : mouvement normal | Type 2 : prolapsus | Type 3 : restriction |\n|---|---|---|\n| Dilatation de la racine : idiopathique ; génétique (**Marfan**, Loeys-Dietz, Ehlers-Danlos) ; aortites (Takayasu, Horton, Behçet, spondylarthrite ankylosante, syphilis) ; bicuspidie ; dissection | Dystrophie ou dysplasie isolée ; **bicuspidie** ; endocardite ; syndrome de Laubry-Pezzi ; déchirure traumatique ; dissection | **RAA** ; toxicité médicamenteuse ; radiothérapie médiastinale |\n| Destruction/perforation : **endocardite** ; traumatisme ; fenestration congénitale ou acquise | | |\n\n### Type 1\n- Dilatation de l'**anneau** (rarement isolée) ou de la **racine** : prédominant sur anneau et sinus = **maladie annuloectasiante** (Marfan, Loeys-Dietz, Ehlers-Danlos, idiopathique), ou sur l'aorte initiale (bicuspidie, aortites). Risque de **rupture ou dissection aortique**.\n- Perforation/destruction d'une cusp : essentiellement l'**EI** (bord libre ou corps de la cusp), plus rarement traumatisme (cathétérisme), fenestrations (petites perforations des zones de coaptation).\n\n### Type 2 (fermeture sous le plan, dans la chambre de chasse)\n- Prolapsus isolé : valve tricuspide dystrophique (acquise) ou dysplasique (congénitale) ; fuite **excentrée**.\n- **Bicuspidie** : prolapsus de la cusp la plus grande (fusionnée).\n- Plus rare : déchirure traumatique, EI, CIV sous-aortique infundibulaire (**Laubry-Pezzi**).\n\n### Type 3 (fermeture au-dessus du plan, vers l'aorte)\n- **RAA** : rare en Occident, migrants (Maghreb, Asie, Afrique) ; épaississement et rétraction des bords libres → orifice central ; ± sténose (**maladie aortique**) ; prédomine sur la mitrale.\n- **Médicaments** : dérivés de l'ergot de seigle (antimigraineux), anorexigènes retirés (fenfluramine, dexfenfluramine, **benfluorex**), MDMA — toxicité sérotoninergique.\n- Carcinoïde (valves gauches rarement atteintes, sauf foramen ovale perméable ou métastases pulmonaires) ; radiothérapie médiastinale (lymphome, cancer du sein gauche).\n\n### IA aiguë\n**EI** (destruction, perforation, abcès de l'anneau), **dissection aortique** atteignant l'anneau, **traumatisme** (thorax fermé, décélération, cathétérisme).\n\n### IA sur prothèse\n- **Paraprothétique** : désinsertion septique (EI précoce ou tardive) ou aseptique (anneau fragilisé) ; une fuite minime précoce après RVA ou TAVI est possible hors sepsis, à signaler et surveiller.\n- **Intraprothétique** : dysfonction (thrombus bloquant une ailette, EI, dégénérescence de bioprothèse). Une IA minime est **normale** sur toute prothèse.","keyPoints":["Trois mécanismes : mouvement normal (racine dilatée, perforation), excessif (prolapsus), restreint (RAA, médicaments, radiothérapie).","Principales causes occidentales : dystrophie valvulaire, dilatation de l'aorte (maladie annuloectasiante → penser Marfan), bicuspidie, endocardite.","La maladie annuloectasiante expose à la dissection ou à la rupture aortique.","IA aiguë : endocardite surtout, dissection aortique, traumatisme.","Médicaments en cause : ergot de seigle, fenfluramine, dexfenfluramine, benfluorex, MDMA.","Une fuite minime est normale sur une prothèse valvulaire."],"pitfalls":["Devant une IA aiguë avec douleur thoracique ou AVC sans fièvre, penser à la dissection aortique.","Devant une maladie annuloectasiante, évoquer un syndrome de Marfan et dépister la famille."],"src":"p. 228-232"},{"id":"233-sec-12","title":"Insuffisance aortique : clinique et examens complémentaires","rank":"A","objectives":["233-obj-03","233-obj-04","233-obj-06"],"content":"### Clinique\n\n- Découverte le plus souvent **fortuite** (souffle) ou lors du bilan d'une maladie causale ; découverte au stade d'IC devenue rare.\n- Souvent **asymptomatique** ; dyspnée d'effort (NYHA), angor rare (fonctionnel, IA massive), asthénie ; signes de repos rares, tardifs, de mauvais pronostic.\n- **Souffle diastolique +++** au foyer aortique irradiant le long du **bord gauche du sternum**, mieux perçu penché en avant, en expiration bloquée ; **holodiastolique** si importante, **protomésodiastolique** si modérée.\n- Souffle systolique éjectionnel d'accompagnement (hyperdébit) fréquent ; **roulement de Flint** apexien (sténose mitrale fonctionnelle) ou galop = IA sévère.\n- Choc de pointe « en dôme », dévié en bas et à gauche.\n- **Signes périphériques** : hyperpulsatilité des pouls ++, battements du cou, oscillation de la tête, pulsatilité sous-unguéale ; **élargissement de la différentielle avec PAD abaissée ++** = IA sévère.\n\n### ECG et radiographie [B]\n\n- ECG parfois normal, rythme sinusal ; FA ou ESV = mauvais pronostic ; **HVG diastolique** (R amples en précordiales gauches, T positives), parfois systolique (sous-décalage de ST, T inversées).\n- Radio : petites IA sans signe ; IA volumineuses → ↑ index cardiothoracique ; aorte déroulée → débord de l'arc moyen droit.\n\n### Échocardiographie doppler [A]\n\n- **Confirme** l'IA (reflux diastolique aorte → VG en couleur) et exclut l'insuffisance pulmonaire.\n- **Quantifie** en 4 grades (combiner les méthodes) ; seuls les grades 3–4 imposent une surcharge volumétrique significative.\n\n| Grade | SOR (mm²) | Volume régurgité (mL) |\n|---|---|---|\n| 1 minime | < 10 | < 30 |\n| 2 minime à modérée | 10–19 | 30–44 |\n| 3 modérée à moyenne | 20–29 | 45–59 |\n| 4 sévère | ≥ 30 | ≥ 60 |\n\n- Critères indirects : hyperdébit dans la chambre de chasse **> 4 L/min/m²** ; dilatation diastolique du VG (grade ≥ 3) ; flux rétrograde télédiastolique dans l'isthme **> 20 cm/s**. Critères directs : **vena contracta**, **PISA** (SOR et volume).\n- **Retentissement** : diamètres télédiastolique/télésystolique (TM ou 2D, indexés), volumes, hypertrophie excentrique, **FEVG** (Simpson biplan ; > 50 % si compensée), pressions de remplissage, PAP → base des indications chez l'asymptomatique, avec l'aorte.\n- **Étiologie** : mobilité et aspect des cusps, tri/bicuspidie, végétations ou abcès, diamètres anneau/sinus/aorte ascendante (racine « piriforme » ou en « bulbe d'oignon » = annuloectasiante) ; bicuspidie → dilatation de l'aorte ascendante dans ~50 % des cas au-delà de la jonction sinotubulaire ; flap de dissection ; autres valves.\n- **ETO** si échogénicité insuffisante, pour l'aorte thoracique, ou suspicion d'EI ou de dissection.\n\n### Test d'effort [B]\n\nNon systématique, aide à la décision : standard, VO2 ou écho d'effort. Mauvaise tolérance : arrêt pour **dyspnée**, capacité **< 80–85 %** de la théorique, plafonnement du pouls d'O2, défaut de réserve contractile, troubles du rythme ventriculaire.\n\n### Autres [B]\n\n- Coronarographie de moins en moins utilisée (coroscanner) : hommes > 40 ans, femmes > 50 ans, facteurs de risque, coroscanner positif ou non concluant. Angiographie sus-sigmoïdienne exceptionnelle.\n- Scanner (disponible, irradiant) et **IRM** (non irradiante, gadolinium CI si insuffisance rénale sévère) : dimensions de l'aorte ascendante et suivi ; IRM : volumes VG, FEVG, volume régurgité.\n\n### Diagnostic différentiel\n\nInsuffisance pulmonaire (cardiopathie congénitale connue), double souffle (rupture d'un sinus aortique), souffle continu (canal artériel persistant, fistule coronarienne), frottement péricardique → l'écho tranche.","keyPoints":["Souffle diastolique au foyer aortique irradiant le long du bord gauche du sternum, mieux entendu penché en avant en expiration bloquée.","PAD abaissée et hyperpulsatilité artérielle signent une IA sévère.","IA sévère (grade 4) : SOR ≥ 30 mm², volume régurgité ≥ 60 mL, hyperdébit > 4 L/min/m², reflux isthmique > 20 cm/s.","L'écho évalue le VG (diamètres, FEVG > 50 % si compensée) et l'aorte ascendante, bases de l'indication opératoire.","Dans la bicuspidie, l'aorte ascendante est dilatée dans environ la moitié des cas.","Test d'effort anormal : arrêt pour dyspnée, capacité < 80–85 % de la théorique, troubles du rythme ventriculaire."],"pitfalls":["L'ECG ou la radiographie ne font pas le diagnostic d'IA : seule l'écho le permet.","Confondre le souffle systolique d'accompagnement de l'IA avec un RA : c'est un souffle d'hyperdébit.","Oublier la dissection ou l'endocardite : l'ETO s'impose quand elles sont suspectées."],"src":"p. 232-237"},{"id":"233-sec-13","title":"Insuffisance aortique : évolution, complications, surveillance et traitement médical","rank":"B","objectives":["233-obj-07","233-obj-12"],"content":"### Évolution\n\nPronostic lié au **retentissement VG** et à une éventuelle **dilatation aortique** (dissection, rupture).\n\n- IA chronique : faible surrisque d'EI. IA significative (grades 3–4) : longtemps asymptomatique ; les symptômes marquent un tournant ; lésions myocardiques possiblement irréversibles → **indication souvent posée chez l'asymptomatique** sur la dilatation VG ou la baisse de FEVG ; surveillance étroite.\n- Dilatation aortique : surveiller le diamètre **chaque année** en écho, IRM ou scanner de temps à autre. Bicuspidie : risque de dissection un peu accru mais faible par rapport au Marfan. **Marfan : dépistage familial** (1er degré) nécessaire ; proposé dans la bicuspidie (10 % de récurrence).\n- IA aiguë : évolution rapide, **OAP, mort subite** ; chirurgie précoce habituelle.\n\n### Complications\n\n- **Endocardite** : prophylaxie (hygiène buccodentaire) toujours ; **antibioprophylaxie seulement si antécédent d'EI, prothèse valvulaire ou cardiopathie cyanogène**.\n- IC gauche ou globale tardive (VG très dilaté, FE altérée) ; dans l'IA aiguë, IC sans dilatation ni baisse de FE.\n- Dissection ou rupture aortique.\n- Mort subite (rare) : trouble du rythme des formes évoluées ou rupture aortique.\n\n### Surveillance de l'IA chronique\n\nObjectifs : estimer le volume régurgité, suivre dilatation VG et FEVG, suivre l'aorte, prévenir l'EI.\n\n| Fuite | Rythme |\n|---|---|\n| Sévère | 1 à 2 fois par an |\n| Modérée à moyenne | Tous les 2 à 3 ans |\n\nContenu : clinique (symptômes, IC), **ECG**, **ETT**, test d'effort ou écho d'effort idéalement avec VO2 (au plus 1 fois par an si sévère), IRM ou scanner si dilatation aortique importante ou progressive, **surveillance dentaire 2 fois par an**. Téléconsultation possible en alternance chez l'asymptomatique ; symptômes → consultation présentielle rapide.\n\nIA aiguë (EI, dissection, traumatisme) : chirurgie **urgente si dissection**, parfois un peu différée si EI ou traumatisme selon la tolérance.\n\n### Traitement médical\n\n- **Aucun médicament n'a démontré de bénéfice** ; les IEC ne sont pas recommandés pour prévenir le remodelage ou l'IC dans l'IA modérée à sévère.\n- IA sévère avec IC congestive : diurétiques ± IEC ou autre vasodilatateur **en attendant la chirurgie** ; **bêtabloquants classiquement contre-indiqués** (allongent la diastole, aggravent la fuite).\n- L'amélioration sous traitement ne doit **pas retarder la chirurgie**.\n- **Marfan** (et par extension dilatation aortique) : **bêtabloquants** = traitement validé pour protéger l'aorte ; **ARA2 seulement si intolérance** aux bêtabloquants.\n- **Sport de compétition contre-indiqué** si IA sévère ; sport de loisir d'endurance modéré encouragé.\n\n### Prophylaxie de l'EI\n\nPas d'antibioprophylaxie systématique sur valve native ; antibioprophylaxie si antécédent d'EI, prothèse ou cardiopathie cyanogène ; hygiène et **examen dentaire tous les 6 mois**.\n\n> **Inacceptable** : traiter une IA symptomatique uniquement par des médicaments de l'IC ; prescrire des antibiotiques avant tout soin dentaire ; ne pas référer une IA sévère, symptomatique ou non.","keyPoints":["Le pronostic dépend du retentissement VG et du risque de dissection ou rupture aortique.","IA sévère : suivi 1 à 2 fois par an (clinique, ECG, ETT ± test d'effort) ; IA modérée : tous les 2 à 3 ans.","Aucun traitement médicamenteux n'est efficace sur l'IA ; les IEC ne préviennent pas le remodelage.","Bêtabloquants : contre-indiqués dans l'IA en IC (allongent la diastole) mais validés dans le Marfan pour protéger l'aorte ; ARA2 si intolérance.","Antibioprophylaxie uniquement si antécédent d'EI, prothèse ou cardiopathie cyanogène ; dentiste 2 fois par an.","Marfan : dépistage familial obligatoire ; bicuspidie : 10 % de récurrence familiale.","Sport de compétition interdit si IA sévère."],"pitfalls":["Repousser la chirurgie parce que les signes d'IC ont régressé sous diurétiques.","Donner des bêtabloquants à une IA sévère décompensée hors contexte de Marfan.","Prescrire une antibioprophylaxie dentaire systématique à une IA sur valve native."],"src":"p. 237-240"},{"id":"233-sec-14","title":"Insuffisance aortique : traitement chirurgical, indications et TAVI","rank":"B","objectives":["233-obj-08","233-obj-09","233-obj-10"],"content":"### Modalités\n\n- IA isolée : **remplacement valvulaire aortique (RVA)** par prothèse mécanique ou biologique ; choix discuté avec le patient, décision finale au patient sauf contre-indication claire. Bioprothèse généralement **après 60–65 ans** ou si désir de grossesse ; prévenir d'une **réopération vers 10 ans** (dégénérescence).\n- IA avec dilatation aortique : RVA + remplacement de l'aorte ascendante par tube avec **réimplantation des coronaires (Bentall)**, ou tube sus-coronaire.\n- **Plastie aortique conservatrice** (Tirone David, Yacoub) : chirurgiens entraînés, feuillets normaux ou bicuspidie peu altérée avec racine dilatée, certains prolapsus ; remplacement de l'aorte initiale avec réimplantation coronaire.\n- Autres : **Ross** (autogreffe pulmonaire en position aortique + bioprothèse ou homogreffe en pulmonaire), **Ozaki** (bioprothèse taillée dans le péricarde du patient).\n\n### Indications (cliniques et échographiques)\n\n| Situation | Indication |\n|---|---|\n| IA sévère **symptomatique** (dyspnée, angor, IC) | Formelle |\n| IA sévère asymptomatique : **DTS > 50 mm ou > 25 mm/m²**, ou **FEVG ≤ 50 %** | Formelle |\n| IA sévère asymptomatique, chirurgie à bas risque : **DTS > 20 mm/m²** ou **FEVG ≤ 55 %** | Devrait être posée |\n| IA sévère et autre chirurgie cardiaque (pontage, aorte, autre valve) | Formelle |\n| Aorte ascendante **≥ 50 mm si Marfan** (quel que soit le grade) | Formelle |\n| Aorte ascendante **≥ 55 mm** | Devrait être posée |\n| Aorte **≥ 45 mm si Marfan avec facteurs de risque** ; **≥ 50 mm si bicuspidie avec facteurs de risque** | Devrait être posée |\n| Chirurgie pour IA sévère : remplacer l'aorte si **≥ 45 mm** | Devrait être posée |\n\nFacteurs de risque aortiques : antécédent familial ou personnel de dissection, IA ou IM sévère, désir de grossesse, **HTA non contrôlée**, progression **> 3 mm/an**.\n\n- **IA aiguë sévère** : indication formelle et **urgente** en cas d'IC.\n- **EI** (valve native ou prothèse) : chirurgie non systématique, discutée si sepsis non maîtrisé, IC ou risque embolique majeur (végétations très volumineuses).\n\n### Bilan préopératoire\n\nBiologie ; imagerie coronaire (coroscanner ou coronarographie) ; angioscanner ou ARM aortique si dilatation ; échodoppler des TSA ; spirométrie si suspicion respiratoire ; foyers dentaires (panoramique ou cone beam) et ORL (radiographie des sinus) ; comorbidités (rein, poumon) ; avis gériatrique si patient fragile **> 75 ans**.\n\n### Résultats\n\nMortalité périopératoire **1–3 %** pour un RVA isolé chez l'asymptomatique ; **3–10 %** si symptomatique, chirurgie de l'aorte ou pontages associés.\n\n### TAVI dans l'IA\n\nParfois proposé en cas de très haut risque ou de contre-indication chirurgicale, **en l'absence d'EI** ; prothèses non conçues pour cette indication (ancrage sur les calcifications) → risque de **migration** ; solution très marginale.","keyPoints":["IA sévère symptomatique : chirurgie formelle ; asymptomatique : DTS > 50 mm (ou > 25 mm/m²) ou FEVG ≤ 50 %.","À bas risque chirurgical, opérer dès DTS > 20 mm/m² ou FEVG ≤ 55 %.","Aorte ascendante : opérer à 55 mm, 50 mm si Marfan, 45 mm si Marfan à risque, 50 mm si bicuspidie à risque.","Dilatation aortique associée : Bentall (tube + réimplantation des coronaires) ou tube sus-coronaire ; plastie conservatrice possible chez certains.","Bioprothèse après 60–65 ans ou désir de grossesse, réopération vers 10 ans.","Mortalité 1–3 % (RVA isolé asymptomatique) à 3–10 % (symptomatique, aorte, pontages).","Le TAVI n'est pas un traitement de l'IA : exceptionnel, hors endocardite, risque de migration."],"pitfalls":["Attendre les symptômes dans l'IA sévère : la dilatation VG ou la baisse de FEVG suffisent à opérer.","Oublier le diamètre aortique : il peut à lui seul indiquer la chirurgie quel que soit le grade de la fuite.","Proposer un TAVI en cas d'endocardite : il est exclu."],"src":"p. 240-244"}],"essentials":[{"id":"233-ess-01","rank":"A","text":"Le rétrécissement aortique est la valvulopathie la plus fréquente, essentiellement dégénératif après 65 ans.","src":"p. 195"},{"id":"233-ess-02","rank":"A","text":"La bicuspidie aortique touche 1 à 2 % de la population et est la première cause de RA entre 30 et 65 ans.","src":"p. 195-197"},{"id":"233-ess-03","rank":"A","text":"La bicuspidie est souvent associée à un anévrisme de l'aorte ascendante, à rechercher, et impose un dépistage des apparentés du 1er degré.","src":"p. 198"},{"id":"233-ess-04","rank":"A","text":"Les trois maîtres symptômes du RA sont la dyspnée, l'angor et la syncope d'effort ; leur apparition impose le traitement.","src":"p. 199"},{"id":"233-ess-05","rank":"A","text":"Le souffle du RA est mésosystolique, éjectionnel, râpeux, maximal au 2e espace intercostal droit, irradiant aux carotides, avec B2 aboli si serré.","src":"p. 199"},{"id":"233-ess-06","rank":"A","text":"L'ETT est l'examen clé de toute valvulopathie : diagnostic, sévérité, retentissement et atteintes associées.","src":"p. 200"},{"id":"233-ess-07","rank":"A","text":"Un RA serré à bas gradient se définit par un volume d'éjection systolique ≤ 35 mL/m² ; l'écho sous dobutamine distingue RA serré et pseudosténose.","src":"p. 202"},{"id":"233-ess-08","rank":"B","text":"L'ECG du RA serré montre le plus souvent une HVG de type surcharge systolique, mais son absence n'exclut pas le diagnostic.","src":"p. 200"},{"id":"233-ess-09","rank":"A","text":"Le cathétérisme n'a presque plus de place dans le RA ; la coronarographie préopératoire reste nécessaire chez l'homme > 40 ans, la femme ménopausée, en cas de facteurs de risque, d'angor ou d'IC.","src":"p. 203"},{"id":"233-ess-10","rank":"B","text":"Le scanner cardiaque est systématique avant TAVI pour mesurer l'anneau, le culot aortique, la distance des ostia coronaires et les axes vasculaires.","src":"p. 204"},{"id":"233-ess-11","rank":"B","text":"La FA est mal tolérée dans le RA car la perte de la systole atriale précipite l'insuffisance cardiaque.","src":"p. 197"},{"id":"233-ess-12","rank":"B","text":"Le syndrome de Heyde associe RA, angiodysplasies intestinales avec anémie ferriprive et anomalie acquise du facteur von Willebrand.","src":"p. 205"},{"id":"233-ess-13","rank":"B","text":"Tout RA serré symptomatique doit être traité par RVA ou TAVI, pratiquement sans limite d'âge si l'état général le permet.","src":"p. 206"},{"id":"233-ess-14","rank":"B","text":"Le TAVI est recommandé chez les patients inopérables ou à risque quel que soit l'âge et en 1re intention après 75 ans si la voie fémorale est possible.","src":"p. 205"},{"id":"233-ess-15","rank":"A","text":"L'insuffisance mitrale est un reflux systolique du VG vers l'atrium gauche par défaut d'étanchéité de la valve.","src":"p. 209"},{"id":"233-ess-16","rank":"A","text":"La classification de Carpentier distingue le type I (jeu normal), le type II (prolapsus) et le type III (restriction, IIIa systolo-diastolique, IIIb systolique).","src":"p. 209-210"},{"id":"233-ess-17","rank":"A","text":"L'IM dystrophique par prolapsus (Barlow ou dégénérescence fibroélastique) est la cause la plus fréquente de fuite mitrale sévère.","src":"p. 211-212"},{"id":"233-ess-18","rank":"A","text":"L'IM secondaire (fonctionnelle) survient sur valve saine par dilatation ou dysfonction du VG (ischémique ou non) ou par dilatation de l'anneau sur AG dilaté.","src":"p. 211-213"},{"id":"233-ess-19","rank":"A","text":"Le souffle d'IM est holosystolique, apexo-axillaire, en jet de vapeur, irradiant à l'aisselle, sans renforcement après une diastole longue.","src":"p. 214"},{"id":"233-ess-20","rank":"A","text":"Dans le prolapsus mitral, un clic mésosystolique précède un souffle méso-télésystolique ou télésystolique.","src":"p. 215"},{"id":"233-ess-21","rank":"A","text":"L'ETO est obligatoire pour le diagnostic d'IM sur endocardite et précieuse pour planifier une plastie mitrale.","src":"p. 217"},{"id":"233-ess-22","rank":"B","text":"Dans l'IM la FEVG est surestimée car le VG est déchargé : on parle de dysfonction dès 60 %.","src":"p. 210"},{"id":"233-ess-23","rank":"A","text":"L'IM aiguë (rupture de cordage, rupture de pilier post-infarctus, endocardite, traumatisme) est une urgence vitale, pouvant donner un OAP unilatéral.","src":"p. 213-214"},{"id":"233-ess-24","rank":"B","text":"La plastie mitrale est le traitement idéal de l'IM par prolapsus : moins de dysfonction VG, moindre morbimortalité et moindre risque d'endocardite que le remplacement.","src":"p. 220"},{"id":"233-ess-25","rank":"B","text":"Le remplacement valvulaire mitral est contre-indiqué si la FE est inférieure à 30 %, la FE chutant de 10 à 15 % en postopératoire.","src":"p. 222"},{"id":"233-ess-26","rank":"B","text":"L'IM secondaire se traite d'abord par le traitement de l'insuffisance cardiaque (médicaments, resynchronisation si QRS larges) ; clip ou chirurgie en cas d'échec.","src":"p. 220-223"},{"id":"233-ess-27","rank":"B","text":"La réparation bord à bord percutanée (clip) ne se discute qu'en cas de haut risque ou de contre-indication chirurgicale, en Heart Team.","src":"p. 221"},{"id":"233-ess-28","rank":"A","text":"L'insuffisance aortique est un reflux diastolique de l'aorte vers le VG ; valvulopathie peu fréquente, longtemps asymptomatique.","src":"p. 224"},{"id":"233-ess-29","rank":"A","text":"Les étiologies de l'IA se classent selon la mobilité des cusps : normale (racine dilatée, perforation), excessive (prolapsus) ou restreinte (RAA, médicaments, radiothérapie).","src":"p. 228"},{"id":"233-ess-30","rank":"A","text":"Dans les pays occidentaux, les principales causes d'IA sont la dystrophie valvulaire, la dilatation de l'aorte (maladie annuloectasiante, Marfan), la bicuspidie et l'endocardite.","src":"p. 243"},{"id":"233-ess-31","rank":"A","text":"L'IA aiguë est le plus souvent due à une endocardite, plus rarement à une dissection aortique ou à un traumatisme ; elle est très symptomatique et conduit à la chirurgie.","src":"p. 232-239"},{"id":"233-ess-32","rank":"A","text":"Le souffle d'IA est diastolique, au foyer aortique, irradiant le long du bord gauche du sternum, mieux perçu penché en avant en expiration bloquée.","src":"p. 232-233"},{"id":"233-ess-33","rank":"A","text":"L'élargissement de la pression pulsée avec PAD abaissée et l'hyperpulsatilité artérielle traduisent une IA sévère.","src":"p. 233"},{"id":"233-ess-34","rank":"B","text":"L'IA impose une surcharge mixte, volumétrique et barométrique, avec hypertrophie excentrique du VG plus marquée que dans l'IM.","src":"p. 226-227"},{"id":"233-ess-35","rank":"B","text":"Aucun médicament n'a démontré de bénéfice dans l'IA ; les bêtabloquants sont contre-indiqués dans l'IA décompensée mais validés dans le Marfan pour protéger l'aorte.","src":"p. 239"},{"id":"233-ess-36","rank":"B","text":"Dans l'IA, l'indication opératoire peut être portée sur le seul diamètre de l'aorte ascendante, quel que soit le grade de la fuite.","src":"p. 240-242"},{"id":"233-ess-37","rank":"A","text":"L'antibioprophylaxie de l'endocardite n'est plus systématique sur valve native : elle est réservée aux antécédents d'EI, aux prothèses valvulaires et aux cardiopathies cyanogènes.","src":"p. 238-239"},{"id":"233-ess-38","rank":"A","text":"Tout patient valvulaire symptomatique, avec souffle modifié ou pour son suivi annuel, doit être adressé au cardiologue ; une fièvre doit faire évoquer l'endocardite.","src":"p. 207"}],"numbers":[{"id":"233-num-01","rank":"B","label":"Gradient VG–aorte normal pendant l'éjection","value":"2 à 5 mmHg","src":"p. 196"},{"id":"233-num-02","rank":"A","label":"Gradient moyen VG–aorte définissant un RA serré","value":"> 40 mmHg","src":"p. 196-201"},{"id":"233-num-03","rank":"A","label":"Vmax transaortique du RA serré","value":"> 4 m/s (normale ≈ 1 m/s ; vitesses augmentées dès > 2,5 m/s)","src":"p. 201"},{"id":"233-num-04","rank":"A","label":"Surface aortique normale","value":"2 à 3,5 cm²","src":"p. 202"},{"id":"233-num-05","rank":"A","label":"Surface aortique du RA serré","value":"< 1 cm² ou < 0,6 cm²/m²","src":"p. 202"},{"id":"233-num-06","rank":"A","label":"Surface aortique du RA critique","value":"≤ 0,75 cm² ou < 0,4 cm²/m²","src":"p. 202"},{"id":"233-num-07","rank":"A","label":"Bas débit définissant le RA serré à bas gradient","value":"Volume d'éjection systolique ≤ 35 mL/m²","src":"p. 202"},{"id":"233-num-08","rank":"A","label":"Prévalence de la bicuspidie aortique","value":"1 à 2 % de la population générale","src":"p. 195"},{"id":"233-num-09","rank":"A","label":"Âge charnière des étiologies du RA","value":"Bicuspidie avant 65–70 ans, dégénératif après","src":"p. 198"},{"id":"233-num-10","rank":"A","label":"Intensité du souffle de RA associée à un frémissement","value":"4/6","src":"p. 199"},{"id":"233-num-11","rank":"B","label":"Score calcique valvulaire en faveur d'un RA serré","value":"> 2 000 UA chez l'homme, > 1 200 UA chez la femme","src":"p. 204"},{"id":"233-num-12","rank":"A","label":"Âge imposant une coronarographie préopératoire (RA)","value":"Homme > 40 ans ; femme ménopausée","src":"p. 203"},{"id":"233-num-13","rank":"B","label":"Seuils d'intervention du RA serré asymptomatique","value":"Vmax > 5 m/s ou FEVG < 55 %","src":"p. 206"},{"id":"233-num-14","rank":"B","label":"Âge de 1re intention du TAVI","value":"> 75 ans quel que soit le risque chirurgical, si voie fémorale possible","src":"p. 205"},{"id":"233-num-15","rank":"B","label":"Bioprothèse aortique : âge et durabilité","value":"Indiquée > 65 ans ; dégénérescence en 10–15 ans","src":"p. 205"},{"id":"233-num-16","rank":"B","label":"Dysfonction systolique du RA posant un problème opératoire","value":"FE < 35 %","src":"p. 206"},{"id":"233-num-17","rank":"B","label":"Seuil de dysfonction VG dans l'IM (FEVG surestimée)","value":"FEVG < 60 %","src":"p. 210"},{"id":"233-num-18","rank":"A","label":"Retentissement de l'IM justifiant la correction","value":"DTS VG > 40 mm et/ou FEVG < 60 % ; AG ≥ 60 mL/m² ; PAPs ≥ 50 mmHg","src":"p. 217-218"},{"id":"233-num-19","rank":"B","label":"HTP post-capillaire de l'IM au cathétérisme","value":"PAPO > 15 mmHg avec onde V","src":"p. 211"},{"id":"233-num-20","rank":"A","label":"Grades de l'IM primaire (SOR / volume régurgité)","value":"I < 20 mm² / < 30 mL ; II 20–29 / 30–44 ; III 30–39 / 45–59 ; IV ≥ 40 mm² / ≥ 60 mL","src":"p. 218"},{"id":"233-num-21","rank":"A","label":"Seuil de sévérité de l'IM secondaire","value":"SOR ≥ 30 mm²","src":"p. 218"},{"id":"233-num-22","rank":"A","label":"Anneau tricuspide imposant une annuloplastie associée","value":"> 40 mm en coupe apicale 4 cavités","src":"p. 218"},{"id":"233-num-23","rank":"B","label":"FE contre-indiquant le remplacement valvulaire mitral","value":"FE < 30 % (chute postopératoire de 10–15 %)","src":"p. 222"},{"id":"233-num-24","rank":"B","label":"Choix de prothèse mitrale selon l'âge","value":"Bioprothèse après 70 ans ; mécanique avant 65 ans","src":"p. 221"},{"id":"233-num-25","rank":"B","label":"Rythme de surveillance de l'IM importante non opérée","value":"Clinique et échographie tous les 6 mois","src":"p. 222"},{"id":"233-num-26","rank":"A","label":"Grades de l'IA (SOR / volume régurgité)","value":"1 < 10 mm² / < 30 mL ; 2 10–19 / 30–44 ; 3 20–29 / 45–59 ; 4 ≥ 30 mm² / ≥ 60 mL","src":"p. 234"},{"id":"233-num-27","rank":"A","label":"Critères indirects d'IA sévère","value":"Hyperdébit > 4 L/min/m² ; flux rétrograde isthmique télédiastolique > 20 cm/s","src":"p. 234"},{"id":"233-num-28","rank":"B","label":"Dilatation de l'aorte ascendante dans la bicuspidie","value":"Environ 50 % des cas ; récurrence familiale 10 %","src":"p. 236-238"},{"id":"233-num-29","rank":"B","label":"Capacité d'effort témoignant d'une mauvaise tolérance de l'IA","value":"< 80–85 % de la théorique","src":"p. 236"},{"id":"233-num-30","rank":"B","label":"Âge de coronarographie préopératoire dans l'IA","value":"Hommes > 40 ans, femmes > 50 ans","src":"p. 236"},{"id":"233-num-31","rank":"B","label":"Rythme de suivi de l'IA","value":"1 à 2 fois/an si sévère ; tous les 2 à 3 ans si modérée à moyenne ; dentiste 2 fois/an","src":"p. 239"},{"id":"233-num-32","rank":"B","label":"Indication formelle dans l'IA sévère asymptomatique","value":"DTS > 50 mm ou > 25 mm/m², ou FEVG ≤ 50 %","src":"p. 240"},{"id":"233-num-33","rank":"B","label":"Indication à bas risque chirurgical dans l'IA sévère asymptomatique","value":"DTS > 20 mm/m² ou FEVG ≤ 55 %","src":"p. 240"},{"id":"233-num-34","rank":"B","label":"Diamètres aortiques opératoires","value":"≥ 55 mm ; ≥ 50 mm si Marfan ; ≥ 45 mm si Marfan à risque ; ≥ 50 mm si bicuspidie à risque ; remplacer l'aorte ≥ 45 mm lors de la chirurgie de l'IA","src":"p. 240-241"},{"id":"233-num-35","rank":"B","label":"Progression aortique = facteur de risque","value":"> 3 mm/an","src":"p. 240-241"},{"id":"233-num-36","rank":"B","label":"Bioprothèse aortique dans l'IA","value":"Après 60–65 ans ; réopération vers 10 ans","src":"p. 240"},{"id":"233-num-37","rank":"B","label":"Mortalité périopératoire du RVA","value":"1–3 % (isolé, asymptomatique) ; 3–10 % (symptomatique, aorte ou pontages)","src":"p. 242"},{"id":"233-num-38","rank":"B","label":"FEVG des IA compensées","value":"> 50 %","src":"p. 235"}],"mnemonics":[{"id":"233-mn-01","rank":"A","title":"Les trois symptômes d'effort du RA","mnemonic":"DAS : le RA « Dépasse À Souffle »","expansion":"- **D** : Dyspnée d'effort\n- **A** : Angor d'effort\n- **S** : Syncope d'effort\n\nTous trois surviennent **à l'effort** et marquent la cassure évolutive du RA.","src":"p. 199"},{"id":"233-mn-02","rank":"A","title":"Critères échographiques du RA serré","mnemonic":"4 – 40 – 1 : compte à rebours du RA serré","expansion":"- **4** : Vmax > 4 m/s\n- **40** : gradient moyen VG–aorte > 40 mmHg\n- **1** : surface aortique < 1 cm² (ou < 0,6 cm²/m²)","src":"p. 202"},{"id":"233-mn-03","rank":"B","title":"Opérer un RA serré asymptomatique","mnemonic":"FÊTE : quand le RA asymptomatique fait la FÊTE, on opère","expansion":"- **F** : FEVG < 55 %\n- **Ê** : Épreuve d'effort anormale\n- **T** : Très serré (Vmax > 5 m/s)\n- **E** : Évolution rapide de la sténose lors de la surveillance","src":"p. 206"},{"id":"233-mn-04","rank":"B","title":"Complications du RA","mnemonic":"MICHÉE + FA","expansion":"- **M** : Mort subite (surtout RA serré symptomatique)\n- **I** : Insuffisance cardiaque\n- **C** : Conduction (troubles conductifs)\n- **H** : Heyde (anémie ferriprive par angiodysplasies + anomalie du facteur von Willebrand)\n- **É** : Endocardite (rare)\n- **E** : Embolies calcaires (cérébrales, rénales, coronaires, rétiniennes)\n- **+ FA** : fibrillation atriale mal tolérée (et hyperexcitabilité ventriculaire, rare)","src":"p. 204-205"},{"id":"233-mn-05","rank":"A","title":"Classification de Carpentier","mnemonic":"1 dans le plan, 2 au-dessus, 3 en dessous","expansion":"- **Type 1** : feuillets restent **dans le plan** de l'anneau, jeu normal (perforation, fente, IM atriale par dilatation de l'anneau)\n- **Type 2** : un feuillet **dépasse au-dessus** du plan vers l'AG, jeu exagéré (prolapsus dystrophique)\n- **Type 3** : feuillets **retenus en dessous** dans le ventricule, jeu restreint (IIIa systolo-diastolique : RAA, radiothérapie, médicaments ; IIIb systolique : IM secondaire)","src":"p. 209-210"},{"id":"233-mn-06","rank":"A","title":"Causes d'IM aiguë","mnemonic":"CPTE : « le Cœur Pète Trop vitE »","expansion":"- **C** : rupture de Cordages (dégénérescence myxoïde ou fibroélastique, endocardite, traumatisme)\n- **P** : Pilier (rupture ou dysfonction ischémique, restriction aiguë sur akinésie post-infarctus)\n- **T** : Traumatisme thoracique\n- **E** : Endocardite (perforation)","src":"p. 213-214"},{"id":"233-mn-07","rank":"B","title":"Opérer une IM primaire importante asymptomatique","mnemonic":"DFPA = « Deux Fois Par An » (le rythme de surveillance sinon)","expansion":"- **D** : DTS du VG > 40 mm (avec rupture de cordage)\n- **F** : FEVG < 60 %\n- **P** : PAP systolique > 50 mmHg au repos\n- **A** : Atrium gauche > 60 mL/m² ou fibrillation Atriale (même paroxystique)\n\nEn l'absence de ces signes : surveillance clinique et échographique **deux fois par an** (tous les 6 mois).","src":"p. 222"},{"id":"233-mn-08","rank":"A","title":"Aortites responsables d'IA par dilatation de la racine","mnemonic":"THBSS : « Ta Horde Boit Sans Soif »","expansion":"- **T** : Takayasu\n- **H** : Horton\n- **B** : Behçet\n- **S** : Spondylarthrite ankylosante\n- **S** : Syphilis\n\nÀ côté des causes génétiques (Marfan, Loeys-Dietz, Ehlers-Danlos), de la bicuspidie, de la dissection et de la dilatation idiopathique.","src":"p. 228-229"},{"id":"233-mn-09","rank":"B","title":"Facteurs de risque abaissant le seuil aortique (Marfan 45 mm, bicuspidie 50 mm)","mnemonic":"« Hé ! Dis, Petit, Il Grossit »","expansion":"- **H** : HTA systémique non contrôlée\n- **D** : Dissection aortique dans les antécédents familiaux ou personnels\n- **P** : Progression du diamètre > 3 mm/an\n- **I** : IA ou IM sévère\n- **G** : Grossesse désirée","src":"p. 240-241"},{"id":"233-mn-10","rank":"A","title":"Bilan préopératoire d'une valvulopathie","mnemonic":"Les 5 C : Cœur, Cou, Crocs, Comorbidités, Cheveux blancs","expansion":"- **Cœur** : imagerie des coronaires (coronarographie ou coroscanner)\n- **Cou** : échodoppler des troncs supra-aortiques\n- **Crocs** : foyers infectieux dentaires et ORL (panoramique dentaire, radiographie des sinus)\n- **Comorbidités** : fonction rénale, pathologie pulmonaire\n- **Cheveux blancs** : avis gériatrique chez le sujet très âgé pour peser le rapport bénéfice/risque","src":"p. 206-221"},{"id":"233-mn-11","rank":"A","title":"Antibioprophylaxie de l'endocardite : les trois seules situations","mnemonic":"APC : « Antécédent, Prothèse, Cyanogène »","expansion":"- **A** : Antécédent d'endocardite infectieuse\n- **P** : Prothèse valvulaire\n- **C** : Cardiopathie cyanogène\n\nSur valve native (IM, IA) : pas d'antibioprophylaxie systématique, mais hygiène buccodentaire et examen dentaire tous les 6 mois.","src":"p. 238-240"}]},"questions":[{"id":"233-qcm-001","type":"QRM","rank":"A","objective":"233-obj-01","tags":["définition","épidémiologie"],"difficulty":1,"stem":"Concernant le rétrécissement aortique (RA), quelles propositions sont exactes ?","options":[{"t":"C'est la valvulopathie la plus fréquemment rencontrée en pratique.","ok":true,"why":"Le RA est décrit comme la valvulopathie la plus fréquente."},{"t":"Il s'agit toujours d'une atteinte congénitale de la valve.","ok":false,"why":"La cause dominante chez le sujet âgé est dégénérative, pas congénitale."},{"t":"L'obstacle siège le plus souvent sur la valve elle-même.","ok":true,"why":"L'obstacle à l'éjection du VG est le plus souvent valvulaire."},{"t":"Un obstacle sous-aortique dynamique des cardiomyopathies obstructives peut mimer un RA.","ok":true,"why":"Les obstacles dynamiques des cardiomyopathies obstructives sont un diagnostic différentiel classique."},{"t":"Le RA est exceptionnel après 65 ans.","ok":false,"why":"C'est au contraire la tranche d'âge où le RA dégénératif est le plus fréquent."}],"explanation":"Le RA est l'atteinte valvulaire la plus fréquente, avec un obstacle qui siège en général sur la valve aortique elle-même ; il faut distinguer les rares obstacles supra- ou sous-valvulaires, dont l'obstruction dynamique des cardiomyopathies obstructives.","src":"p. 195"},{"id":"233-qru-001","type":"QRU","rank":"A","objective":"233-obj-01","tags":["définition","clinique"],"difficulty":1,"stem":"Quel gradient moyen VG–aorte définit un RA serré à l'échocardiographie ?","options":[{"t":"> 10 mmHg","ok":false,"why":"Ce gradient reste très en deçà du seuil retenu pour un RA serré."},{"t":"> 20 mmHg","ok":false,"why":"Insuffisant pour parler de RA serré."},{"t":"> 40 mmHg","ok":true,"why":"Un gradient moyen supérieur à 40 mmHg définit le RA serré."},{"t":"> 60 mmHg","ok":false,"why":"Ce chiffre n'est pas le seuil retenu, même s'il peut être atteint dans des formes très serrées."},{"t":"Il n'existe pas de seuil de gradient utilisé en pratique.","ok":false,"why":"Le gradient moyen est au contraire un critère central de sévérité."}],"explanation":"Le gradient moyen VG–aorte normal est de 2 à 5 mmHg ; il s'élève avec la sévérité de l'obstacle, et un gradient moyen supérieur à 40 mmHg définit conventionnellement un RA serré.","src":"p. 196"},{"id":"233-qcm-003","type":"QRM","rank":"A","objective":"233-obj-05","tags":["physiopathologie"],"difficulty":2,"stem":"À propos de l'hypertrophie ventriculaire gauche (VG) au cours du RA, quelles affirmations sont vraies ?","options":[{"t":"Elle est concentrique et vise à normaliser la contrainte pariétale.","ok":true,"why":"L'hypertrophie concentrique compense l'élévation de postcharge selon la loi de Laplace."},{"t":"Elle permet le plus souvent de conserver une FEVG normale pendant de nombreuses années.","ok":true,"why":"Tant que l'hypertrophie compense la surcharge, la fonction systolique globale reste longtemps préservée."},{"t":"Une FEVG normale élimine formellement un RA serré.","ok":false,"why":"La FEVG peut rester normale malgré un RA serré : elle ne permet pas d'exclure la sévérité."},{"t":"La fibrose myocardique associée peut limiter la récupération après remplacement valvulaire.","ok":true,"why":"Une ischémie relative du myocarde hypertrophié favorise une fibrose parfois incomplètement réversible."},{"t":"Cette hypertrophie est toujours excentrique, comme dans l'insuffisance aortique.","ok":false,"why":"C'est l'inverse : l'hypertrophie du RA est concentrique, l'IA donne une hypertrophie excentrique."}],"explanation":"La surcharge de pression du RA entraîne une hypertrophie concentrique qui normalise la contrainte pariétale et préserve longtemps la FEVG ; une fibrose myocardique associée peut cependant rendre la récupération partielle après la correction de l'obstacle.","src":"p. 196","trap":"Une FEVG normale n'élimine pas un RA serré."},{"id":"233-qru-002","type":"QRU","rank":"A","objective":"233-obj-05","tags":["physiopathologie"],"difficulty":2,"stem":"Pourquoi le passage en fibrillation atriale (FA) est-il particulièrement mal toléré dans le RA serré ?","options":[{"t":"Parce que la FA accélère toujours la fréquence cardiaque de façon dangereuse.","ok":false,"why":"La tachycardie n'est pas le mécanisme principal invoqué ici."},{"t":"Parce que la systole atriale devient indispensable au remplissage d'un VG hypertrophié et peu compliant.","ok":true,"why":"La dysfonction diastolique rend le remplissage dépendant de la contraction atriale, perdue en FA."},{"t":"Parce que la FA provoque systématiquement un arrêt cardiaque.","ok":false,"why":"Ce n'est pas le mécanisme décrit ; la FA décompense la fonction cardiaque sans provoquer un arrêt systématique."},{"t":"Parce que la FA améliore le remplissage diastolique.","ok":false,"why":"C'est l'inverse : la FA supprime la contribution atriale au remplissage."},{"t":"Parce que la FA fait chuter la postcharge du VG.","ok":false,"why":"La FA n'agit pas sur la postcharge, mais sur le remplissage diastolique."}],"explanation":"La dysfonction diastolique du VG hypertrophié rend la contraction atriale indispensable au remplissage ; sa perte lors du passage en FA précipite une poussée d'insuffisance cardiaque.","src":"p. 197"},{"id":"233-qcm-005","type":"QRM","rank":"A","objective":"233-obj-02","tags":["étiologie","épidémiologie"],"difficulty":1,"stem":"Concernant les étiologies du RA, quelles propositions sont exactes ?","options":[{"t":"La bicuspidie est l'étiologie la plus fréquente entre 30 et 65 ans.","ok":true,"why":"Avant 65–70 ans, la bicuspidie domine parmi les causes de RA."},{"t":"Le RA dégénératif (maladie de Mönckeberg) devient prédominant après 65–70 ans.","ok":true,"why":"Après cet âge charnière, le RA dégénératif calcifié est la cause la plus fréquente."},{"t":"Le RA post-rhumatismal est aujourd'hui la cause la plus fréquente en France.","ok":false,"why":"Le RA post-rhumatismal est devenu rare et se voit surtout chez les migrants."},{"t":"La bicuspidie touche environ 1 à 2 % de la population.","ok":true,"why":"C'est la prévalence rapportée pour cette anomalie valvulaire congénitale."},{"t":"Le RA post-rhumatismal s'associe classiquement à une atteinte isolée de la valve aortique.","ok":false,"why":"Il s'accompagne le plus souvent d'une insuffisance aortique et d'une atteinte mitrale associée."}],"explanation":"Deux étiologies dominent le RA : la bicuspidie avant 65–70 ans et le RA dégénératif calcifié après cet âge ; le RA post-rhumatismal, devenu rare, touche surtout les migrants et s'associe volontiers à une IA et à une atteinte mitrale.","src":"p. 197-198"},{"id":"233-qcm-006","type":"QRM","rank":"A","objective":"233-obj-02","tags":["étiologie","imagerie"],"difficulty":2,"stem":"Un homme de 45 ans est découvert porteur d'une bicuspidie aortique responsable d'un RA modéré. Quelles prises en charge sont pertinentes ?","options":[{"t":"Rechercher systématiquement un anévrisme de l'aorte ascendante.","ok":true,"why":"La bicuspidie s'associe fréquemment à une dilatation de l'aorte ascendante qu'il faut mesurer."},{"t":"Proposer un dépistage échographique aux apparentés du premier degré.","ok":true,"why":"La transmission possiblement autosomique dominante justifie un dépistage familial."},{"t":"Affirmer que la coarctation de l'aorte est systématiquement associée.","ok":false,"why":"L'association à une coarctation existe mais reste plus rare que l'anévrisme de l'aorte ascendante."},{"t":"Considérer que la bicuspidie ne peut jamais se traduire par une fuite aortique.","ok":false,"why":"La bicuspidie peut aussi se manifester par une insuffisance aortique et non seulement par un RA."},{"t":"Savoir que la forme la plus fréquente comporte un raphé de fusion des cusps antérieures.","ok":true,"why":"Le type avec raphé, par fusion des cusps antérodroite et antérogauche, est la forme la plus courante."}],"explanation":"La bicuspidie impose de mesurer l'aorte ascendante et de dépister les apparentés du premier degré ; elle peut se compliquer d'un RA comme d'une IA, et sa forme la plus fréquente comporte un raphé de fusion des deux cusps antérieures.","src":"p. 197-198"},{"id":"233-qru-003","type":"QRU","rank":"A","objective":"233-obj-03","tags":["clinique"],"difficulty":1,"stem":"Parmi les trois symptômes classiques du RA serré, lesquels surviennent typiquement à l'effort ?","options":[{"t":"Dyspnée, angor et syncope.","ok":true,"why":"Ces trois symptômes surviennent classiquement à l'effort et marquent la cassure évolutive du RA."},{"t":"Palpitations, vertiges et céphalées.","ok":false,"why":"Ce ne sont pas les symptômes cardinaux décrits pour le RA."},{"t":"Toux, fièvre et frissons.","ok":false,"why":"Ces signes évoquent une autre pathologie, notamment infectieuse."},{"t":"Douleur abdominale, nausées et vomissements.","ok":false,"why":"Non spécifiques du RA."},{"t":"Œdèmes des membres inférieurs isolés.","ok":false,"why":"Ce n'est pas l'un des trois maîtres symptômes d'effort du RA."}],"explanation":"Le RA reste longtemps asymptomatique puis se révèle par la triade d'effort dyspnée–angor–syncope, dont l'apparition marque un tournant évolutif de mauvais pronostic en l'absence de traitement.","src":"p. 199"},{"id":"233-qcm-008","type":"QRM","rank":"A","objective":"233-obj-03","tags":["clinique","pièges"],"difficulty":2,"stem":"Un patient de 78 ans porteur d'un RA connu affirme ne ressentir aucune gêne à l'effort. Quelles remarques sont justes ?","options":[{"t":"Il faut rechercher une réduction progressive et inconsciente de ses activités.","ok":true,"why":"Beaucoup de patients réduisent leurs efforts sans s'en rendre compte et se déclarent à tort asymptomatiques."},{"t":"L'absence de symptôme rapporté élimine formellement un RA serré symptomatique.","ok":false,"why":"Un interrogatoire insuffisant peut masquer des symptômes réels liés à une baisse d'activité."},{"t":"Comparer son niveau d'activité actuel à celui des mois ou années précédents est utile.","ok":true,"why":"C'est la méthode recommandée pour démasquer une limitation fonctionnelle méconnue."},{"t":"Un souffle très intense élimine un RA évolué à bas débit.","ok":false,"why":"À l'inverse, un RA évolué à bas débit peut donner un souffle atténué, voire quasi inaudible."},{"t":"Une échocardiographie n'apporte alors aucune information supplémentaire.","ok":false,"why":"L'ETT reste indispensable pour évaluer la sévérité, quelle que soit la présentation clinique."}],"explanation":"L'interrogatoire doit être minutieux car de nombreux patients ont réduit leurs efforts sans s'en apercevoir et se disent à tort asymptomatiques ; un souffle atténué n'exclut pas un RA sévère évolué à bas débit.","src":"p. 199","trap":"Un patient qui dit ne rien ressentir peut simplement avoir réduit son niveau d'activité."},{"id":"233-qcm-009","type":"QRM","rank":"A","objective":"233-obj-03","tags":["clinique"],"difficulty":1,"stem":"Quelles caractéristiques du souffle du RA sont exactes ?","options":[{"t":"Il est mésosystolique, éjectionnel, de tonalité rude et râpeuse.","ok":true,"why":"C'est la description classique du souffle du RA."},{"t":"Il est maximal au 2e espace intercostal droit.","ok":true,"why":"Le foyer aortique correspond à ce repère anatomique."},{"t":"Il irradie classiquement vers les vaisseaux du cou.","ok":true,"why":"L'irradiation carotidienne est un élément caractéristique de ce souffle."},{"t":"Il se renforce typiquement après une diastole longue.","ok":true,"why":"Une diastole longue augmente le volume éjecté et intensifie le souffle du RA."},{"t":"Il est toujours holosystolique et irradie vers l'aisselle.","ok":false,"why":"Cette description correspond au souffle de l'insuffisance mitrale, pas à celui du RA."}],"explanation":"Le souffle du RA est mésosystolique éjectionnel, rude, râpeux, maximal au 2e espace intercostal droit, irradiant aux vaisseaux du cou, et se renforce après une diastole longue ; l'irradiation axillaire holosystolique est au contraire évocatrice d'une IM.","src":"p. 199"},{"id":"233-qru-004","type":"QRU","rank":"A","objective":"233-obj-03","tags":["clinique"],"difficulty":1,"stem":"Quel signe auscultatoire oriente vers un RA serré calcifié ?","options":[{"t":"Un éclat de B2 au foyer pulmonaire.","ok":false,"why":"Ce signe évoque plutôt une hypertension artérielle pulmonaire."},{"t":"Une abolition de B2.","ok":true,"why":"L'abolition de B2 est classiquement retrouvée dans les RA serrés calcifiés."},{"t":"Un souffle diastolique isolé au foyer aortique.","ok":false,"why":"Ce type de souffle évoque une insuffisance aortique, pas un RA."},{"t":"Un roulement diastolique apexien.","ok":false,"why":"Ce signe oriente plutôt vers un rétrécissement mitral."},{"t":"Un clic mésosystolique.","ok":false,"why":"Le clic mésosystolique est évocateur d'un prolapsus mitral, pas d'un RA."}],"explanation":"L'abolition du deuxième bruit cardiaque (B2) est un argument auscultatoire classique en faveur d'un RA serré et calcifié.","src":"p. 199"},{"id":"233-qcm-011","type":"QRM","rank":"A","objective":"233-obj-04","tags":["paraclinique","diagnostic"],"difficulty":2,"stem":"Concernant les critères échocardiographiques du RA serré, quelles propositions sont exactes ?","options":[{"t":"Une vitesse maximale transaortique supérieure à 4 m/s.","ok":true,"why":"C'est l'un des trois critères classiques du RA serré."},{"t":"Un gradient moyen VG–aorte supérieur à 40 mmHg.","ok":true,"why":"Deuxième critère habituel de sévérité."},{"t":"Une surface aortique inférieure à 1 cm² ou inférieure à 0,6 cm²/m².","ok":true,"why":"Troisième critère de sévérité, tenant compte de la surface corporelle."},{"t":"Une surface aortique comprise entre 2 et 3,5 cm².","ok":false,"why":"Cette fourchette correspond à une surface aortique normale, non à un RA serré."},{"t":"Une vitesse maximale transaortique proche de 1 m/s.","ok":false,"why":"Cette valeur correspond à une vitesse normale, pas à un RA serré."}],"explanation":"Le RA serré est défini par la combinaison d'une vitesse maximale > 4 m/s, d'un gradient moyen > 40 mmHg et d'une surface aortique < 1 cm² (ou < 0,6 cm²/m²), à distinguer des valeurs normales (≈ 1 m/s, 2–5 mmHg, 2–3,5 cm²).","src":"p. 201-202"},{"id":"233-qru-005","type":"QRU","rank":"A","objective":"233-obj-04","tags":["paraclinique"],"difficulty":2,"stem":"Quelle surface aortique définit un RA « critique » ?","options":[{"t":"≤ 0,75 cm² ou < 0,4 cm²/m²","ok":true,"why":"C'est le seuil retenu pour parler de RA critique, en deçà de celui du RA simplement serré."},{"t":"< 1,5 cm²","ok":false,"why":"Ce chiffre reste au-dessus du seuil de sévérité même simple."},{"t":"< 2 cm²","ok":false,"why":"Cette valeur reste dans la zone normale à modérément réduite."},{"t":"< 3 cm²","ok":false,"why":"Cette surface correspond à la limite basse de la normale."},{"t":"< 0,9 cm²/m²","ok":false,"why":"Ce chiffre indexé n'est pas le seuil retenu pour le RA critique."}],"explanation":"Au-delà du seuil de RA serré (< 1 cm² ou < 0,6 cm²/m²), on parle de RA critique lorsque la surface descend à 0,75 cm² ou moins (ou < 0,4 cm²/m²).","src":"p. 202"},{"id":"233-qcm-013","type":"QRM","rank":"A","objective":"233-obj-04","tags":["paraclinique","pièges"],"difficulty":3,"stem":"Une patiente a un gradient moyen à 32 mmHg avec une surface aortique estimée à 0,9 cm² et une FEVG altérée. Quelles démarches sont adaptées ?","options":[{"t":"Évoquer un RA serré à bas débit, bas gradient.","ok":true,"why":"Une surface serrée avec un gradient sous le seuil de 40 mmHg évoque ce profil particulier, surtout si le débit est abaissé."},{"t":"Vérifier le volume d'éjection systolique indexé.","ok":true,"why":"Un volume d'éjection systolique ≤ 35 mL/m² définit le bas débit expliquant le gradient faible."},{"t":"Réaliser une échocardiographie sous faible dose de dobutamine.","ok":true,"why":"Ce test distingue un authentique RA serré d'une pseudosténose en cas de doute diagnostique."},{"t":"Conclure d'emblée que le RA n'est pas serré du fait du gradient bas.","ok":false,"why":"Se fier au seul gradient expose à sous-estimer un RA serré en contexte de bas débit."},{"t":"Écarter toute indication chirurgicale car le gradient est inférieur à 40 mmHg.","ok":false,"why":"Le gradient bas ne suffit pas à exclure une indication ; l'évaluation du bas débit est indispensable avant de conclure."}],"explanation":"Un gradient moyen inférieur à 40 mmHg avec une surface serrée et une FEVG altérée doit faire rechercher un bas débit (volume d'éjection systolique ≤ 35 mL/m²) et réaliser une échographie de stress sous dobutamine pour distinguer un authentique RA serré d'une pseudosténose.","src":"p. 202","trap":"Se fier au seul gradient expose à méconnaître un RA serré à bas débit."},{"id":"233-qcm-014","type":"QRM","rank":"A","objective":"233-obj-06","tags":["ECG","paraclinique"],"difficulty":2,"stem":"Concernant l'ECG au cours du RA, quelles propositions sont exactes ?","options":[{"t":"Un RA serré donne classiquement une HVG de type surcharge systolique.","ok":true,"why":"Des ondes T négatives asymétriques en précordiales gauches traduisent cette surcharge systolique."},{"t":"Un ECG normal élimine formellement un RA serré.","ok":false,"why":"L'absence d'anomalie ECG n'exclut pas un RA serré."},{"t":"Des troubles de conduction comme un BAV du premier degré peuvent s'observer.","ok":true,"why":"Des troubles conductifs, dont le BBG ou le BAV1, peuvent accompagner un RA évolué."},{"t":"La FA est plus fréquente dans le RA que dans les valvulopathies mitrales.","ok":false,"why":"La FA reste au contraire moins fréquente dans le RA que dans les atteintes mitrales."},{"t":"L'ECG peut être normal si le RA est peu évolué.","ok":true,"why":"Un RA peu évolué peut s'accompagner d'un tracé sans anomalie notable."}],"explanation":"L'ECG du RA serré montre typiquement une HVG de surcharge systolique et parfois des troubles conductifs, mais un tracé normal n'exclut jamais un RA serré ; la FA y est moins fréquente que dans les valvulopathies mitrales.","src":"p. 200"},{"id":"233-qru-006","type":"QRU","rank":"A","objective":"233-obj-04","tags":["diagnostic"],"difficulty":2,"stem":"Chez un homme de 55 ans candidat à un remplacement valvulaire pour RA serré, sans facteur de risque cardiovasculaire connu, quel bilan coronaire est recommandé ?","options":[{"t":"Aucun bilan coronaire n'est nécessaire avant 60 ans.","ok":false,"why":"L'âge de 40 ans chez l'homme est le seuil retenu pour justifier une coronarographie préopératoire, indépendamment des facteurs de risque."},{"t":"Une coronarographie préopératoire systématique.","ok":true,"why":"Chez l'homme de plus de 40 ans, une coronarographie préopératoire est recommandée même en l'absence de facteur de risque."},{"t":"Un dosage isolé de troponine suffit.","ok":false,"why":"Ce dosage n'a pas d'intérêt pour le bilan coronaire préopératoire d'un RA."},{"t":"Une épreuve d'effort seule, sans imagerie coronaire.","ok":false,"why":"L'épreuve d'effort n'est pas l'examen de référence du bilan coronaire préopératoire chez ce patient."},{"t":"Une IRM cardiaque de repos suffit à écarter une coronaropathie.","ok":false,"why":"L'IRM n'est pas l'examen recommandé pour ce bilan coronaire préopératoire."}],"explanation":"La coronarographie préopératoire est recommandée chez tout homme de plus de 40 ans ou toute femme ménopausée candidats à une chirurgie de RA, même en l'absence de facteur de risque cardiovasculaire.","src":"p. 203"},{"id":"233-qcm-016","type":"QRM","rank":"A","objective":"233-obj-06","tags":["imagerie","paraclinique"],"difficulty":2,"stem":"Quelles sont les indications du scanner cardiaque dans le RA ?","options":[{"t":"Il est systématique avant la pose d'un TAVI.","ok":true,"why":"Il précise l'anneau, le culot aortique, les ostia coronaires et les axes d'abord vasculaire."},{"t":"Il permet de mesurer un score calcique valvulaire en cas de discordance clinico-échographique.","ok":true,"why":"Un score calcique élevé (> 2 000 UA chez l'homme, > 1 200 UA chez la femme) oriente vers un RA serré."},{"t":"Il remplace systématiquement l'échocardiographie dans le diagnostic initial du RA.","ok":false,"why":"L'ETT reste l'examen clé initial ; le scanner intervient en complément, notamment préopératoire."},{"t":"Il peut préciser la mesure de l'aorte ascendante si l'ETT est insuffisante.","ok":true,"why":"Le scanner est utile pour compléter la mesure aortique lorsque l'échographie ne suffit pas."},{"t":"Il est contre-indiqué chez tout patient candidat à un TAVI.","ok":false,"why":"Au contraire, il est un examen systématique du bilan préalable au TAVI."}],"explanation":"Le scanner cardiaque est systématique avant TAVI (anneau, culot aortique, ostia coronaires, axes vasculaires), utile pour le score calcique en cas de discordance et pour préciser l'aorte ascendante, mais il ne remplace pas l'échocardiographie comme examen diagnostique initial.","src":"p. 204"},{"id":"233-qcm-017","type":"QRM","rank":"A","objective":"233-obj-06","tags":["paraclinique"],"difficulty":2,"stem":"Concernant l'épreuve d'effort dans le RA, quelles propositions sont exactes ?","options":[{"t":"Elle est indiquée chez le patient présentant un RA serré dit asymptomatique.","ok":true,"why":"Elle vise à démasquer objectivement des symptômes méconnus chez ces patients."},{"t":"Elle est contre-indiquée chez un RA serré franchement symptomatique.","ok":true,"why":"Elle n'est pas recommandée lorsque les symptômes sont déjà patents."},{"t":"Une élévation inadéquate ou une baisse de la pression artérielle à l'effort est un signe de mauvaise tolérance.","ok":true,"why":"Ce profil tensionnel anormal à l'effort témoigne d'une réponse hémodynamique défaillante."},{"t":"Elle est toujours réalisée en première intention avant l'échocardiographie.","ok":false,"why":"L'ETT reste l'examen initial ; l'épreuve d'effort est un complément chez certains patients asymptomatiques."},{"t":"Elle n'apporte aucune information sur le niveau d'effort atteint.","ok":false,"why":"Elle permet au contraire d'objectiver le niveau d'effort réellement toléré."}],"explanation":"L'épreuve d'effort est réservée au RA serré asymptomatique pour démasquer une intolérance méconnue (niveau d'effort atteint, réponse tensionnelle anormale) ; elle est proscrite en cas de symptômes déjà patents.","src":"p. 204"},{"id":"233-qcm-018","type":"QRM","rank":"A","objective":"233-obj-07","tags":["complications"],"difficulty":2,"stem":"Parmi les complications évolutives du RA non traité, lesquelles sont correctement associées à leur mécanisme ?","options":[{"t":"Mort subite, surtout dans le RA serré symptomatique.","ok":true,"why":"C'est une complication redoutée, particulièrement chez les patients symptomatiques non traités."},{"t":"Syndrome de Heyde associant anémie ferriprive et angiodysplasies intestinales.","ok":true,"why":"Ce syndrome comporte une anomalie acquise du facteur von Willebrand favorisant les saignements digestifs."},{"t":"Embolies calcaires pouvant toucher la rétine et donner une cécité transitoire.","ok":true,"why":"Des fragments calcaires peuvent migrer vers l'artère centrale de la rétine."},{"t":"La fibrillation atriale est en général très bien tolérée dans le RA.","ok":false,"why":"C'est l'inverse : la FA est mal tolérée du fait de la perte de la systole atriale."},{"t":"L'endocardite est la complication la plus fréquente du RA.","ok":false,"why":"L'endocardite reste une complication rare du RA, loin derrière l'insuffisance cardiaque ou la mort subite."}],"explanation":"Le RA non traité expose à l'insuffisance cardiaque, aux troubles conductifs, à la mort subite (surtout si symptomatique), à des embolies calcaires et au syndrome de Heyde ; la FA, mal tolérée, et l'endocardite, plus rare, complètent le tableau.","src":"p. 204-205"},{"id":"233-qcm-019","type":"QRM","rank":"A","objective":"233-obj-09","tags":["traitement"],"difficulty":2,"stem":"Concernant les options thérapeutiques du RA serré, quelles propositions sont exactes ?","options":[{"t":"La bioprothèse chirurgicale est en général proposée après 65 ans.","ok":true,"why":"Elle évite l'anticoagulation au prix d'une dégénérescence en 10 à 15 ans, ce qui la fait préférer chez le sujet plus âgé."},{"t":"La prothèse mécanique impose une anticoagulation à vie.","ok":true,"why":"C'est la contrepartie de sa longue durabilité, la faisant réserver au sujet jeune."},{"t":"Le TAVI est recommandé en première intention après 75 ans si la voie fémorale est possible.","ok":true,"why":"C'est l'indication de première intention retenue au-delà de cet âge, quel que soit le risque chirurgical."},{"t":"La valvuloplastie au ballon constitue aujourd'hui un traitement de fond durable du RA.","ok":false,"why":"Cette technique est quasi abandonnée en raison d'une resténose précoce."},{"t":"La décision de TAVI se prend en dehors de toute concertation pluridisciplinaire.","ok":false,"why":"La décision doit être prise en Heart Team, en tenant compte de l'âge, de la fragilité et des comorbidités."}],"explanation":"Le choix thérapeutique du RA serré associe RVA chirurgical (bioprothèse après 65 ans, prothèse mécanique chez le sujet jeune sous anticoagulation) et TAVI, recommandé chez les patients à risque ou inopérables et en première intention après 75 ans si la voie fémorale est possible, toujours décidé en Heart Team.","src":"p. 205"},{"id":"233-qcm-020","type":"QRM","rank":"A","objective":"233-obj-10","tags":["traitement","pièges"],"difficulty":3,"stem":"Un homme de 82 ans présente un RA serré symptomatique (dyspnée d'effort), sans comorbidité majeure. Quelles affirmations sont exactes ?","options":[{"t":"L'âge avancé ne doit pas, à lui seul, faire renoncer au traitement.","ok":true,"why":"Le RA serré symptomatique se traite pratiquement sans limite d'âge si l'état général le permet."},{"t":"Un traitement (RVA ou TAVI) est indiqué de façon quasi systématique dans cette situation.","ok":true,"why":"Tout RA serré symptomatique impose en principe un traitement, sauf pathologie associée limitant le pronostic à court terme."},{"t":"La seule option envisageable chez ce patient est la valvuloplastie au ballon.","ok":false,"why":"La valvuloplastie n'est pas un traitement de fond ; RVA ou TAVI restent les options à privilégier."},{"t":"Une simple surveillance clinique annuelle est suffisante.","ok":false,"why":"La présence de symptômes chez un RA serré impose un traitement et non une simple surveillance."},{"t":"L'absence d'autre pathologie engageant le pronostic à court terme est un argument en faveur du traitement.","ok":true,"why":"C'est l'une des conditions mentionnées pour proposer un traitement malgré l'âge avancé."}],"explanation":"Le RA serré symptomatique impose un traitement (RVA ou TAVI) pratiquement sans limite d'âge, dès lors que l'état général est conservé et qu'aucune autre pathologie ne compromet le pronostic à court terme ; la valvuloplastie au ballon n'est pas une alternative de fond.","src":"p. 206","trap":"Refuser un traitement au seul motif de l'âge est une erreur."},{"id":"233-qroc-001","type":"QROC","rank":"A","objective":"233-obj-01","tags":["définition"],"difficulty":1,"question":"Comment définir le rétrécissement aortique en une phrase ?","answer":"Obstacle à l'éjection du sang du VG vers l'aorte, siégeant le plus souvent sur la valve aortique elle-même.","accept":["obstacle à l'éjection ventriculaire gauche"],"keywords":["obstacle","éjection","valve aortique"],"explanation":"Le RA correspond à une gêne à l'éjection du ventricule gauche, l'obstacle étant le plus souvent situé sur la valve aortique elle-même.","src":"p. 195"},{"id":"233-qroc-002","type":"QROC","rank":"A","objective":"233-obj-04","tags":["paraclinique"],"difficulty":1,"question":"Quelle surface aortique (non indexée) définit un RA serré ?","answer":"Inférieure à 1 cm².","accept":["< 1 cm2","moins de 1 cm2"],"keywords":["1","cm2","surface"],"explanation":"Une surface aortique inférieure à 1 cm² (ou < 0,6 cm²/m² indexée à la surface corporelle) définit le RA serré.","src":"p. 202"},{"id":"233-qroc-003","type":"QROC","rank":"A","objective":"233-obj-04","tags":["paraclinique"],"difficulty":1,"question":"Quel gradient moyen VG–aorte définit un RA serré ?","answer":"Un gradient moyen supérieur à 40 mmHg.","accept":["> 40 mmhg","superieur a 40"],"keywords":["40","gradient","mmhg"],"explanation":"Le gradient moyen VG–aorte, normalement de 2 à 5 mmHg, dépasse 40 mmHg dans le RA serré.","src":"p. 196"},{"id":"233-qroc-004","type":"QROC","rank":"A","objective":"233-obj-03","tags":["clinique"],"difficulty":1,"question":"Citer les trois symptômes cardinaux d'effort du RA serré.","answer":"Dyspnée, angor et syncope d'effort.","accept":["dyspnee angor syncope"],"keywords":["dyspnée","angor","syncope"],"explanation":"Ces trois symptômes, tous déclenchés par l'effort, marquent la cassure évolutive du RA et imposent le traitement lorsqu'ils apparaissent.","src":"p. 199"},{"id":"233-qroc-005","type":"QROC","rank":"A","objective":"233-obj-03","tags":["clinique"],"difficulty":1,"question":"Où le souffle du RA est-il classiquement maximal à l'auscultation ?","answer":"Au deuxième espace intercostal droit (foyer aortique).","accept":["2e eic droit","foyer aortique"],"keywords":["2e","espace","intercostal","droit"],"explanation":"Le souffle mésosystolique éjectionnel du RA est maximal au 2e espace intercostal droit et irradie vers les vaisseaux du cou.","src":"p. 199"},{"id":"233-qroc-006","type":"QROC","rank":"A","objective":"233-obj-02","tags":["étiologie"],"difficulty":1,"question":"Quelle est la principale étiologie du RA chez un adulte de 45 ans ?","answer":"La bicuspidie aortique.","accept":["bicuspidie"],"keywords":["bicuspidie"],"explanation":"Avant 65–70 ans, la bicuspidie aortique est l'étiologie la plus fréquente du RA, devant les causes rhumatismales devenues rares.","src":"p. 198"},{"id":"233-qroc-007","type":"QROC","rank":"A","objective":"233-obj-02","tags":["étiologie","épidémiologie"],"difficulty":1,"question":"Quelle est la principale étiologie du RA chez un sujet de 80 ans ?","answer":"Le RA dégénératif calcifié (maladie de Mönckeberg).","accept":["ra degeneratif","monckeberg"],"keywords":["dégénératif","calcifié"],"explanation":"Après 65–70 ans, le RA dégénératif calcifié devient l'étiologie dominante, avec une valve d'autant plus calcifiée que la sténose est sévère.","src":"p. 198"},{"id":"233-qroc-008","type":"QROC","rank":"A","objective":"233-obj-07","tags":["complications"],"difficulty":2,"question":"Quel syndrome associe RA, angiodysplasies intestinales et anémie ferriprive ?","answer":"Le syndrome de Heyde.","accept":["heyde"],"keywords":["heyde"],"explanation":"Le syndrome de Heyde associe un RA à des angiodysplasies intestinales responsables d'une anémie ferriprive, favorisées par une anomalie acquise du facteur von Willebrand.","src":"p. 205"},{"id":"233-qroc-009","type":"QROC","rank":"A","objective":"233-obj-06","tags":["imagerie"],"difficulty":2,"question":"Quel seuil de score calcique valvulaire (scanner) est en faveur d'un RA serré chez l'homme ?","answer":"Supérieur à 2 000 UA.","accept":["2000 ua","> 2000"],"keywords":["2000","ua","homme"],"explanation":"Un score calcique valvulaire supérieur à 2 000 UA chez l'homme (1 200 UA chez la femme) oriente vers un RA serré en cas de discordance entre surface et gradient.","src":"p. 204"},{"id":"233-qroc-010","type":"QROC","rank":"A","objective":"233-obj-04","tags":["paraclinique"],"difficulty":2,"question":"Quel volume d'éjection systolique indexé définit un bas débit dans le RA à bas gradient ?","answer":"Inférieur ou égal à 35 mL/m².","accept":["<= 35 ml/m2"],"keywords":["35","ml","m2"],"explanation":"Un RA serré à bas gradient s'accompagne d'un volume d'éjection systolique indexé inférieur ou égal à 35 mL/m², ce qui explique un gradient sous le seuil habituel de 40 mmHg.","src":"p. 202"},{"id":"233-qroc-011","type":"QROC","rank":"A","objective":"233-obj-04","tags":["paraclinique"],"difficulty":1,"question":"À partir de quel âge une coronarographie préopératoire est-elle systématique chez l'homme avant chirurgie de RA ?","answer":"À partir de 40 ans.","accept":["40 ans"],"keywords":["40","ans","homme"],"explanation":"Chez l'homme de plus de 40 ans (ou la femme ménopausée), une coronarographie préopératoire est recommandée même en l'absence de facteur de risque.","src":"p. 203"},{"id":"233-qroc-012","type":"QROC","rank":"A","objective":"233-obj-11","tags":["traitement"],"difficulty":2,"question":"À partir de quel âge le TAVI est-il recommandé en première intention si la voie fémorale est possible ?","answer":"Après 75 ans.","accept":["75 ans","apres 75"],"keywords":["75","ans","tavi"],"explanation":"Le TAVI est recommandé en première intention après 75 ans, quel que soit le risque chirurgical, lorsque la voie fémorale est réalisable.","src":"p. 205"},{"id":"233-open-01","type":"OPEN","rank":"A","objective":"233-obj-04","tags":["diagnostic","clinique","paraclinique"],"difficulty":2,"prompt":"Un homme de 70 ans consulte pour une dyspnée d'effort progressive depuis six mois. L'auscultation retrouve un souffle systolique rude au foyer aortique irradiant aux carotides. Détaillez la démarche diagnostique permettant d'affirmer un RA serré et d'en apprécier le retentissement.","rubric":[{"point":"Évoquer le RA devant le souffle éjectionnel typique et la dyspnée d'effort","weight":2},{"point":"Rechercher les deux autres symptômes cardinaux : angor, syncope","weight":1},{"point":"Demander une ETT comme examen clé du diagnostic et de la quantification","weight":2},{"point":"Citer les trois critères échographiques de sévérité (Vmax > 4 m/s, gradient moyen > 40 mmHg, surface < 1 cm²)","weight":2},{"point":"Évaluer le retentissement VG (hypertrophie, FEVG) et rechercher une atteinte associée","weight":2},{"point":"Discuter le bilan coronaire préopératoire (homme > 40 ans)","weight":1}],"model":"Devant une dyspnée d'effort avec souffle mésosystolique éjectionnel râpeux irradiant aux carotides, on évoque un RA et on recherche activement un angor et une syncope d'effort. L'ETT est l'examen clé : elle confirme le diagnostic (valve calcifiée, doppler continu), quantifie la sévérité (Vmax > 4 m/s, gradient moyen > 40 mmHg, surface < 1 cm² ou < 0,6 cm²/m²) et évalue le retentissement (hypertrophie et FEVG du VG, PAP, valves associées). Un bilan coronaire (coronarographie préopératoire, homme de plus de 40 ans) complète l'évaluation avant toute décision thérapeutique.","src":"p. 198-203"},{"id":"233-open-02","type":"OPEN","rank":"A","objective":"233-obj-02","tags":["étiologie","suivi"],"difficulty":2,"prompt":"Une femme de 28 ans est découverte porteuse d'une bicuspidie aortique lors d'un bilan systématique, avec un RA minime. Quelles investigations et quelle surveillance familiale proposez-vous ?","rubric":[{"point":"Mesurer systématiquement l'aorte ascendante à la recherche d'un anévrisme","weight":2},{"point":"Envisager une ETO, un angioscanner ou une IRM si l'ETT est insuffisante","weight":1},{"point":"Proposer un dépistage échographique aux apparentés du premier degré","weight":2},{"point":"Expliquer le caractère évolutif de la bicuspidie vers un RA à l'âge adulte","weight":1},{"point":"Programmer une surveillance échographique régulière","weight":1}],"model":"La découverte d'une bicuspidie impose de mesurer l'aorte ascendante (ETT, complétée par ETO, angioscanner ou IRM si besoin) à la recherche d'un anévrisme associé. La transmission possiblement autosomique dominante justifie de proposer un dépistage échographique aux apparentés du premier degré. Il faut expliquer à la patiente le caractère évolutif de cette malformation congénitale, qui peut aboutir à un RA ou à une IA à l'âge adulte, et organiser une surveillance échographique régulière.","src":"p. 197-198"},{"id":"233-open-03","type":"OPEN","rank":"A","objective":"233-obj-10","tags":["traitement"],"difficulty":3,"prompt":"Chez un patient porteur d'un RA serré asymptomatique à FEVG normale, quels éléments feraient discuter une intervention plutôt qu'une simple surveillance ?","rubric":[{"point":"Une épreuve d'effort anormale","weight":2},{"point":"Un RA très serré avec Vmax > 5 m/s","weight":2},{"point":"Une aggravation rapide de la sténose lors de la surveillance","weight":1},{"point":"Une FEVG abaissée en dessous de 55 %","weight":2},{"point":"Rappeler qu'en l'absence de ces critères la surveillance reste la règle","weight":1}],"model":"En l'absence de symptômes et avec une FEVG conservée, le RA serré est en principe surveillé. Une intervention est cependant discutée si l'épreuve d'effort est anormale, si le RA est très serré (Vmax > 5 m/s), si la sténose progresse rapidement lors du suivi, ou si la FEVG passe sous 55 %. En dehors de ces situations, la surveillance clinique et échographique régulière reste la stratégie recommandée.","src":"p. 206"},{"id":"233-open-04","type":"OPEN","rank":"A","objective":"233-obj-08","tags":["traitement"],"difficulty":2,"prompt":"Quels sont les éléments du bilan préopératoire à réunir avant un remplacement valvulaire aortique pour RA serré ?","rubric":[{"point":"Imagerie coronaire (coronarographie ou coroscanner)","weight":2},{"point":"Échodoppler des troncs supra-aortiques","weight":1},{"point":"Recherche de foyers infectieux ORL et dentaires (panoramique, radiographie des sinus)","weight":2},{"point":"Évaluation des comorbidités rénales et pulmonaires","weight":1},{"point":"Avis gériatrique chez le patient très âgé","weight":1},{"point":"Mesure/imagerie de l'aorte en cas de bicuspidie","weight":1}],"model":"Le bilan préopératoire du RA serré associe une imagerie coronaire (coronarographie ou coroscanner), un échodoppler des troncs supra-aortiques, la recherche de foyers infectieux ORL et dentaires (panoramique dentaire, radiographie des sinus), l'évaluation des comorbidités rénales et pulmonaires, et un avis gériatrique chez le sujet très âgé. En cas de bicuspidie associée, l'aorte doit être mesurée (scanner ou IRM) pour discuter un geste aortique combiné.","src":"p. 206-207"},{"id":"233-qcm-101","type":"QRM","rank":"A","objective":"233-obj-01","tags":["définition"],"difficulty":1,"stem":"Concernant l'insuffisance mitrale (IM), quelles propositions sont exactes ?","options":[{"t":"Elle correspond à un reflux de sang du VG vers l'atrium gauche en systole.","ok":true,"why":"C'est la définition même de l'IM, liée à un défaut d'étanchéité de la valve mitrale."},{"t":"Elle correspond à un reflux de sang de l'aorte vers le VG en diastole.","ok":false,"why":"Cette description correspond à l'insuffisance aortique, pas à l'IM."},{"t":"La valve mitrale comporte deux feuillets réunis par deux commissures.","ok":true,"why":"Les feuillets antérieur et postérieur sont réunis par les commissures antéroexterne et postéro-interne."},{"t":"Les feuillets mitraux sont amarrés au VG par des cordages issus des piliers.","ok":true,"why":"Les cordages, issus des deux piliers, relient les feuillets au myocarde ventriculaire."},{"t":"L'IM ne peut jamais résulter d'une anomalie isolée de l'anneau.","ok":false,"why":"Une dilatation isolée de l'anneau peut, à elle seule, être responsable d'une IM dite atriale."}],"explanation":"L'IM est un reflux systolique du VG vers l'atrium gauche par défaut d'étanchéité de la valve mitrale, dont l'appareil comporte deux feuillets, deux commissures et des cordages amarrés aux piliers ; elle peut résulter d'une atteinte isolée de l'anneau, des feuillets, des cordages ou des piliers.","src":"p. 209"},{"id":"233-qcm-102","type":"QRM","rank":"A","objective":"233-obj-01","tags":["diagnostic","physiopathologie"],"difficulty":2,"stem":"À propos de la classification de Carpentier, quelles associations sont correctes ?","options":[{"t":"Type I : jeu valvulaire normal, feuillets dans le plan de l'anneau.","ok":true,"why":"C'est le mécanisme des perforations, fentes, et de l'IM atriale par dilatation de l'anneau."},{"t":"Type II : jeu exagéré, un feuillet dépasse le plan de l'anneau vers l'atrium (prolapsus).","ok":true,"why":"C'est le mécanisme classique des IM dystrophiques par prolapsus."},{"t":"Type IIIa : jeu restreint en systole et en diastole.","ok":true,"why":"Ce mécanisme se voit notamment dans le rhumatisme articulaire aigu et les atteintes médicamenteuses ou radiques."},{"t":"Type IIIb : jeu restreint uniquement en systole, typique de l'IM secondaire.","ok":true,"why":"L'éloignement des piliers dans les cardiopathies dilatées ou ischémiques restreint le jeu valvulaire en systole."},{"t":"Type II correspond à une restriction du jeu valvulaire.","ok":false,"why":"Le type II correspond au contraire à un excès de mobilité, pas à une restriction."}],"explanation":"La classification de Carpentier distingue le type I (jeu normal), le type II (jeu exagéré, prolapsus), le type IIIa (restriction systolo-diastolique) et le type IIIb (restriction systolique, typique de l'IM secondaire).","src":"p. 209-210"},{"id":"233-qru-101","type":"QRU","rank":"A","objective":"233-obj-01","tags":["physiopathologie"],"difficulty":2,"stem":"Quel mécanisme de Carpentier correspond à un prolapsus valvulaire mitral dystrophique ?","options":[{"t":"Type I","ok":false,"why":"Le type I correspond à un jeu valvulaire normal, sans excès de mobilité."},{"t":"Type II","ok":true,"why":"Le prolapsus, mouvement exagéré d'un feuillet au-delà du plan de l'anneau, définit le type II."},{"t":"Type IIIa","ok":false,"why":"Ce type correspond à une restriction systolo-diastolique, pas à un excès de mobilité."},{"t":"Type IIIb","ok":false,"why":"Ce type correspond à une restriction systolique, typique de l'IM secondaire."},{"t":"Aucun type ne correspond au prolapsus.","ok":false,"why":"Le prolapsus est au contraire bien identifié comme le type II de Carpentier."}],"explanation":"Le prolapsus valvulaire, mouvement exagéré d'un feuillet dépassant le plan de l'anneau vers l'atrium gauche, correspond au type II de la classification de Carpentier.","src":"p. 209-210"},{"id":"233-qcm-103","type":"QRM","rank":"A","objective":"233-obj-05","tags":["physiopathologie"],"difficulty":2,"stem":"Concernant le retentissement ventriculaire gauche de l'IM chronique, quelles propositions sont exactes ?","options":[{"t":"Le VG subit une surcharge volumique responsable d'une hypertrophie excentrique.","ok":true,"why":"Le VG reçoit à la fois le sang des veines pulmonaires et le volume régurgité, imposant une surcharge de volume."},{"t":"La FEVG mesurée est sous-estimée par rapport à la fonction contractile réelle.","ok":false,"why":"C'est l'inverse : la FEVG est surestimée car le VG se décharge en partie dans l'atrium gauche à basse pression."},{"t":"On considère qu'il existe une dysfonction VG dès que la FEVG passe sous 60 %.","ok":true,"why":"Du fait de la surestimation de la FEVG, le seuil de dysfonction est abaissé à 60 % dans l'IM."},{"t":"La correction chirurgicale est recommandée chez l'asymptomatique dès que le DTS VG dépasse 40 mm.","ok":true,"why":"Le diamètre télésystolique du VG supérieur à 40 mm est un critère justifiant la correction même sans symptôme."},{"t":"Le VG ne se dilate jamais au cours d'une IM chronique significative.","ok":false,"why":"La dilatation du VG est au contraire un élément central du retentissement de l'IM chronique."}],"explanation":"Dans l'IM chronique, la surcharge volumique du VG entraîne une hypertrophie excentrique et une dilatation ; la FEVG est surestimée par la décharge dans l'atrium gauche, ce qui abaisse le seuil de dysfonction à 60 % et justifie la correction dès un DTS VG > 40 mm chez l'asymptomatique.","src":"p. 209-210","trap":"Une FEVG à 60 % dans une IM sévère traduit déjà une dysfonction ventriculaire."},{"id":"233-qru-102","type":"QRU","rank":"A","objective":"233-obj-05","tags":["physiopathologie"],"difficulty":2,"stem":"Que traduit une onde V ample avec une PAPO supérieure à 15 mmHg au cathétérisme droit dans l'IM ?","options":[{"t":"Une hypertension pulmonaire pré-capillaire isolée.","ok":false,"why":"L'onde V de reflux dans l'IM est un signe post-capillaire, pas pré-capillaire."},{"t":"Une hypertension pulmonaire post-capillaire liée au reflux mitral.","ok":true,"why":"L'onde V systolique de reflux et l'élévation de la PAPO signent l'hypertension pulmonaire post-capillaire de l'IM."},{"t":"Une sténose pulmonaire associée.","ok":false,"why":"Ce n'est pas le mécanisme évoqué par ce profil hémodynamique."},{"t":"Une insuffisance tricuspide isolée sans rapport avec la valve mitrale.","ok":false,"why":"Le profil décrit est directement rattaché au reflux mitral, pas à la valve tricuspide."},{"t":"Une normalisation des pressions pulmonaires.","ok":false,"why":"Au contraire, ces valeurs témoignent d'une élévation pathologique des pressions pulmonaires."}],"explanation":"L'élévation de la PAPO au-delà de 15 mmHg avec une onde V ample traduit une hypertension pulmonaire post-capillaire secondaire au reflux mitral vers l'atrium gauche et la circulation pulmonaire.","src":"p. 211"},{"id":"233-qcm-104","type":"QRM","rank":"A","objective":"233-obj-02","tags":["étiologie"],"difficulty":2,"stem":"Concernant l'IM primaire dystrophique par prolapsus, quelles propositions sont exactes ?","options":[{"t":"C'est la cause la plus fréquente des fuites mitrales sévères.","ok":true,"why":"L'atteinte dystrophique par prolapsus domine largement les étiologies des IM sévères."},{"t":"La dégénérescence myxoïde (maladie de Barlow) se caractérise par un excès de tissu et des valves redondantes.","ok":true,"why":"C'est la description classique de la maladie de Barlow, avec hypermobilité et ruptures de cordages par traction."},{"t":"La dégénérescence fibroélastique touche préférentiellement la valve postérieure chez l'homme âgé.","ok":true,"why":"Cette forme, plus fréquente, se voit surtout chez l'homme âgé, avec rupture de cordage sur la valve postérieure."},{"t":"Ce mécanisme correspond au type IIIa de Carpentier.","ok":false,"why":"Le prolapsus dystrophique correspond au type II, et non au type IIIa (restriction)."},{"t":"Elle ne s'observe jamais dans le cadre d'un syndrome de Marfan.","ok":false,"why":"Un prolapsus mitral dystrophique peut s'observer dans le Marfan ou l'Ehlers-Danlos."}],"explanation":"L'IM dystrophique par prolapsus (Carpentier II) est la première cause de fuite mitrale sévère ; elle regroupe la maladie de Barlow (excès myxoïde diffus) et la dégénérescence fibroélastique (plus fréquente, homme âgé, valve postérieure), et peut s'inscrire dans un syndrome de Marfan.","src":"p. 211-212"},{"id":"233-qcm-105","type":"QRM","rank":"A","objective":"233-obj-02","tags":["étiologie"],"difficulty":2,"stem":"Concernant l'IM secondaire (fonctionnelle), quelles propositions sont exactes ?","options":[{"t":"Les feuillets valvulaires sont anatomiquement normaux.","ok":true,"why":"C'est la caractéristique définissant l'IM secondaire, par opposition à l'IM primaire organique."},{"t":"Elle peut résulter d'un déplacement des piliers dans une cardiopathie dilatée ou ischémique.","ok":true,"why":"L'éloignement des piliers restreint la coaptation des feuillets, définissant le mécanisme IIIb."},{"t":"Elle peut résulter d'une dilatation de l'anneau sur un atrium gauche très dilaté.","ok":true,"why":"C'est le mécanisme de l'IM dite atriale, de type I selon Carpentier."},{"t":"Elle correspond toujours à une atteinte organique des cordages.","ok":false,"why":"C'est au contraire l'IM primaire qui correspond à une atteinte organique des feuillets ou des cordages."},{"t":"L'IM ischémique classique fait suite à un infarctus inférieur avec séquelle de cinétique.","ok":true,"why":"C'est la présentation classique décrite pour l'IM ischémique secondaire."}],"explanation":"L'IM secondaire touche des feuillets normaux : elle résulte d'un déplacement des piliers (cardiopathie dilatée ou ischémique, classiquement après infarctus inférieur) ou d'une dilatation de l'anneau sur un atrium gauche très dilaté (IM atriale).","src":"p. 213"},{"id":"233-qru-103","type":"QRU","rank":"A","objective":"233-obj-02","tags":["étiologie","urgence"],"difficulty":2,"stem":"Quel mécanisme d'IM secondaire est le plus classiquement décrit après un infarctus inférieur ?","options":[{"t":"Une dilatation isolée de l'anneau mitral.","ok":false,"why":"Ce mécanisme correspond à l'IM atriale, non à l'IM post-infarctus."},{"t":"Une séquelle de cinétique inférieure avec restriction du jeu valvulaire.","ok":true,"why":"L'infarctus inférieur laisse classiquement une séquelle de cinétique qui restreint le jeu valvulaire (type IIIb)."},{"t":"Une perforation valvulaire par endocardite.","ok":false,"why":"La perforation évoque une endocardite, pas une séquelle ischémique."},{"t":"Une dégénérescence myxoïde du feuillet postérieur.","ok":false,"why":"Ce mécanisme correspond à une cause dystrophique primaire, non ischémique."},{"t":"Une atteinte rhumatismale bicommissurale.","ok":false,"why":"Ce mécanisme n'a pas de lien avec un infarctus inférieur."}],"explanation":"L'IM ischémique secondaire fait classiquement suite à un infarctus inférieur, avec une séquelle de cinétique inférieure restreignant le jeu valvulaire en systole (type IIIb).","src":"p. 213"},{"id":"233-qcm-106","type":"QRM","rank":"A","objective":"233-obj-02","tags":["étiologie","urgence"],"difficulty":2,"stem":"Parmi les causes suivantes, lesquelles peuvent provoquer une IM aiguë ?","options":[{"t":"Rupture de cordage sur dégénérescence myxoïde.","ok":true,"why":"Une rupture de cordage brutale sur valve dystrophique est une cause classique d'IM aiguë."},{"t":"Rupture de pilier au décours d'un infarctus.","ok":true,"why":"C'est une complication mécanique gravissime de l'infarctus du myocarde."},{"t":"Perforation valvulaire au cours d'une endocardite.","ok":true,"why":"La destruction infectieuse d'un feuillet peut provoquer une fuite aiguë majeure."},{"t":"Dégénérescence progressive d'une bioprothèse mitrale sur plusieurs années.","ok":false,"why":"Ce mécanisme est lentement progressif, ce n'est pas une cause d'IM aiguë."},{"t":"Traumatisme thoracique fermé.","ok":true,"why":"Un traumatisme thoracique peut léser l'appareil valvulaire mitral et provoquer une fuite aiguë."}],"explanation":"L'IM aiguë résulte le plus souvent d'une rupture de cordage, d'une rupture ou dysfonction de pilier post-infarctus, d'un traumatisme thoracique ou d'une perforation par endocardite ; il s'agit d'une urgence hémodynamique potentiellement grave.","src":"p. 213-214"},{"id":"233-qru-104","type":"QRU","rank":"A","objective":"233-obj-02","tags":["urgence","pièges"],"difficulty":3,"stem":"Un patient présente un tableau d'œdème pulmonaire aigu strictement unilatéral. Quel diagnostic doit être évoqué en priorité ?","options":[{"t":"Une pneumopathie infectieuse banale.","ok":false,"why":"Ce tableau ne correspond pas à la présentation typique d'une pneumopathie infectieuse."},{"t":"Une IM aiguë par rupture de cordage avec fuite directionnelle.","ok":true,"why":"Une rupture de cordage peut créer un jet régurgitant dirigé vers une seule veine pulmonaire, donnant un OAP unilatéral."},{"t":"Un RA serré asymptomatique.","ok":false,"why":"Le RA ne provoque pas ce type de présentation unilatérale."},{"t":"Une péricardite aiguë.","ok":false,"why":"La péricardite ne se traduit pas par un OAP unilatéral."},{"t":"Une insuffisance aortique chronique bien tolérée.","ok":false,"why":"Une IA chronique bien tolérée n'explique pas un tableau aigu unilatéral."}],"explanation":"Un œdème pulmonaire unilatéral doit faire évoquer une IM aiguë par rupture de cordage, dont le jet régurgitant directionnel peut se projeter préférentiellement vers une veine pulmonaire et donner un tableau radiologique trompeur.","src":"p. 214","trap":"Un OAP unilatéral peut égarer vers un diagnostic pulmonaire alors qu'il s'agit d'une IM aiguë."},{"id":"233-qcm-107","type":"QRM","rank":"A","objective":"233-obj-03","tags":["clinique"],"difficulty":1,"stem":"Concernant le souffle de l'insuffisance mitrale, quelles propositions sont exactes ?","options":[{"t":"Il est holosystolique, de B1 à B2 voire au-delà.","ok":true,"why":"C'est la description classique du souffle de régurgitation mitrale."},{"t":"Il est maximal à la pointe et irradie classiquement vers l'aisselle.","ok":true,"why":"Le foyer mitral et l'irradiation axillaire sont typiques, sauf cas particulier de prolapsus postérieur."},{"t":"Il se renforce systématiquement après une diastole longue, comme le souffle du RA.","ok":false,"why":"C'est au contraire une caractéristique distinctive : le souffle d'IM ne se renforce pas après une diastole longue."},{"t":"Son intensité est toujours strictement proportionnelle à la sévérité de la fuite.","ok":false,"why":"L'intensité n'est pas toujours corrélée à la sévérité, notamment dans l'IM secondaire où le souffle peut être discret."},{"t":"Il peut irradier vers la base en cas de prolapsus du feuillet postérieur.","ok":true,"why":"Dans ce cas particulier, le jet est dirigé vers le septum interatrial et l'aorte, modifiant l'irradiation."}],"explanation":"Le souffle de l'IM est holosystolique, apexien, irradiant classiquement à l'aisselle et ne se renforçant pas après une diastole longue (contrairement au RA) ; son intensité n'est pas toujours proportionnelle à la sévérité, et l'irradiation peut se faire vers la base en cas de prolapsus postérieur.","src":"p. 214"},{"id":"233-qru-105","type":"QRU","rank":"A","objective":"233-obj-03","tags":["clinique"],"difficulty":1,"stem":"Quel signe auscultatoire précède classiquement le souffle télésystolique d'un prolapsus mitral ?","options":[{"t":"Un éclat de B1.","ok":false,"why":"Ce n'est pas le signe classiquement décrit avant le souffle de prolapsus."},{"t":"Un clic mésosystolique.","ok":true,"why":"Le clic, lié à la mise en tension brutale des cordages, précède le souffle méso- ou télésystolique du prolapsus."},{"t":"Un galop B4.","ok":false,"why":"Ce signe n'est pas spécifiquement associé au prolapsus mitral."},{"t":"Un frottement péricardique.","ok":false,"why":"Ce signe évoque une péricardite, pas un prolapsus valvulaire mitral."},{"t":"Un souffle continu.","ok":false,"why":"Ce type de souffle évoque une autre pathologie, comme un canal artériel persistant."}],"explanation":"Dans le prolapsus mitral, la mise en tension brutale des cordages produit un clic mésosystolique, suivi d'un souffle méso- ou télésystolique de régurgitation.","src":"p. 215"},{"id":"233-qcm-108","type":"QRM","rank":"A","objective":"233-obj-04","tags":["paraclinique","diagnostic"],"difficulty":2,"stem":"Concernant l'évaluation échocardiographique de la sévérité de l'IM primaire, quelles propositions sont exactes ?","options":[{"t":"La méthode PISA permet d'estimer la surface de l'orifice régurgitant (SOR).","ok":true,"why":"C'est la méthode de référence pour quantifier l'orifice régurgitant."},{"t":"Une IM primaire est considérée comme significative dès le grade II (modérée).","ok":false,"why":"L'IM primaire significative correspond aux grades III (moyenne) et IV (importante), pas au grade II."},{"t":"Le grade IV (importante) correspond à une SOR supérieure ou égale à 40 mm².","ok":true,"why":"C'est le seuil retenu pour le grade le plus sévère selon la classification en 4 grades."},{"t":"Le volume régurgité du grade IV est supérieur ou égal à 60 mL.","ok":true,"why":"Ce volume accompagne la SOR ≥ 40 mm² pour définir l'IM primaire importante."},{"t":"Le doppler couleur ne joue aucun rôle dans le diagnostic positif de l'IM.","ok":false,"why":"Le doppler couleur, avec le doppler pulsé et continu, participe au diagnostic positif du reflux systolique."}],"explanation":"La sévérité de l'IM primaire est quantifiée en 4 grades par la méthode PISA (SOR et volume régurgité) : l'IM est dite significative à partir du grade III (moyenne), le grade IV (importante) correspondant à une SOR ≥ 40 mm² et un volume régurgité ≥ 60 mL.","src":"p. 217-218"},{"id":"233-qru-106","type":"QRU","rank":"A","objective":"233-obj-04","tags":["paraclinique"],"difficulty":2,"stem":"Quel diamètre télésystolique du VG (DTS) justifie la correction d'une IM primaire même chez l'asymptomatique ?","options":[{"t":"> 30 mm","ok":false,"why":"Ce seuil est inférieur à celui retenu comme critère de retentissement."},{"t":"> 40 mm","ok":true,"why":"Un DTS VG supérieur à 40 mm est l'un des critères de retentissement justifiant la correction."},{"t":"> 55 mm","ok":false,"why":"Ce chiffre est trop élevé par rapport au seuil réellement retenu."},{"t":"> 60 mm","ok":false,"why":"Ce chiffre ne correspond pas au seuil utilisé dans l'IM."},{"t":"Il n'existe pas de seuil de DTS utilisé en pratique dans l'IM.","ok":false,"why":"Un tel seuil existe bien et fait partie des critères de retentissement."}],"explanation":"Un diamètre télésystolique du VG supérieur à 40 mm, tout comme une FEVG inférieure à 60 %, un volume de l'atrium gauche ≥ 60 mL/m² ou une PAP systolique ≥ 50 mmHg, justifie la correction de l'IM primaire même chez l'asymptomatique.","src":"p. 217-218"},{"id":"233-qcm-109","type":"QRM","rank":"A","objective":"233-obj-04","tags":["paraclinique","pièges"],"difficulty":2,"stem":"Concernant la quantification de l'IM secondaire, quelles propositions sont exactes ?","options":[{"t":"Le seuil de sévérité (SOR) est plus bas que pour l'IM primaire.","ok":true,"why":"Une SOR ≥ 30 mm² suffit à définir une IM secondaire significative, contre 40 mm² pour l'IM primaire."},{"t":"La fuite doit être évaluée à distance de toute optimisation du traitement de l'insuffisance cardiaque.","ok":false,"why":"Au contraire, l'évaluation doit être répétée après optimisation du traitement, la fuite variant avec la volémie."},{"t":"La sévérité peut varier d'un examen à l'autre selon l'état volémique du patient.","ok":true,"why":"La fuite « accordéon » de l'IM secondaire dépend fortement des conditions de charge."},{"t":"Un anneau tricuspide supérieur à 40 mm en 4 cavités fait discuter une annuloplastie associée.","ok":true,"why":"C'est le seuil retenu pour associer un geste tricuspide à la chirurgie mitrale."},{"t":"La méthode PISA n'est jamais utilisable pour l'IM secondaire.","ok":false,"why":"La méthode PISA reste utilisée pour quantifier l'IM secondaire, avec un seuil de sévérité différent."}],"explanation":"L'IM secondaire est jugée significative dès une SOR ≥ 30 mm² (contre 40 mm² pour l'IM primaire) et doit être évaluée après optimisation du traitement de l'insuffisance cardiaque, la fuite variant avec la volémie ; un anneau tricuspide > 40 mm en 4 cavités fait discuter une annuloplastie associée.","src":"p. 218","trap":"Évaluer une IM secondaire chez un patient encore en surcharge expose à surestimer la fuite."},{"id":"233-qcm-110","type":"QRM","rank":"A","objective":"233-obj-06","tags":["ECG","imagerie"],"difficulty":1,"stem":"Concernant l'ECG et la radiographie thoracique dans l'IM, quelles propositions sont exactes ?","options":[{"t":"L'ECG peut rester longtemps normal.","ok":true,"why":"L'ECG de l'IM peut être normal pendant une longue période avant l'apparition d'anomalies."},{"t":"Une hypertrophie atriale gauche et une FA peuvent s'observer à l'ECG.","ok":true,"why":"La dilatation de l'atrium gauche favorise ces anomalies électriques."},{"t":"La radiographie peut montrer une dilatation de l'atrium gauche avec un arc moyen gauche convexe.","ok":true,"why":"C'est un signe radiologique classique de dilatation atriale gauche."},{"t":"Des lignes de Kerley peuvent s'observer en cas d'hypertension pulmonaire ou d'insuffisance cardiaque.","ok":true,"why":"Ces lignes traduisent un œdème interstitiel lié à la congestion pulmonaire."},{"t":"L'ECG est toujours pathologique dès le stade initial de l'IM.","ok":false,"why":"L'ECG peut au contraire rester longtemps normal, même en cas d'IM significative."}],"explanation":"L'ECG de l'IM peut rester longtemps normal puis montrer une hypertrophie atriale gauche, une HVG ou une FA ; la radiographie thoracique peut objectiver une cardiomégalie, une dilatation de l'atrium gauche et des signes de surcharge pulmonaire (lignes de Kerley) en cas d'IM évoluée.","src":"p. 214"},{"id":"233-qcm-111","type":"QRM","rank":"A","objective":"233-obj-06","tags":["paraclinique"],"difficulty":2,"stem":"Concernant le bilan coronaire dans l'IM, quelles propositions sont exactes ?","options":[{"t":"Un coroscanner peut être proposé en première intention si la probabilité prétest de coronaropathie est faible.","ok":true,"why":"Le coroscanner est adapté aux patients à faible probabilité prétest de maladie coronaire."},{"t":"Une coronarographie est indiquée en cas de suspicion d'ischémie ou de baisse de la FEVG.","ok":true,"why":"Ces situations justifient une exploration coronaire invasive."},{"t":"L'âge (homme > 40 ans, femme ménopausée) et les facteurs de risque sont des critères d'indication de la coronarographie.","ok":true,"why":"Ces critères rejoignent ceux utilisés dans les autres valvulopathies avant chirurgie."},{"t":"La ventriculographie reste l'examen de référence pour quantifier l'IM.","ok":false,"why":"La ventriculographie est abandonnée ; l'échocardiographie est désormais l'examen de référence."},{"t":"Le cathétérisme droit n'apporte jamais d'information utile dans l'IM.","ok":false,"why":"Le cathétérisme droit peut être utile pour mesurer le débit et les pressions droites dans certains cas."}],"explanation":"Le coroscanner est proposé en première intention si la probabilité prétest est faible ; la coronarographie reste indiquée en cas de suspicion d'ischémie, de baisse de FEVG, ou selon l'âge et les facteurs de risque, tandis que la ventriculographie a été abandonnée au profit de l'échocardiographie.","src":"p. 219"},{"id":"233-qcm-112","type":"QRM","rank":"A","objective":"233-obj-04","tags":["diagnostic","urgence"],"difficulty":1,"stem":"Dans quelle situation l'échocardiographie transœsophagienne (ETO) est-elle indispensable pour le diagnostic d'IM ?","options":[{"t":"En cas de suspicion d'endocardite infectieuse.","ok":true,"why":"L'ETO est obligatoire pour détecter des végétations fines et confirmer une endocardite."},{"t":"Pour planifier la faisabilité d'une plastie mitrale.","ok":true,"why":"L'ETO précise le mécanisme et guide la stratégie chirurgicale, en particulier en vue d'une plastie."},{"t":"En cas de suspicion de rupture partielle de cordage.","ok":true,"why":"L'ETO améliore la visualisation des ruptures partielles de cordages difficiles à voir en ETT."},{"t":"Systématiquement pour toute IM minime découverte fortuitement.","ok":false,"why":"L'ETT suffit en général pour une IM minime, l'ETO n'étant pas systématique dans cette situation."},{"t":"Uniquement en cas de contre-indication à l'ETT.","ok":false,"why":"L'ETO est indiquée pour des raisons diagnostiques précises, pas seulement en cas de contre-indication à l'ETT."}],"explanation":"L'ETO est obligatoire en cas de suspicion d'endocardite (recherche de végétations), utile pour préciser le mécanisme et la faisabilité d'une plastie, et pour visualiser des ruptures partielles de cordages ou des segments prolabés mal vus en ETT.","src":"p. 217"},{"id":"233-qcm-113","type":"QRM","rank":"A","objective":"233-obj-07","tags":["complications","suivi"],"difficulty":2,"stem":"Concernant l'évolution naturelle de l'IM, quelles propositions sont exactes ?","options":[{"t":"Une IM progressive est en général longtemps bien tolérée avant l'apparition d'une insuffisance cardiaque.","ok":true,"why":"L'évolution progressive permet une adaptation prolongée avant décompensation."},{"t":"Une IM brutale (rupture de cordage, endocardite, infarctus) est en général mal tolérée avec un OAP rapide.","ok":true,"why":"L'absence d'adaptation atriale et ventriculaire explique la mauvaise tolérance des formes aiguës."},{"t":"La fibrillation atriale favorisée par la dilatation de l'atrium gauche justifie une chirurgie précoce chez l'asymptomatique.","ok":true,"why":"La survenue d'une FA, même paroxystique, est un argument de retentissement justifiant l'intervention."},{"t":"Le suivi échographique annuel n'est nécessaire qu'en cas d'IM sévère symptomatique déjà opérée.","ok":false,"why":"Une IM significative asymptomatique nécessite un suivi clinique et échographique annuel, non réservé aux formes opérées."},{"t":"Les troubles du rythme ventriculaire sont plus fréquents que la FA au cours de l'IM.","ok":false,"why":"C'est l'inverse : la FA est plus fréquente que les troubles du rythme ventriculaire, plus rares."}],"explanation":"L'IM progressive est longtemps bien tolérée, contrairement aux formes brutales (rupture de cordage, endocardite, infarctus) responsables d'un OAP rapide ; la FA, favorisée par la dilatation atriale, justifie une chirurgie précoce même chez l'asymptomatique et impose un suivi échographique annuel des formes non opérées.","src":"p. 219-220"},{"id":"233-qcm-114","type":"QRM","rank":"A","objective":"233-obj-08","tags":["traitement"],"difficulty":2,"stem":"Concernant la chirurgie de l'IM, quelles propositions sont exactes ?","options":[{"t":"La plastie reconstructrice est considérée comme le traitement idéal lorsqu'elle est réalisable.","ok":true,"why":"Elle respecte l'appareil sous-valvulaire et s'associe à moins de dysfonction VG et de risque d'endocardite."},{"t":"Elle est indiquée en priorité en cas de prolapsus, avec ou sans rupture.","ok":true,"why":"Le prolapsus se prête particulièrement bien à une réparation conservatrice."},{"t":"Elle est toujours facilement réalisable, y compris dans les IM rhumatismales évoluées.","ok":false,"why":"La plastie reste possible mais difficile et expose à un risque de récidive dans certaines IM rhumatismales."},{"t":"En cas de remplacement, la bioprothèse est généralement proposée chez le sujet âgé.","ok":true,"why":"Elle évite l'anticoagulation au prix d'une dégénérescence progressive, ce qui la fait préférer après 70 ans."},{"t":"La prothèse mécanique est réservée aux patients jeunes ou en FA associée.","ok":true,"why":"Sa longue durabilité justifie ce choix chez le sujet jeune, au prix d'une anticoagulation à vie."}],"explanation":"La plastie reconstructrice est le traitement idéal de l'IM, en particulier dans le prolapsus, mais reste difficile dans certaines IM rhumatismales évoluées ; en cas de remplacement, la bioprothèse est proposée chez le sujet âgé et la prothèse mécanique chez le sujet jeune ou en FA.","src":"p. 220"},{"id":"233-qru-107","type":"QRU","rank":"A","objective":"233-obj-08","tags":["traitement","pièges"],"difficulty":3,"stem":"Chez un patient ayant une IM primaire sévère symptomatique avec une FEVG à 28 %, quelle est l'attitude adaptée si la plastie n'est pas réalisable ?","options":[{"t":"Réaliser un remplacement valvulaire mitral en première intention.","ok":false,"why":"Le remplacement valvulaire est contre-indiqué en dessous de 30 % de FEVG en raison de la chute postopératoire attendue."},{"t":"Privilégier un traitement médical ou discuter une transplantation si le patient est jeune, le remplacement étant contre-indiqué.","ok":true,"why":"En dessous de 30 % de FEVG, la chute postopératoire de 10 à 15 % expose à une dysfonction sévère, contre-indiquant le remplacement."},{"t":"Proposer systématiquement une valvuloplastie mitrale au ballon.","ok":false,"why":"Cette technique n'est pas celle utilisée pour l'IM et n'est pas l'option retenue ici."},{"t":"Attendre une aggravation supplémentaire avant toute décision.","ok":false,"why":"Ce n'est pas l'attitude recommandée ; un traitement médical ou une orientation spécialisée doit être envisagée sans délai."},{"t":"Considérer que la FEVG basse n'a aucune influence sur la décision chirurgicale.","ok":false,"why":"La FEVG basse influence au contraire fortement la décision, en contre-indiquant le remplacement."}],"explanation":"Lorsque la plastie n'est pas réalisable dans une IM primaire sévère symptomatique avec une FEVG inférieure à 30 %, le remplacement valvulaire est contre-indiqué en raison de la chute postopératoire attendue de la FEVG ; un traitement médical, voire une transplantation chez le sujet jeune, est alors discuté.","src":"p. 222","trap":"Remplacer la valve avec une FE < 30 % expose à une dysfonction ventriculaire sévère postopératoire."},{"id":"233-qcm-115","type":"QRM","rank":"A","objective":"233-obj-09","tags":["traitement"],"difficulty":2,"stem":"Concernant le traitement percutané de l'IM, quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'une réparation bord à bord par clip.","ok":true,"why":"C'est la technique percutanée de référence pour l'IM, primaire ou secondaire."},{"t":"Il peut être proposé en cas d'IM primaire ou secondaire chez un patient à haut risque chirurgical.","ok":true,"why":"C'est l'indication principale retenue pour cette technique."},{"t":"La décision se prend en dehors de toute concertation pluridisciplinaire.","ok":false,"why":"Au contraire, la décision doit passer par une Heart Team ou une « clinique des valves »."},{"t":"Il constitue le traitement de première intention chez tout patient opérable.","ok":false,"why":"Le traitement percutané n'est envisagé qu'en cas de haut risque ou de contre-indication chirurgicale."},{"t":"Des registres et essais randomisés récents ont précisé ses bénéfices dans les IM primaires et secondaires.","ok":true,"why":"Ces données ont permis de mieux cerner les indications de la technique selon le mécanisme de l'IM."}],"explanation":"Le traitement percutané de l'IM (réparation bord à bord par clip) peut être proposé en cas d'IM primaire ou secondaire chez un patient à haut risque ou contre-indiqué à la chirurgie, toujours après discussion en Heart Team ou clinique des valves ; des registres et essais randomisés récents en ont précisé les bénéfices.","src":"p. 221"},{"id":"233-qcm-116","type":"QRM","rank":"A","objective":"233-obj-10","tags":["traitement"],"difficulty":2,"stem":"Quelles situations justifient une chirurgie chez un patient porteur d'une IM primaire importante (grade III-IV) mais asymptomatique ?","options":[{"t":"Un DTS VG supérieur à 40 mm avec rupture de cordage.","ok":true,"why":"C'est l'un des critères de retentissement justifiant l'intervention malgré l'absence de symptôme."},{"t":"Une FEVG inférieure à 60 %.","ok":true,"why":"Ce seuil abaissé, spécifique à l'IM, traduit déjà une dysfonction justifiant l'intervention."},{"t":"Une fibrillation atriale, même paroxystique.","ok":true,"why":"La survenue d'une FA, quelle que soit sa forme, est un argument de retentissement à opérer."},{"t":"Une PAP systolique supérieure à 50 mmHg au repos.","ok":true,"why":"Ce seuil d'hypertension pulmonaire au repos justifie également l'intervention chez l'asymptomatique."},{"t":"L'absence de tout signe de retentissement.","ok":false,"why":"En l'absence de tout critère de retentissement, la surveillance semestrielle est préférée à la chirurgie."}],"explanation":"Chez l'asymptomatique porteur d'une IM primaire importante, la chirurgie est indiquée dès qu'un signe de retentissement apparaît : DTS VG > 40 mm avec rupture de cordage, FEVG < 60 %, PAP systolique > 50 mmHg au repos ou FA même paroxystique ; en leur absence, une surveillance semestrielle est proposée.","src":"p. 220"},{"id":"233-qcm-117","type":"QRM","rank":"A","objective":"233-obj-09","tags":["traitement"],"difficulty":2,"stem":"Concernant la prise en charge de l'IM secondaire, quelles propositions sont exactes ?","options":[{"t":"Le traitement de l'insuffisance cardiaque (médicaments, resynchronisation) est proposé en première intention.","ok":true,"why":"L'optimisation du traitement médical de l'IC précède toute intervention sur la valve."},{"t":"Une intervention (plutôt percutanée) est envisagée en cas d'échec du traitement médical.","ok":true,"why":"Le clip est privilégié en seconde intention lorsque le traitement médical ne suffit pas."},{"t":"La resynchronisation cardiaque peut être proposée en cas de QRS larges.","ok":true,"why":"Elle fait partie de l'optimisation thérapeutique de l'insuffisance cardiaque sous-jacente."},{"t":"La chirurgie conventionnelle est systématiquement préférée au traitement médical d'emblée.","ok":false,"why":"Le traitement médical de l'IC est la première étape ; l'intervention n'intervient qu'en cas d'échec."},{"t":"Aucune surveillance particulière n'est nécessaire tant que le traitement médical est bien conduit.","ok":false,"why":"Une surveillance clinique et échographique reste nécessaire même sous traitement médical bien conduit."}],"explanation":"L'IM secondaire est d'abord traitée médicalement (traitement de l'insuffisance cardiaque, resynchronisation si QRS larges) ; une intervention, plutôt percutanée, n'est discutée qu'en cas d'échec de cette optimisation.","src":"p. 220"},{"id":"233-qru-108","type":"QRU","rank":"A","objective":"233-obj-04","tags":["diagnostic"],"difficulty":1,"stem":"Quel anneau tricuspide mesuré en coupe apicale 4 cavités fait discuter une annuloplastie tricuspide lors d'une chirurgie mitrale ?","options":[{"t":"> 30 mm","ok":false,"why":"Ce chiffre est inférieur au seuil réellement retenu."},{"t":"> 40 mm","ok":true,"why":"Un anneau tricuspide supérieur à 40 mm en 4 cavités fait discuter un geste tricuspide associé."},{"t":"> 50 mm","ok":false,"why":"Ce chiffre est supérieur au seuil habituellement utilisé."},{"t":"> 60 mm","ok":false,"why":"Ce chiffre n'est pas le seuil retenu en pratique."},{"t":"Il n'existe pas de seuil utilisé en pratique.","ok":false,"why":"Un tel seuil existe bien et guide la décision d'un geste tricuspide associé."}],"explanation":"Un anneau tricuspide dilaté au-delà de 40 mm en coupe apicale 4 cavités, même en l'absence de fuite tricuspide sévère, fait discuter une annuloplastie tricuspide associée à la chirurgie mitrale.","src":"p. 218"},{"id":"233-qcm-118","type":"QRM","rank":"A","objective":"233-obj-07","tags":["prévention"],"difficulty":1,"stem":"Concernant la surveillance et la prévention dans l'IM peu sévère (grade I-II), quelles propositions sont exactes ?","options":[{"t":"Une réévaluation clinique et échographique régulière est recommandée.","ok":true,"why":"Un suivi régulier permet de détecter une éventuelle progression de la fuite."},{"t":"Une antibioprophylaxie systématique de l'endocardite est recommandée.","ok":false,"why":"L'antibioprophylaxie n'est pas systématique ; seules l'hygiène cutanée et dentaire sont recommandées."},{"t":"Une hygiène cutanée et des soins dentaires réguliers sont recommandés.","ok":true,"why":"Ces mesures d'hygiène participent à la prévention de l'endocardite infectieuse."},{"t":"Aucun suivi n'est nécessaire tant que le patient reste asymptomatique.","ok":false,"why":"Un suivi régulier reste recommandé même en l'absence de symptôme."},{"t":"Un traitement chirurgical est proposé d'emblée dès le diagnostic.","ok":false,"why":"Une IM de grade I-II ne justifie pas de traitement chirurgical d'emblée, seulement une surveillance."}],"explanation":"Une IM de grade I-II relève d'une simple surveillance clinique et échographique régulière, associée à des mesures d'hygiène cutanée et dentaire pour prévenir l'endocardite, sans antibioprophylaxie systématique ni indication chirurgicale d'emblée.","src":"p. 220"},{"id":"233-qcm-119","type":"QRM","rank":"A","objective":"233-obj-04","tags":["paraclinique"],"difficulty":1,"stem":"Concernant l'écho d'effort ou l'épreuve d'effort dans l'IM, quelles propositions sont exactes ?","options":[{"t":"Leurs indications restent imprécises dans l'IM.","ok":true,"why":"Le texte souligne que la place de ces examens reste mal codifiée dans l'IM."},{"t":"Elles peuvent aider à démasquer des symptômes non rapportés spontanément.","ok":true,"why":"Elles participent, comme dans d'autres valvulopathies, à révéler une intolérance méconnue."},{"t":"Elles permettent d'apprécier la fuite et les pressions pulmonaires à l'effort.","ok":true,"why":"L'écho d'effort renseigne sur le comportement dynamique de la fuite et des pressions."},{"t":"Elles remplacent systématiquement l'échocardiographie de repos.","ok":false,"why":"Ces examens sont un complément et ne remplacent pas l'ETT de repos, examen clé du diagnostic."},{"t":"Elles sont contre-indiquées chez tout patient porteur d'une IM.","ok":false,"why":"Elles ne sont pas contre-indiquées de façon systématique, seulement d'indication imprécise."}],"explanation":"L'épreuve d'effort, la VO2 ou l'écho d'effort ont des indications imprécises dans l'IM ; elles peuvent néanmoins aider à démasquer des symptômes méconnus et à apprécier le comportement de la fuite et des pressions pulmonaires à l'effort, sans remplacer l'ETT de repos.","src":"p. 219"},{"id":"233-qcm-120","type":"QRM","rank":"A","objective":"233-obj-03","tags":["clinique"],"difficulty":2,"stem":"Concernant les circonstances de découverte de l'IM, quelles propositions sont exactes ?","options":[{"t":"Un souffle systolique systématique peut révéler une IM.","ok":true,"why":"La découverte fortuite lors de l'auscultation est une circonstance fréquente."},{"t":"Une IM sévère peut rester totalement asymptomatique.","ok":true,"why":"Certaines IM importantes restent longtemps silencieuses sur le plan fonctionnel."},{"t":"L'OAP est un mode de révélation précoce et bénin de l'IM.","ok":false,"why":"L'OAP est au contraire un mode de révélation tardif et grave, marquant un tournant évolutif."},{"t":"Une fièvre prolongée peut faire découvrir une IM dans le cadre d'une endocardite.","ok":true,"why":"Une endocardite peut se révéler par une fièvre prolongée associée à un souffle."},{"t":"Les palpitations ou une dyspnée d'effort peuvent être les premiers signes.","ok":true,"why":"Ce sont des signes fonctionnels précoces possibles, en dehors de toute complication."}],"explanation":"L'IM peut être découverte devant un souffle systolique systématique, des palpitations, une dyspnée ou une asthénie d'effort, une complication (OAP tardif et grave, FA) ou une fièvre prolongée évoquant une endocardite ; une IM sévère peut rester longtemps asymptomatique.","src":"p. 214"},{"id":"233-qroc-101","type":"QROC","rank":"A","objective":"233-obj-01","tags":["définition"],"difficulty":1,"question":"Comment définir l'insuffisance mitrale en une phrase ?","answer":"Reflux systolique de sang du ventricule gauche vers l'atrium gauche par défaut d'étanchéité de la valve mitrale.","accept":["reflux systolique vg vers ag"],"keywords":["reflux","systolique","mitrale"],"explanation":"L'IM correspond à un défaut d'étanchéité de la valve mitrale entraînant un reflux du VG vers l'atrium gauche en systole.","src":"p. 209"},{"id":"233-qroc-102","type":"QROC","rank":"A","objective":"233-obj-01","tags":["diagnostic"],"difficulty":1,"question":"Nommer les deux feuillets de la valve mitrale.","answer":"Le feuillet antérieur (grande valve) et le feuillet postérieur (petite valve).","accept":["feuillet anterieur et posterieur"],"keywords":["antérieur","postérieur","feuillet"],"explanation":"La valve mitrale comporte deux feuillets, antérieur (grande valve) et postérieur (petite valve), insérés sur un anneau fibreux.","src":"p. 209"},{"id":"233-qroc-103","type":"QROC","rank":"A","objective":"233-obj-01","tags":["physiopathologie"],"difficulty":2,"question":"Quel type de Carpentier correspond à l'IM secondaire des cardiopathies dilatées ou ischémiques ?","answer":"Le type IIIb.","accept":["type iiib","3b"],"keywords":["iiib","type"],"explanation":"L'IM secondaire des cardiopathies dilatées ou ischémiques correspond au type IIIb de Carpentier, restriction du jeu valvulaire en systole par éloignement des piliers.","src":"p. 210"},{"id":"233-qroc-104","type":"QROC","rank":"A","objective":"233-obj-05","tags":["physiopathologie"],"difficulty":2,"question":"À partir de quel seuil de FEVG parle-t-on de dysfonction VG dans l'IM ?","answer":"FEVG inférieure à 60 %.","accept":["< 60%","moins de 60"],"keywords":["60","fevg"],"explanation":"Du fait de la surestimation de la FEVG dans l'IM (VG déchargé dans l'atrium gauche), on parle de dysfonction dès que la FEVG passe sous 60 %.","src":"p. 210"},{"id":"233-qroc-105","type":"QROC","rank":"A","objective":"233-obj-02","tags":["étiologie"],"difficulty":1,"question":"Quelle est la cause la plus fréquente des IM primaires sévères ?","answer":"L'IM dystrophique par prolapsus valvulaire.","accept":["prolapsus dystrophique"],"keywords":["prolapsus","dystrophique"],"explanation":"L'IM primaire dystrophique par prolapsus (Carpentier II) est la cause la plus fréquente des fuites mitrales sévères.","src":"p. 211"},{"id":"233-qroc-106","type":"QROC","rank":"A","objective":"233-obj-02","tags":["étiologie"],"difficulty":2,"question":"Quelle maladie associe des valves myxoïdes redondantes et hypermobiles avec excès de tissu ?","answer":"La maladie de Barlow (dégénérescence myxoïde).","accept":["barlow","degenerescence myxoide"],"keywords":["barlow","myxoïde"],"explanation":"La maladie de Barlow correspond à une dégénérescence myxoïde avec excès de tissu, valves redondantes et épaissies, et ruptures de cordages par traction.","src":"p. 212"},{"id":"233-qroc-107","type":"QROC","rank":"A","objective":"233-obj-02","tags":["urgence"],"difficulty":2,"question":"Citer deux causes classiques d'IM aiguë.","answer":"Rupture de cordage et rupture (ou dysfonction) de pilier post-infarctus.","accept":["rupture de cordage, rupture de pilier"],"keywords":["rupture","cordage","pilier"],"explanation":"Les causes classiques d'IM aiguë sont la rupture de cordage, la rupture ou dysfonction de pilier post-infarctus, le traumatisme thoracique et la perforation par endocardite.","src":"p. 213-214"},{"id":"233-qroc-108","type":"QROC","rank":"A","objective":"233-obj-03","tags":["clinique"],"difficulty":1,"question":"Où irradie classiquement le souffle systolique de l'insuffisance mitrale ?","answer":"Vers l'aisselle (irradiation axillaire).","accept":["aisselle","axillaire"],"keywords":["aisselle","irradiation"],"explanation":"Le souffle holosystolique de l'IM, maximal à la pointe, irradie classiquement vers l'aisselle (sauf en cas de prolapsus postérieur, où l'irradiation se fait vers la base).","src":"p. 214"},{"id":"233-qroc-109","type":"QROC","rank":"A","objective":"233-obj-04","tags":["paraclinique"],"difficulty":2,"question":"Quelle méthode échographique permet de calculer la surface de l'orifice régurgitant (SOR) dans l'IM ?","answer":"La méthode PISA.","accept":["pisa"],"keywords":["pisa"],"explanation":"La méthode PISA permet de calculer la surface de l'orifice régurgitant (SOR), critère central de la quantification échographique de l'IM.","src":"p. 217"},{"id":"233-qroc-110","type":"QROC","rank":"A","objective":"233-obj-04","tags":["paraclinique"],"difficulty":2,"question":"Quel diamètre télésystolique du VG justifie la correction d'une IM primaire asymptomatique ?","answer":"Supérieur à 40 mm.","accept":["> 40 mm"],"keywords":["40","mm","dts"],"explanation":"Un diamètre télésystolique du VG supérieur à 40 mm est l'un des critères de retentissement justifiant la correction d'une IM primaire, même chez l'asymptomatique.","src":"p. 217-218"},{"id":"233-qroc-111","type":"QROC","rank":"A","objective":"233-obj-04","tags":["paraclinique"],"difficulty":2,"question":"Quel seuil de SOR définit la sévérité d'une IM secondaire ?","answer":"SOR supérieure ou égale à 30 mm².","accept":["sor >= 30 mm2"],"keywords":["30","mm2","sor"],"explanation":"Le seuil de sévérité retenu pour l'IM secondaire est une SOR ≥ 30 mm², plus bas que celui de l'IM primaire (≥ 40 mm²).","src":"p. 218"},{"id":"233-qroc-112","type":"QROC","rank":"A","objective":"233-obj-04","tags":["paraclinique"],"difficulty":1,"question":"Quel diamètre d'anneau tricuspide, en coupe 4 cavités, fait discuter une annuloplastie tricuspide associée ?","answer":"Supérieur à 40 mm.","accept":["> 40 mm"],"keywords":["40","mm","tricuspide"],"explanation":"Un anneau tricuspide dilaté au-delà de 40 mm en coupe apicale 4 cavités fait discuter une annuloplastie tricuspide associée lors de la chirurgie mitrale.","src":"p. 218"},{"id":"233-open-11","type":"OPEN","rank":"A","objective":"233-obj-01","tags":["diagnostic","clinique","paraclinique"],"difficulty":2,"prompt":"Une femme de 62 ans présente une dyspnée d'effort progressive. L'auscultation retrouve un souffle holosystolique apexien irradiant à l'aisselle. Décrivez la démarche permettant d'affirmer une IM primaire sévère et d'en préciser le retentissement.","rubric":[{"point":"Évoquer une IM devant le souffle holosystolique apexo-axillaire","weight":2},{"point":"Rechercher un clic mésosystolique évocateur de prolapsus","weight":1},{"point":"Demander une ETT comme examen clé (positif, étiologique, sévérité, retentissement)","weight":2},{"point":"Citer la méthode PISA et les grades de sévérité de l'IM primaire","weight":2},{"point":"Évaluer le retentissement VG (DTS > 40 mm, FEVG < 60 %) et l'atrium gauche/PAP","weight":2}],"model":"Devant une dyspnée d'effort avec souffle holosystolique apexo-axillaire, on évoque une IM, en recherchant un éventuel clic mésosystolique orientant vers un prolapsus. L'ETT est l'examen clé : elle confirme le reflux systolique, précise le mécanisme selon Carpentier, quantifie la sévérité par la méthode PISA (grade III-IV = IM significative) et évalue le retentissement VG (DTS > 40 mm, FEVG < 60 %), l'atrium gauche et la PAP systolique, éléments qui conditionnent l'indication opératoire même en l'absence de symptôme franc.","src":"p. 214-218"},{"id":"233-open-12","type":"OPEN","rank":"A","objective":"233-obj-02","tags":["étiologie"],"difficulty":2,"prompt":"Distinguez les mécanismes de l'IM primaire (organique) et de l'IM secondaire (fonctionnelle), en donnant un exemple étiologique pour chacun.","rubric":[{"point":"Définir l'IM primaire : lésion des feuillets ou des cordages","weight":2},{"point":"Donner un exemple d'IM primaire (dystrophique par prolapsus, rhumatismale)","weight":1},{"point":"Définir l'IM secondaire : feuillets normaux, anomalie du ventricule ou de l'anneau","weight":2},{"point":"Donner un exemple d'IM secondaire (ischémique post-infarctus inférieur, IM atriale)","weight":1}],"model":"L'IM primaire correspond à une lésion organique des feuillets ou des cordages, comme dans l'IM dystrophique par prolapsus (Barlow ou dégénérescence fibroélastique) ou l'IM rhumatismale. L'IM secondaire touche des feuillets anatomiquement normaux et résulte d'une anomalie du ventricule (déplacement des piliers, par exemple après un infarctus inférieur) ou de l'anneau (dilatation sur un atrium gauche très dilaté, IM dite atriale).","src":"p. 211-213"},{"id":"233-open-13","type":"OPEN","rank":"A","objective":"233-obj-04","tags":["paraclinique","diagnostic"],"difficulty":3,"prompt":"Quels sont les critères échocardiographiques de retentissement de l'IM chronique qui orientent vers une correction chez un patient asymptomatique ?","rubric":[{"point":"Diamètre télésystolique du VG > 40 mm","weight":2},{"point":"FEVG < 60 %","weight":2},{"point":"Volume de l'atrium gauche ≥ 60 mL/m²","weight":1},{"point":"PAP systolique ≥ 50 mmHg","weight":1},{"point":"Survenue d'une fibrillation atriale, même paroxystique","weight":1}],"model":"Chez un patient asymptomatique porteur d'une IM primaire importante, la correction est envisagée dès qu'apparaît un signe de retentissement : DTS VG > 40 mm, FEVG < 60 % (seuil abaissé car surestimée dans l'IM), volume de l'atrium gauche ≥ 60 mL/m² en rythme sinusal, PAP systolique ≥ 50 mmHg au repos, ou survenue d'une fibrillation atriale même paroxystique. En l'absence de ces critères, une surveillance clinique et échographique semestrielle est proposée.","src":"p. 217-220"},{"id":"233-open-14","type":"OPEN","rank":"A","objective":"233-obj-07","tags":["complications","suivi"],"difficulty":2,"prompt":"Décrivez l'évolution naturelle de l'IM non traitée et les principales complications à redouter.","rubric":[{"point":"Opposer évolution progressive (bien tolérée longtemps) et évolution brutale (mal tolérée, OAP rapide)","weight":2},{"point":"Citer la fibrillation atriale comme complication favorisée par la dilatation de l'atrium gauche","weight":2},{"point":"Citer l'insuffisance cardiaque tardive ou aiguë selon le mode évolutif","weight":2},{"point":"Mentionner le risque de rupture de cordage et d'endocardite aggravant la fuite","weight":1}],"model":"L'IM progressive est en général longtemps bien tolérée avant l'apparition d'une insuffisance cardiaque tardive, alors qu'une IM brutale (rupture de cordage, endocardite, infarctus) est mal tolérée avec un œdème pulmonaire aigu rapide. La dilatation de l'atrium gauche favorise la survenue d'une fibrillation atriale, elle-même facteur de décompensation et argument pour une chirurgie précoce. L'endocardite infectieuse peut aggraver une fuite préexistante, et les troubles du rythme ventriculaire restent plus rares, liés à la dysfonction VG.","src":"p. 219-220"},{"id":"233-qcm-201","type":"QRM","rank":"B","objective":"233-obj-08","tags":["traitement"],"difficulty":1,"stem":"Concernant le choix d'une prothèse valvulaire lors d'un remplacement mitral, quelles propositions sont exactes ?","options":[{"t":"La prothèse mécanique impose un traitement anticoagulant au long cours.","ok":true,"why":"C'est le prix de sa longue durabilité : un AVK à vie est nécessaire."},{"t":"La bioprothèse expose à un risque de dégénérescence à distance.","ok":true,"why":"C'est son principal inconvénient, ce qui la réserve plutôt au patient âgé."},{"t":"Après 70 ans, on s'oriente le plus souvent vers une prothèse mécanique.","ok":false,"why":"C'est l'inverse : après 70 ans la bioprothèse est préférée, la mécanique plutôt avant 65 ans."},{"t":"Une fibrillation atriale associée peut faire préférer une prothèse mécanique, du fait de l'anticoagulation déjà nécessaire.","ok":true,"why":"Si une anticoagulation est de toute façon requise pour la FA, la mécanique perd son inconvénient principal."},{"t":"Le choix ne dépend que de l'âge du patient.","ok":false,"why":"Il dépend aussi du rythme cardiaque, des préférences du patient et du risque du traitement anticoagulant."}],"explanation":"Le choix entre prothèse mécanique (durable mais anticoagulant à vie) et bioprothèse (pas d'anticoagulant mais dégénérescence) dépend de l'âge (bio après 70 ans, mécanique avant 65 ans), du rythme, des préférences du patient et du risque hémorragique.","src":"p. 221"},{"id":"233-qru-201","type":"QRU","rank":"B","objective":"233-obj-09","tags":["traitement"],"difficulty":1,"stem":"Concernant le traitement percutané de l'insuffisance mitrale par clip, quelle proposition est exacte ?","options":[{"t":"Il rapproche par voie percutanée les feuillets mitraux antérieur et postérieur.","ok":true,"why":"C'est le principe de la réparation bord à bord percutanée, recommandations ESC 2021."},{"t":"Il remplace systématiquement la chirurgie en première intention.","ok":false,"why":"Il ne se discute qu'en cas de haut risque ou de contre-indication chirurgicale."},{"t":"Il n'est envisageable que dans les IM secondaires.","ok":false,"why":"Il est envisagé aussi bien dans les IM primaires que secondaires selon les critères d'éligibilité."},{"t":"Il nécessite une anticoagulation à vie comme une prothèse mécanique.","ok":false,"why":"Le clip n'est pas une prothèse mécanique et n'impose pas d'anticoagulation à vie de ce fait."},{"t":"Il dispense du bilan préopératoire habituel.","ok":false,"why":"Le bilan de risque opératoire reste nécessaire avant toute décision de prise en charge."}],"explanation":"Le clip mitral rapproche les feuillets antérieur et postérieur par voie percutanée ; il ne se discute qu'en cas de haut risque ou de contre-indication à la chirurgie, pour des IM primaires comme secondaires.","src":"p. 221"},{"id":"233-qcm-202","type":"QRM","rank":"A","objective":"233-obj-08","tags":["traitement","pièges"],"difficulty":2,"stem":"Concernant le bilan préopératoire avant chirurgie valvulaire mitrale, quelles propositions sont exactes ?","options":[{"t":"Il comporte une imagerie des coronaires par coronarographie ou coroscanner.","ok":true,"why":"C'est un élément systématique du bilan de risque opératoire."},{"t":"Il comporte un échodoppler des troncs supra-aortiques.","ok":true,"why":"Il fait partie du bilan préopératoire standard des valvulopathies."},{"t":"Il peut être limité chez le sujet très âgé, l'avis gériatrique n'étant pas utile.","ok":false,"why":"Au contraire, un avis gériatrique est recherché chez le sujet très âgé pour peser le rapport bénéfice/risque."},{"t":"La recherche de foyers infectieux dentaires et ORL en fait partie.","ok":true,"why":"Une radiographie des sinus et un panoramique dentaire sont recommandés."},{"t":"La fonction rénale et l'état pulmonaire n'ont pas à être évalués avant l'intervention.","ok":false,"why":"La recherche de comorbidités, notamment rénale et pulmonaire, fait partie du bilan."}],"explanation":"Le bilan préopératoire d'une valvulopathie associe une imagerie coronaire, un échodoppler des troncs supra-aortiques, la recherche de foyers infectieux ORL et dentaires, la recherche de comorbidités et, chez le sujet très âgé, un avis gériatrique.","src":"p. 221"},{"id":"233-qcm-203","type":"QRM","rank":"B","objective":"233-obj-11","tags":["traitement"],"difficulty":2,"stem":"Concernant la « clinique des valves » et le Heart Team, quelles propositions sont exactes ?","options":[{"t":"Elle regroupe les expertises cliniques, d'imagerie, de chirurgie, d'anesthésie et de cathétérisme interventionnel.","ok":true,"why":"C'est la définition même d'une clinique des valves pluridisciplinaire."},{"t":"La discussion collégiale permet d'adapter la stratégie à l'expertise de chaque centre.","ok":true,"why":"Les recommandations insistent sur cette discussion pluridisciplinaire avant toute décision."},{"t":"Le recours à une équipe pluridisciplinaire n'est qu'une option facultative sans niveau de preuve particulier.","ok":false,"why":"Il s'agit d'une recommandation de niveau 1 selon l'ESC 2021."},{"t":"Elle concerne uniquement les patients candidats à un remplacement chirurgical.","ok":false,"why":"Elle concerne toutes les options thérapeutiques, y compris percutanées, pour l'IM primaire comme secondaire."},{"t":"Elle s'applique aussi bien aux IM primaires qu'aux IM secondaires.","ok":true,"why":"Le texte précise que ces options concernent les deux types d'IM."}],"explanation":"La clinique des valves réunit cardiologues cliniciens, imageurs, chirurgiens, anesthésistes et interventionnels pour discuter collégialement de la meilleure stratégie ; ce recours à une équipe pluridisciplinaire est une recommandation de niveau 1 (ESC 2021).","src":"p. 221"},{"id":"233-qru-202","type":"QRU","rank":"B","objective":"233-obj-10","tags":["traitement","urgence"],"difficulty":1,"stem":"Concernant une insuffisance mitrale aiguë mal tolérée, quelle proposition est exacte ?","options":[{"t":"Elle impose une chirurgie urgente.","ok":true,"why":"L'IM aiguë mal tolérée est une véritable urgence chirurgicale."},{"t":"Elle se traite toujours médicalement en première intention avant d'envisager un geste.","ok":false,"why":"L'urgence hémodynamique impose au contraire une correction chirurgicale sans délai."},{"t":"Elle relève d'une simple surveillance rapprochée sans geste immédiat.","ok":false,"why":"Une IM aiguë mal tolérée est une urgence vitale nécessitant un geste rapide."},{"t":"Elle contre-indique tout geste chirurgical tant que le patient n'est pas stabilisé.","ok":false,"why":"C'est au contraire la chirurgie urgente qui permet de stabiliser le patient."},{"t":"Elle ne concerne que les IM secondaires à une cardiopathie dilatée.","ok":false,"why":"L'IM aiguë peut avoir de nombreuses causes (rupture de cordage, endocardite, infarctus), pas seulement une cardiopathie dilatée."}],"explanation":"Une IM aiguë mal tolérée est une urgence chirurgicale : le geste correctif ne doit pas être différé, quelle que soit la cause de la rupture de l'appareil valvulaire.","src":"p. 222"},{"id":"233-qcm-205","type":"QRM","rank":"B","objective":"233-obj-10","tags":["traitement","pièges"],"difficulty":3,"stem":"Chez un patient asymptomatique porteur d'une insuffisance mitrale primaire importante (grade III-IV), quels éléments justifient une indication chirurgicale ?","options":[{"t":"Un diamètre télésystolique du VG > 40 mm associé à une rupture de cordage.","ok":true,"why":"C'est l'un des critères de retentissement justifiant l'intervention chez l'asymptomatique."},{"t":"Une FEVG < 60 %.","ok":true,"why":"Ce seuil, abaissé car la FEVG est surestimée dans l'IM, signe déjà une dysfonction."},{"t":"Une pression artérielle pulmonaire systolique > 50 mmHg au repos.","ok":true,"why":"L'élévation des pressions droites au repos est un critère de retentissement reconnu."},{"t":"La seule dyspnée d'effort minime sans autre anomalie échographique suffit à elle seule à l'indication chez l'asymptomatique par définition.","ok":false,"why":"Un patient réellement asymptomatique n'a pas de dyspnée ; la présence de symptômes fait sortir du cadre de l'IM « asymptomatique »."},{"t":"Une fibrillation atriale associée, même paroxystique.","ok":true,"why":"La survenue d'une FA, même paroxystique, justifie l'intervention chez l'asymptomatique."}],"explanation":"Chez l'asymptomatique avec IM primaire importante, l'indication opératoire repose sur un DTS > 40 mm avec rupture de cordage, une FEVG < 60 %, une PAP systolique > 50 mmHg au repos ou une fibrillation atriale (même paroxystique) ; en l'absence de ces signes, surveillance tous les 6 mois.","src":"p. 222","trap":"Ne pas confondre « asymptomatique » avec l'apparition de la moindre dyspnée : dès qu'il y a des symptômes, on sort du cadre de la surveillance."},{"id":"233-qcm-206","type":"QRM","rank":"A","objective":"233-obj-04","tags":["diagnostic","paraclinique"],"difficulty":1,"stem":"Concernant les examens complémentaires de l'insuffisance mitrale, quelles propositions sont exactes ?","options":[{"t":"L'ECG et la radiographie thoracique n'ont pas de signe spécifique de l'IM.","ok":true,"why":"Leur intérêt est limité ; ils montrent tout au plus des signes de dilatation des cavités."},{"t":"L'échocardiographie doppler transthoracique est l'examen clé du diagnostic et de la sévérité.","ok":true,"why":"Elle confirme l'IM, précise son mécanisme, quantifie la sévérité et évalue le retentissement."},{"t":"Le cathétérisme reste l'examen de référence pour quantifier une IM.","ok":false,"why":"Son intérêt est aujourd'hui limité, l'échocardiographie fournissant les mêmes informations de façon non invasive."},{"t":"L'échocardiographie transœsophagienne peut être nécessaire pour apprécier la faisabilité d'une plastie.","ok":true,"why":"Elle est utile quand la voie transthoracique ne répond pas à toutes les questions, notamment pour planifier la chirurgie."},{"t":"La coronarographie préopératoire n'a d'intérêt que chez le sujet jeune sans facteur de risque.","ok":false,"why":"Elle est surtout indiquée en cas d'angor, de facteurs de risque coronarien, ou systématiquement chez le sujet âgé."}],"explanation":"L'ETT est l'examen clé de l'IM (diagnostic, mécanisme, sévérité) ; l'ETO aide à la faisabilité d'une plastie ; ECG et radio ont un intérêt limité ; le cathétérisme n'a plus qu'un rôle marginal, sauf la coronarographie préopératoire chez les patients à risque ou âgés.","src":"p. 222-223"},{"id":"233-qcm-207","type":"QRM","rank":"B","objective":"233-obj-08","tags":["traitement"],"difficulty":2,"stem":"Concernant le traitement chirurgical de l'insuffisance mitrale primaire, quelles propositions sont exactes ?","options":[{"t":"La réparation valvulaire est la technique de référence lorsqu'elle est réalisable.","ok":true,"why":"Elle est privilégiée, en particulier dans les IM par prolapsus."},{"t":"La plastie ne nécessite pas d'anticoagulation au long cours.","ok":true,"why":"Contrairement au remplacement par prothèse mécanique, la plastie ne requiert pas d'AVK à vie."},{"t":"La plastie expose à un risque de récidive de la fuite à long terme.","ok":true,"why":"Un léger risque de récidive existe malgré le bénéfice global de la technique."},{"t":"Le remplacement par bioprothèse est plutôt réservé au patient de plus de 70 ans.","ok":true,"why":"La bioprothèse évite l'anticoagulant mais dégénère, ce qui la réserve au patient âgé."},{"t":"Le remplacement par prothèse mécanique est indifféremment proposé à tout âge.","ok":false,"why":"La prothèse mécanique, du fait de l'anticoagulation à vie, est plutôt réservée au patient de moins de 65 ans."}],"explanation":"La plastie mitrale, technique de référence, évite l'anticoagulant mais expose à un léger risque de récidive ; le remplacement se fait par bioprothèse après 70 ans ou prothèse mécanique avant 65 ans.","src":"p. 223"},{"id":"233-qcm-208","type":"QRM","rank":"A","objective":"233-obj-01","tags":["définition","physiopathologie"],"difficulty":1,"stem":"Concernant l'insuffisance aortique (IA), quelles propositions sont exactes ?","options":[{"t":"Elle correspond à un reflux de sang de l'aorte vers le ventricule gauche en diastole.","ok":true,"why":"C'est la définition de la régurgitation aortique."},{"t":"C'est la valvulopathie la plus fréquente en population générale.","ok":false,"why":"C'est le rétrécissement aortique qui est la valvulopathie la plus fréquente ; l'IA est peu fréquente."},{"t":"Sa prévalence augmente avec l'âge.","ok":true,"why":"Le texte précise que la prévalence de l'IA croît avec l'âge de la population."},{"t":"Elle se produit pendant la systole ventriculaire.","ok":false,"why":"Le reflux se produit en diastole, quand la valve aortique devrait être fermée."},{"t":"Elle peut concerner la racine aortique autant que la valve elle-même.","ok":true,"why":"Les deux structures, racine et valve aortique, peuvent être en cause dans l'IA."}],"explanation":"L'IA est un reflux diastolique de l'aorte vers le VG ; valvulopathie peu fréquente (contrairement au RA), sa prévalence augmente avec l'âge, et elle peut résulter d'une atteinte de la racine aortique comme de la valve elle-même.","src":"p. 224-225"},{"id":"233-qcm-209","type":"QRM","rank":"A","objective":"233-obj-01","tags":["diagnostic","physiopathologie"],"difficulty":1,"stem":"Concernant l'anatomie de la racine et de la valve aortiques, quelles propositions sont exactes ?","options":[{"t":"La racine aortique comprend l'anneau, les sinus de Valsalva, la jonction sinotubulaire et l'aorte initiale.","ok":true,"why":"Ce sont les quatre composants successifs de la racine aortique."},{"t":"Les commissures des cusps s'insèrent au niveau de la jonction entre deux sinus.","ok":true,"why":"C'est à cette zone commissurale que s'ancrent les cusps voisines."},{"t":"La valve aortique normale comporte quatre cusps.","ok":false,"why":"Elle en comporte normalement trois (valve tricuspide) : antérodroite, antérogauche, non coronaire."},{"t":"La bicuspidie touche 1 à 2 % de la population générale.","ok":true,"why":"C'est la prévalence rapportée de cette anomalie congénitale."},{"t":"La bicuspidie résulte d'une fusion ou d'un défaut de séparation embryologique de deux cusps.","ok":true,"why":"C'est le mécanisme embryologique décrit à l'origine de la bicuspidie."}],"explanation":"La racine aortique associe anneau, sinus de Valsalva, jonction sinotubulaire et aorte initiale ; la valve aortique normale est tricuspide (3 cusps) ; la bicuspidie (1-2 % de la population) résulte d'une fusion embryologique de deux cusps.","src":"p. 225"},{"id":"233-qcm-210","type":"QRM","rank":"B","objective":"233-obj-05","tags":["physiopathologie"],"difficulty":3,"stem":"Concernant la physiopathologie de l'insuffisance aortique chronique, quelles propositions sont exactes ?","options":[{"t":"Elle impose une surcharge à la fois volumétrique et barométrique du VG.","ok":true,"why":"Le volume régurgité augmente la précharge, et l'augmentation du volume d'éjection augmente la postcharge."},{"t":"Le remodelage ventriculaire gauche qui en résulte est de type hypertrophie excentrique, plus marqué que dans l'IM.","ok":true,"why":"La dilatation et l'hypertrophie pariétale sont plus importantes que dans l'insuffisance mitrale."},{"t":"La grande compliance du VG permet de maintenir des pressions de remplissage normales pendant plusieurs années malgré la dilatation.","ok":true,"why":"C'est ce qui explique la longue tolérance clinique de l'IA chronique."},{"t":"La pression artérielle diastolique s'élève parallèlement à la pression systolique.","ok":false,"why":"Au contraire, la pression diastolique s'abaisse du fait de la régurgitation, élargissant la pression pulsée."},{"t":"La baisse de la pression artérielle diastolique peut compromettre la perfusion coronaire, qui se fait surtout en diastole.","ok":true,"why":"Ceci peut aller jusqu'à un phénomène de vol coronarien diastolique dans les formes sévères."}],"explanation":"L'IA chronique impose une surcharge mixte (volumétrique et barométrique) entraînant une hypertrophie excentrique plus marquée que dans l'IM ; la grande compliance VG maintient longtemps des pressions de remplissage normales, tandis que la baisse de la PA diastolique menace la perfusion coronaire.","src":"p. 226-227"},{"id":"233-qru-203","type":"QRU","rank":"B","objective":"233-obj-02","tags":["étiologie"],"difficulty":2,"stem":"Parmi les propositions suivantes, laquelle n'est **pas** une cause de dilatation de la racine aortique responsable d'insuffisance aortique de type 1 ?","options":[{"t":"La maladie de Marfan.","ok":false,"why":"C'est au contraire une cause génétique classique de dilatation annuloectasiante."},{"t":"La maladie de Takayasu.","ok":false,"why":"C'est une aortite inflammatoire pouvant dilater la racine aortique."},{"t":"Le rhumatisme articulaire aigu.","ok":true,"why":"Le RAA est une cause de restriction valvulaire (type 3), pas de dilatation de la racine aortique."},{"t":"La maladie de Horton.","ok":false,"why":"Cette artérite à cellules géantes figure parmi les aortites responsables d'IA par dilatation."},{"t":"La bicuspidie aortique.","ok":false,"why":"Elle peut s'associer à une dilatation de l'aorte initiale responsable d'IA de type 1."}],"explanation":"Les causes de dilatation de la racine aortique comprennent les maladies génétiques (Marfan, Loeys-Dietz, Ehlers-Danlos), les aortites (Takayasu, Horton, Behçet, spondylarthrite, syphilis), la bicuspidie et la dissection ; le RAA relève d'un autre mécanisme, la restriction valvulaire.","src":"p. 228-229"},{"id":"233-qcm-212","type":"QRM","rank":"A","objective":"233-obj-02","tags":["étiologie","pièges"],"difficulty":2,"stem":"Concernant les mécanismes de l'insuffisance aortique, quelles propositions sont exactes ?","options":[{"t":"Le prolapsus valvulaire correspond à une fermeture des cusps sous le plan de l'anneau, dans la chambre de chasse.","ok":true,"why":"C'est la définition du mouvement excessif ou prolapsus (type 2)."},{"t":"Dans la bicuspidie avec prolapsus, c'est en général la plus petite cusp qui prolabe.","ok":false,"why":"C'est au contraire la plus grande cusp, issue de la fusion de deux cusps, qui prolabe le plus souvent."},{"t":"La restriction valvulaire correspond à une fermeture des cusps au-dessus du plan de l'anneau, vers l'aorte.","ok":true,"why":"C'est la définition du mouvement restreint (type 3)."},{"t":"L'endocardite infectieuse peut causer une IA par destruction ou perforation d'une cusp à mouvement par ailleurs normal.","ok":true,"why":"La perforation ou destruction d'une cusp par l'EI relève du type 1."},{"t":"Le syndrome de Laubry-Pezzi associe une communication interventriculaire sous-aortique à un prolapsus valvulaire aortique.","ok":true,"why":"C'est la définition de ce syndrome cité parmi les causes rares de prolapsus."}],"explanation":"Le prolapsus (type 2) ferme les cusps sous le plan de l'anneau (la plus grande cusp dans la bicuspidie) ; la restriction (type 3) les ferme au-dessus, vers l'aorte ; l'EI peut causer une IA par perforation à mouvement normal (type 1) ; le Laubry-Pezzi associe CIV et prolapsus aortique.","src":"p. 229-230"},{"id":"233-qcm-213","type":"QRM","rank":"A","objective":"233-obj-02","tags":["étiologie"],"difficulty":2,"stem":"Concernant les étiologies restrictives (type 3) de l'insuffisance aortique, quelles propositions sont exactes ?","options":[{"t":"Le rhumatisme articulaire aigu prédomine en général sur la valve mitrale mais peut aussi atteindre la valve aortique.","ok":true,"why":"C'est précisé à propos du RAA, devenu rare en Occident mais encore présent chez les migrants."},{"t":"Les dérivés de l'ergot de seigle et certains anorexigènes retirés du marché peuvent léser la valve aortique.","ok":true,"why":"Le benfluorex, la fenfluramine et la dexfenfluramine sont cités parmi les toxiques valvulaires."},{"t":"La toxicité de ces médicaments est liée à leur action de type sérotoninergique.","ok":true,"why":"C'est le mécanisme rapporté pour ces substances valvulotoxiques."},{"t":"Le carcinoïde atteint fréquemment les valves gauches, quel que soit le contexte.","ok":false,"why":"L'atteinte des valves gauches est rare, sauf en cas de foramen ovale perméable ou de métastases pulmonaires."},{"t":"La radiothérapie médiastinale peut être en cause, notamment en cas de cancer du sein gauche.","ok":true,"why":"La radiothérapie pour lymphome ou cancer du sein, surtout gauche, est citée parmi les causes restrictives."}],"explanation":"Les causes restrictives d'IA comprennent le RAA (prédominant sur la mitrale), les toxiques sérotoninergiques (ergot de seigle, anorexigènes retirés, MDMA), le carcinoïde (rarement les valves gauches, sauf shunt ou métastase pulmonaire) et la radiothérapie médiastinale.","src":"p. 230-231"},{"id":"233-qru-204","type":"QRU","rank":"A","objective":"233-obj-02","tags":["étiologie","urgence"],"difficulty":2,"stem":"Concernant les IA sur prothèse valvulaire, quelle proposition est exacte ?","options":[{"t":"Une IA paraprothétique minime précoce après remplacement valvulaire est toujours synonyme de sepsis.","ok":false,"why":"Une fuite paraprothétique minime peut exister précocement hors tout contexte septique ; elle doit néanmoins être surveillée."},{"t":"Une IA minime est considérée comme normale sur une prothèse mécanique ou biologique.","ok":true,"why":"C'est précisé à propos des IA intraprothétiques : une fuite minime est physiologique sur prothèse."},{"t":"Toute IA sur prothèse impose une reprise chirurgicale immédiate.","ok":false,"why":"Seules les fuites significatives ou septiques imposent une reprise ; une fuite minime est surveillée."},{"t":"Une IA intraprothétique ne peut résulter que d'une dégénérescence de bioprothèse.","ok":false,"why":"Elle peut aussi résulter d'un thrombus bloquant une ailette ou d'une endocardite infectieuse."},{"t":"La désinsertion septique de prothèse ne survient jamais à distance de la chirurgie.","ok":false,"why":"Une endocardite prothétique tardive peut désinsérer la prothèse bien après l'intervention."}],"explanation":"Sur prothèse valvulaire, une IA intraprothétique minime est considérée comme normale, alors qu'une fuite paraprothétique peut être septique (endocardite précoce ou tardive) ou aseptique (fragilisation de l'anneau) et doit être surveillée.","src":"p. 232"},{"id":"233-qcm-215","type":"QRM","rank":"A","objective":"233-obj-03","tags":["clinique"],"difficulty":1,"stem":"Concernant les signes fonctionnels de l'insuffisance aortique, quelles propositions sont exactes ?","options":[{"t":"Elle est souvent asymptomatique.","ok":true,"why":"L'IA peut rester longtemps silencieuse cliniquement."},{"t":"La dyspnée d'effort est le symptôme le plus fréquemment retrouvé quand des signes existent.","ok":true,"why":"Elle est classée selon la NYHA et représente le symptôme principal."},{"t":"L'angor est un symptôme fréquent, présent chez la majorité des patients dès le début de la maladie.","ok":false,"why":"L'angor est rare, de type fonctionnel, et ne survient qu'en cas d'IA massive."},{"t":"Des signes au repos, quand ils existent, sont rares, tardifs et de mauvais pronostic.","ok":true,"why":"Leur apparition marque un stade avancé de la maladie."},{"t":"La découverte au stade d'insuffisance cardiaque est devenue fréquente de nos jours.","ok":false,"why":"Cette découverte tardive est au contraire devenue rare grâce au dépistage plus précoce."}],"explanation":"L'IA est souvent asymptomatique ; quand des symptômes existent, la dyspnée d'effort domine, l'angor fonctionnel est rare (IA massive) et les signes de repos, rares et tardifs, sont de mauvais pronostic.","src":"p. 232"},{"id":"233-qcm-216","type":"QRM","rank":"A","objective":"233-obj-03","tags":["clinique"],"difficulty":2,"stem":"Concernant l'auscultation de l'insuffisance aortique, quelles propositions sont exactes ?","options":[{"t":"Le souffle diastolique de l'IA prédomine au foyer aortique et irradie le long du bord gauche du sternum.","ok":true,"why":"C'est la description classique de ce souffle."},{"t":"Il est mieux perçu lorsque le patient est allongé sur le dos en inspiration profonde.","ok":false,"why":"Il est au contraire mieux perçu penché en avant, assis ou debout, en expiration bloquée."},{"t":"Il est holodiastolique dans les IA importantes et protomésodiastolique dans les IA de moindre importance.","ok":true,"why":"L'étendue du souffle dans la diastole reflète l'importance de la fuite."},{"t":"Un souffle systolique éjectionnel d'accompagnement peut se voir, lié à l'augmentation du débit antérograde.","ok":true,"why":"Ce souffle systolique d'hyperdébit est fréquent et ne doit pas être confondu avec un RA."},{"t":"Le roulement de Flint traduit une sténose mitrale organique associée.","ok":false,"why":"Il s'agit d'une sténose mitrale fonctionnelle liée à la gêne à l'ouverture mitrale par le jet d'IA, pas d'une atteinte organique."}],"explanation":"Le souffle diastolique de l'IA, maximal au foyer aortique et irradiant vers le bord gauche du sternum, est mieux perçu penché en avant en expiration bloquée ; holodiastolique si importante, il peut s'accompagner d'un souffle systolique d'hyperdébit et, dans les formes sévères, d'un roulement de Flint fonctionnel.","src":"p. 232-233","trap":"Le roulement de Flint est une sténose mitrale FONCTIONNELLE liée au jet d'IA, non une valvulopathie mitrale organique associée."},{"id":"233-qru-205","type":"QRU","rank":"A","objective":"233-obj-03","tags":["clinique"],"difficulty":2,"stem":"Concernant les signes périphériques de l'insuffisance aortique sévère, quelle proposition est exacte ?","options":[{"t":"La pression artérielle systolique est habituellement abaissée.","ok":false,"why":"C'est au contraire la pression systolique qui s'élève, du fait de l'augmentation du volume d'éjection."},{"t":"La pression artérielle diastolique est abaissée, élargissant la différentielle.","ok":true,"why":"Cet élargissement de la pression pulsée par baisse de la diastolique traduit la sévérité de la fuite."},{"t":"Les pouls périphériques sont habituellement diminués.","ok":false,"why":"Au contraire, on observe une hyperpulsatilité des pouls artériels périphériques."},{"t":"Le choc de pointe est habituellement normal, non dévié.","ok":false,"why":"Il est décrit comme étalé, dévié en bas et à gauche, « en dôme », en cas de dilatation du VG."},{"t":"Aucun signe périphérique n'est décrit dans l'IA.","ok":false,"why":"De nombreux signes périphériques d'hyperpulsatilité sont décrits : pouls, battements du cou, oscillation de la tête, pulsatilité sous-unguéale."}],"explanation":"L'IA sévère se traduit par un choc de pointe en dôme dévié en bas et à gauche, une hyperpulsatilité des pouls périphériques et un élargissement de la pression pulsée par élévation de la systolique et surtout baisse de la diastolique.","src":"p. 233"},{"id":"233-qcm-218","type":"QRM","rank":"B","objective":"233-obj-06","tags":["ECG","paraclinique"],"difficulty":2,"stem":"Concernant l'ECG et la radiographie thoracique dans l'insuffisance aortique, quelles propositions sont exactes ?","options":[{"t":"L'ECG peut être tout à fait normal.","ok":true,"why":"Un ECG normal n'exclut pas une IA, y compris significative."},{"t":"La survenue d'une fibrillation atriale ou d'extrasystoles ventriculaires est un élément de bon pronostic.","ok":false,"why":"C'est au contraire un élément de mauvais pronostic dans l'IA."},{"t":"On observe typiquement une HVG de type diastolique avec ondes R amples en précordiales gauches et ondes T positives.","ok":true,"why":"C'est l'aspect électrique classique de la surcharge diastolique de l'IA."},{"t":"Une HVG de type systolique avec sous-décalage de ST et ondes T inversées peut également se voir.","ok":true,"why":"C'est décrit comme un aspect possible, témoignant d'une atteinte plus évoluée."},{"t":"Les IA de petit volume s'accompagnent toujours d'anomalies radiologiques visibles.","ok":false,"why":"Les IA de petit volume n'ont en général pas de traduction radiologique."}],"explanation":"L'ECG de l'IA peut être normal ; il montre typiquement une HVG diastolique (R amples, T positives), parfois une HVG systolique (ST sous-décalé, T inversées) ; la survenue de FA ou d'ESV est de mauvais pronostic ; la radio ne montre d'anomalie que dans les IA volumineuses.","src":"p. 233-234"},{"id":"233-qcm-219","type":"QRM","rank":"A","objective":"233-obj-04","tags":["paraclinique","imagerie"],"difficulty":1,"stem":"Concernant l'échocardiographie doppler dans l'insuffisance aortique, quelles propositions sont exactes ?","options":[{"t":"Elle confirme le reflux diastolique de l'aorte vers le VG en doppler couleur.","ok":true,"why":"C'est le critère diagnostique positif de l'IA en échocardiographie."},{"t":"Elle permet d'exclure une insuffisance pulmonaire comme cause du souffle diastolique.","ok":true,"why":"L'échocardiographie fait la distinction avec l'insuffisance pulmonaire, autre cause de souffle diastolique."},{"t":"La sévérité de l'IA est quantifiée en deux grades seulement, minime ou sévère.","ok":false,"why":"Elle est quantifiée en quatre grades (1 à 4), même si certaines recommandations américaines n'en distinguent que trois."},{"t":"Seuls les grades 3 et 4 entraînent une surcharge volumétrique significative du VG.","ok":true,"why":"C'est précisé à propos de la pertinence physiopathologique de la classification en quatre grades."},{"t":"Un grade 4 (fuite sévère) correspond à une surface de l'orifice régurgitant ≥ 30 mm² et un volume régurgité ≥ 60 mL.","ok":true,"why":"Ce sont les seuils du tableau de quantification de l'IA."}],"explanation":"L'échocardiographie confirme le reflux diastolique aorte-VG, exclut l'insuffisance pulmonaire, et quantifie l'IA en 4 grades (seuls les grades 3-4 sont hémodynamiquement significatifs) ; le grade 4 correspond à une SOR ≥ 30 mm² et un volume régurgité ≥ 60 mL.","src":"p. 234"},{"id":"233-qroc-201","type":"QROC","rank":"B","objective":"233-obj-08","tags":["traitement"],"difficulty":1,"question":"Avant quel âge préfère-t-on classiquement une prothèse mitrale mécanique, et après quel âge une bioprothèse ?","answer":"Mécanique avant 65 ans, bioprothèse après 70 ans","accept":["avant 65 ans mécanique après 70 ans bio","65-70 ans"],"keywords":["65","70","mécanique","bioprothèse"],"explanation":"Le choix dépend surtout de l'âge : la prothèse mécanique (durable, anticoagulant à vie) est plutôt proposée avant 65 ans, la bioprothèse (pas d'anticoagulant, dégénérescence) après 70 ans, la zone intermédiaire se discutant au cas par cas.","src":"p. 221"},{"id":"233-qroc-202","type":"QROC","rank":"B","objective":"233-obj-09","tags":["traitement"],"difficulty":1,"question":"Dans quelles circonstances le traitement percutané de l'IM par clip bord à bord peut-il être discuté ?","answer":"Uniquement en cas de haut risque chirurgical ou de contre-indication à la chirurgie","accept":["haut risque ou contre-indication chirurgicale"],"keywords":["haut risque","contre-indication","chirurgie"],"explanation":"Le clip mitral n'est envisagé qu'en cas de haut risque opératoire ou de contre-indication formelle à la chirurgie, après discussion en clinique des valves.","src":"p. 221"},{"id":"233-qroc-203","type":"QROC","rank":"A","objective":"233-obj-10","tags":["traitement","urgence"],"difficulty":2,"question":"Quel est le seuil de fraction d'éjection en dessous duquel le remplacement valvulaire mitral devient contre-indiqué dans l'IM primaire non réparable ?","answer":"FE < 30 %","accept":["FE inférieure à 30%","30 pourcent"],"keywords":["30","FE","contre-indiqué"],"explanation":"En dessous de 30 % de FE, le remplacement valvulaire est contre-indiqué car la FE chute encore de 10 à 15 % après l'intervention, exposant à une dysfonction VG sévère ; on privilégie alors le traitement médical, la plastie si possible, ou la transplantation chez le sujet jeune.","src":"p. 222"},{"id":"233-qroc-204","type":"QROC","rank":"B","objective":"233-obj-10","tags":["traitement","suivi"],"difficulty":2,"question":"Chez un patient asymptomatique avec IM primaire importante ne remplissant aucun critère opératoire, à quel rythme propose-t-on la surveillance clinique et échographique ?","answer":"Tous les 6 mois","accept":["semestrielle","6 mois"],"keywords":["6 mois","surveillance"],"explanation":"En l'absence de retentissement, de symptômes ou de FA, une surveillance clinique et échographique semestrielle est proposée, avec indication chirurgicale dès l'apparition d'un de ces éléments.","src":"p. 222"},{"id":"233-qroc-205","type":"QROC","rank":"A","objective":"233-obj-01","tags":["définition"],"difficulty":1,"question":"Quelle est la définition de l'insuffisance aortique ?","answer":"Reflux de sang de l'aorte vers le ventricule gauche en diastole","accept":["régurgitation aortique","fuite aortique"],"keywords":["reflux","aorte","VG","diastole"],"explanation":"L'IA est un reflux (régurgitation) de sang de l'aorte vers le ventricule gauche en diastole, du fait d'un défaut d'étanchéité de la valve ou de la racine aortique.","src":"p. 224"},{"id":"233-qroc-206","type":"QROC","rank":"A","objective":"233-obj-01","tags":["diagnostic"],"difficulty":1,"question":"Quelle est la prévalence de la bicuspidie aortique dans la population générale ?","answer":"1 à 2 %","accept":["1-2%","1 à 2 pourcent"],"keywords":["1","2","pourcent"],"explanation":"La bicuspidie aortique, anomalie congénitale par fusion embryologique de deux cusps, touche 1 à 2 % de la population générale.","src":"p. 225"},{"id":"233-qroc-207","type":"QROC","rank":"B","objective":"233-obj-05","tags":["physiopathologie"],"difficulty":2,"question":"Quel type d'hypertrophie ventriculaire gauche caractérise l'adaptation du VG à l'insuffisance aortique chronique ?","answer":"Hypertrophie excentrique","accept":["remodelage excentrique"],"keywords":["hypertrophie","excentrique"],"explanation":"La surcharge mixte, volumétrique et barométrique, de l'IA induit une hypertrophie excentrique du VG (dilatation associée à un épaississement pariétal), plus marquée que dans l'insuffisance mitrale.","src":"p. 227"},{"id":"233-qroc-208","type":"QROC","rank":"B","objective":"233-obj-05","tags":["physiopathologie"],"difficulty":2,"question":"Pourquoi la circulation coronarienne peut-elle souffrir dans une insuffisance aortique sévère ?","answer":"La perfusion coronaire, essentiellement diastolique, est compromise par la baisse de la pression artérielle diastolique","accept":["vol coronarien diastolique","baisse PA diastolique"],"keywords":["coronaire","diastolique","perfusion"],"explanation":"La perfusion coronarienne se fait surtout en diastole ; la baisse de la pression diastolique aortique dans l'IA sévère peut créer un véritable « vol » coronarien et entraîner un angor fonctionnel.","src":"p. 227"},{"id":"233-qroc-209","type":"QROC","rank":"A","objective":"233-obj-02","tags":["étiologie"],"difficulty":2,"question":"Citez deux médicaments retirés du marché reconnus comme causes toxiques d'insuffisance aortique restrictive.","answer":"Fenfluramine et benfluorex (ou dexfenfluramine)","accept":["fenfluramine benfluorex dexfenfluramine"],"keywords":["fenfluramine","benfluorex"],"explanation":"Les anorexigènes retirés du marché (fenfluramine, dexfenfluramine, benfluorex) ainsi que les dérivés de l'ergot de seigle et les amphétaminiques (MDMA) sont des causes toxiques, par mécanisme sérotoninergique, d'IA restrictive.","src":"p. 231"},{"id":"233-qroc-210","type":"QROC","rank":"A","objective":"233-obj-03","tags":["clinique"],"difficulty":1,"question":"Dans quelle position le souffle diastolique de l'insuffisance aortique est-il le mieux perçu ?","answer":"Patient penché en avant, assis ou debout, en expiration bloquée","accept":["penché en avant en expiration"],"keywords":["penché en avant","expiration"],"explanation":"Le souffle diastolique de l'IA est mieux entendu chez un patient penché en avant, assis ou debout, en expiration bloquée, ce qui rapproche le cœur de la paroi thoracique.","src":"p. 232-233"},{"id":"233-qroc-211","type":"QROC","rank":"B","objective":"233-obj-03","tags":["clinique"],"difficulty":2,"question":"Comment appelle-t-on le roulement diastolique apexien pouvant s'entendre dans une insuffisance aortique sévère, et quel en est le mécanisme ?","answer":"Roulement de Flint, par sténose mitrale fonctionnelle","accept":["souffle de Flint"],"keywords":["Flint","sténose mitrale fonctionnelle"],"explanation":"Le roulement de Flint est un souffle diastolique apexien lié à une sténose mitrale fonctionnelle : le jet régurgitant aortique gêne l'ouverture normale de la valve mitrale.","src":"p. 233"},{"id":"233-qroc-212","type":"QROC","rank":"A","objective":"233-obj-04","tags":["paraclinique"],"difficulty":1,"question":"En combien de grades l'échocardiographie classe-t-elle la sévérité de l'insuffisance aortique ?","answer":"4 grades","accept":["quatre grades"],"keywords":["4","grades"],"explanation":"L'IA, comme l'IM, est classée en quatre grades échocardiographiques (1 à 4, de minime à sévère), en combinant plusieurs méthodes de quantification.","src":"p. 234"},{"id":"233-open-21","type":"OPEN","rank":"B","objective":"233-obj-10","tags":["traitement","suivi"],"difficulty":2,"prompt":"Résumez la stratégie thérapeutique de l'insuffisance mitrale primaire selon son grade et le statut symptomatique du patient.","rubric":[{"point":"Grade I-II : pas d'intervention, simple surveillance","weight":2},{"point":"Grade III-IV symptomatique : chirurgie, plastie privilégiée, remplacement possible seulement si FE > 30 %","weight":3},{"point":"Grade III-IV asymptomatique : chirurgie si retentissement (DTS, FEVG, PAP) ou FA, sinon surveillance semestrielle","weight":3},{"point":"IM secondaire : traiter d'abord l'insuffisance cardiaque, geste discuté en cas d'échec","weight":2}],"model":"Une IM isolée de grade I-II ne justifie pas d'intervention. À partir du grade III-IV, la stratégie dépend des symptômes : chez le patient symptomatique, la chirurgie est indiquée, avec une nette préférence pour la plastie reconstructrice, y compris en cas de dysfonction VG ; si elle n'est pas réalisable, le remplacement n'est proposé que si la FE dépasse 30 %, sous peine de dysfonction VG postopératoire sévère. Chez l'asymptomatique, on opère dès qu'apparaît un signe de retentissement (DTS > 40 mm avec rupture de cordage, FEVG < 60 %, PAP systolique > 50 mmHg) ou une fibrillation atriale ; sinon, une surveillance clinique et échographique tous les 6 mois est proposée. Pour l'IM secondaire, le traitement de l'insuffisance cardiaque (médicaments, resynchronisation) prime, la chirurgie ou le clip n'étant discutés qu'en cas d'échec.","src":"p. 222-223"},{"id":"233-open-22","type":"OPEN","rank":"A","objective":"233-obj-01","tags":["définition","diagnostic"],"difficulty":1,"prompt":"Un homme de 51 ans, sans antécédent notable, consulte pour une dyspnée d'effort progressive. L'auscultation retrouve un souffle diastolique au bord gauche du sternum et sa PA est à 152/58 mmHg. Expliquez ce que ces éléments cliniques évoquent et pourquoi.","rubric":[{"point":"Identifier un souffle diastolique du bord gauche du sternum comme évocateur d'IA","weight":2},{"point":"Relier la pression pulsée élargie (152/58) à une hyperpulsatilité artérielle de l'IA sévère","weight":3},{"point":"Mentionner la nécessité d'une échocardiographie pour confirmer et quantifier","weight":2},{"point":"Évoquer une recherche étiologique (bicuspidie, dilatation aortique, endocardite...) une fois le diagnostic posé","weight":1}],"model":"Le souffle diastolique perçu au bord gauche du sternum est très évocateur d'une insuffisance aortique. La pression artérielle à 152/58 mmHg montre une pression pulsée très élargie, avec une pression diastolique basse : ce signe d'hyperpulsatilité artérielle oriente vers une fuite aortique significative plutôt que minime. La dyspnée d'effort progressive traduit un possible retentissement sur le VG. L'échocardiographie doppler est l'examen clé pour confirmer le diagnostic, quantifier la fuite (grade), apprécier le retentissement ventriculaire gauche et rechercher une étiologie (bicuspidie, dilatation de la racine aortique, séquelle d'endocardite).","src":"p. 224, 233"},{"id":"233-open-23","type":"OPEN","rank":"A","objective":"233-obj-02","tags":["étiologie","suivi"],"difficulty":2,"prompt":"Classez les principales étiologies de l'insuffisance aortique selon les trois mécanismes décrits par le mouvement des cusps, en citant au moins deux causes par mécanisme.","rubric":[{"point":"Mouvement normal (type 1) : dilatation de la racine (idiopathique, Marfan, aortites) ou perforation (endocardite)","weight":3},{"point":"Mouvement excessif / prolapsus (type 2) : dystrophie/dysplasie isolée, bicuspidie","weight":2},{"point":"Mouvement restreint (type 3) : rhumatisme articulaire aigu, toxiques médicamenteux","weight":2},{"point":"Préciser que ces mécanismes peuvent s'associer chez un même patient","weight":1}],"model":"Trois mécanismes expliquent l'IA selon la mobilité des cusps. Un mouvement normal (type 1) se voit en cas de dilatation de la racine aortique, qu'elle soit idiopathique, génétique (Marfan, Loeys-Dietz, Ehlers-Danlos), inflammatoire (Takayasu, Horton, Behçet) ou liée à une bicuspidie ou une dissection, ainsi qu'en cas de destruction ou perforation d'une cusp par une endocardite. Un mouvement excessif ou prolapsus (type 2) s'observe dans les dystrophies ou dysplasies valvulaires isolées et dans la bicuspidie, où la cusp fusionnée, plus grande, prolabe. Un mouvement restreint (type 3) correspond au rhumatisme articulaire aigu et aux atteintes toxiques médicamenteuses (ergot de seigle, anorexigènes, MDMA) ou radiques. Ces mécanismes peuvent parfois coexister chez un même patient.","src":"p. 228-231"},{"id":"233-open-24","type":"OPEN","rank":"B","objective":"233-obj-05","tags":["physiopathologie","suivi"],"difficulty":3,"prompt":"Comparez la tolérance hémodynamique d'une insuffisance aortique aiguë à celle d'une insuffisance aortique chronique, en expliquant le mécanisme de la différence.","rubric":[{"point":"IA chronique : VG dilaté et compliant, adaptation progressive, longtemps asymptomatique","weight":3},{"point":"IA aiguë : VG non dilaté, compliance normale non adaptée, élévation brutale des pressions de remplissage","weight":3},{"point":"Conséquence clinique : œdème pulmonaire brutal dans l'IA aiguë, contre une tolérance prolongée dans la forme chronique","weight":2},{"point":"Citer l'endocardite infectieuse comme cause typique de l'IA aiguë","weight":1}],"model":"Dans l'IA chronique, le VG se remodèle progressivement (hypertrophie excentrique) et acquiert une grande compliance, ce qui lui permet de tolérer un volume régurgité important avec des pressions de remplissage longtemps normales : la maladie reste asymptomatique pendant des années. À l'inverse, l'IA aiguë, le plus souvent due à une endocardite infectieuse, survient sur un VG de taille normale, à compliance non adaptée : le volume régurgité brutal élève immédiatement les pressions de remplissage, se transmettant à l'atrium gauche puis à la circulation pulmonaire, ce qui provoque un œdème aigu du poumon rapide. Le souffle de l'IA aiguë peut être discret, ce qui rend le diagnostic clinique parfois difficile malgré la gravité du tableau.","src":"p. 226-227"},{"id":"233-qcm-301","type":"QRM","rank":"A","objective":"233-obj-04","tags":["paraclinique","imagerie"],"difficulty":2,"stem":"Concernant les critères de quantification échocardiographique d'une insuffisance aortique sévère, quelles propositions sont exactes ?","options":[{"t":"Un hyperdébit dans la chambre de chasse du VG supérieur à 4 L/min/m² est en faveur d'une fuite sévère.","ok":true,"why":"C'est le seuil indirect classique d'une fuite volumétriquement significative."},{"t":"Une vitesse de flux rétrograde télédiastolique dans l'isthme aortique supérieure à 20 cm/s est en faveur d'une IA sévère.","ok":true,"why":"Ce critère indirect, mesuré en doppler, est cité comme argument de sévérité chez l'adulte."},{"t":"La vena contracta est un critère de quantification indirect.","ok":false,"why":"C'est au contraire un critère direct, mesuré au niveau du jet régurgitant à son origine."},{"t":"La méthode PISA permet d'estimer la surface de l'orifice régurgitant et le volume régurgité.","ok":true,"why":"La zone de convergence proximale (PISA) est une méthode de quantification directe utilisable dans l'IA comme dans l'IM."},{"t":"La dilatation du VG en diastole ne renseigne pas sur la sévérité de la fuite.","ok":false,"why":"Une dilatation diastolique du VG signe au contraire une surcharge volumétrique significative, de grade ≥ 3."}],"explanation":"La sévérité de l'IA se quantifie par des critères indirects (hyperdébit > 4 L/min/m², dilatation diastolique du VG, flux rétrograde isthmique > 20 cm/s) et directs (vena contracta, PISA permettant de calculer SOR et volume régurgité).","src":"p. 234-235"},{"id":"233-qcm-302","type":"QRM","rank":"A","objective":"233-obj-04","tags":["paraclinique","imagerie"],"difficulty":2,"stem":"Concernant l'évaluation échocardiographique du retentissement de l'insuffisance aortique, quelles propositions sont exactes ?","options":[{"t":"Les diamètres télédiastolique et télésystolique du VG doivent être indexés à la surface corporelle.","ok":true,"why":"L'indexation permet de comparer les mesures entre patients de morphologies différentes."},{"t":"La FEVG est le plus souvent normale (> 50 %) dans les IA compensées.","ok":true,"why":"Tant que le VG compense la surcharge, la FEVG reste normale."},{"t":"L'hypertrophie associée à la dilatation du VG dans l'IA est de type concentrique.","ok":false,"why":"Il s'agit d'une hypertrophie excentrique, associant dilatation cavitaire et épaississement pariétal."},{"t":"Les indications de remplacement valvulaire chez l'asymptomatique reposent notamment sur ces données de retentissement.","ok":true,"why":"Diamètres, volumes et FEVG constituent la base des indications opératoires chez l'asymptomatique."},{"t":"L'estimation de la pression artérielle pulmonaire ne fait pas partie du bilan échographique du retentissement.","ok":false,"why":"La mesure de la PAP fait partie du bilan de retentissement, au même titre que les diamètres et la FEVG."}],"explanation":"Le retentissement de l'IA est évalué par les diamètres VG indexés, les volumes, l'aspect d'hypertrophie excentrique, la FEVG (normale > 50 % si compensée) et la PAP, données qui fondent les indications chez l'asymptomatique.","src":"p. 235"},{"id":"233-qcm-303","type":"QRM","rank":"B","objective":"233-obj-04","tags":["paraclinique","étiologie"],"difficulty":2,"stem":"Concernant l'évaluation échocardiographique étiologique de l'insuffisance aortique, quelles propositions sont exactes ?","options":[{"t":"L'aspect « piriforme » ou « en bulbe d'oignon » de la racine aortique évoque une maladie annuloectasiante.","ok":true,"why":"Cet aspect caractéristique oriente vers une dilatation prédominant sur l'anneau et les sinus."},{"t":"En cas de bicuspidie, l'aorte ascendante est dilatée dans environ la moitié des cas.","ok":true,"why":"Cette association est fréquente et se situe le plus souvent au-delà de la jonction sinotubulaire."},{"t":"La présence de végétations ou d'abcès valvulaires oriente vers une origine dégénérative.","ok":false,"why":"Ces images évoquent au contraire une endocardite infectieuse, non une cause dégénérative."},{"t":"L'échocardiographie apprécie aussi les autres valves, notamment mitrale ou tricuspide.","ok":true,"why":"L'examen d'une valvulopathie recherche systématiquement des atteintes valvulaires associées."},{"t":"La présence d'un « flap » évoque une dissection aortique.","ok":true,"why":"C'est l'image caractéristique du volet intimal séparant les deux chenaux d'une dissection."}],"explanation":"L'échocardiographie étiologique recherche l'aspect des valves (bi/tricuspide), la mobilité des cusps, des végétations ou abcès (endocardite), un aspect « en bulbe d'oignon » (maladie annuloectasiante) ou un flap (dissection), ainsi que les autres valves.","src":"p. 235-236"},{"id":"233-qru-302","type":"QRU","rank":"B","objective":"233-obj-06","tags":["paraclinique","diagnostic"],"difficulty":2,"stem":"Concernant les critères de mauvaise tolérance à l'épreuve d'effort dans l'insuffisance aortique, quelle proposition est exacte ?","options":[{"t":"L'arrêt de l'effort par épuisement musculaire plutôt que par dyspnée signe une mauvaise tolérance cardiaque.","ok":false,"why":"C'est au contraire l'arrêt pour dyspnée, et non l'épuisement musculaire, qui est le critère de mauvaise tolérance."},{"t":"Une capacité d'effort inférieure à 80-85 % de la valeur théorique est un critère de mauvaise tolérance.","ok":true,"why":"C'est l'un des critères cités de mauvaise tolérance à l'effort dans l'IA."},{"t":"Un plafonnement du pouls d'oxygène en fin d'effort est un signe rassurant.","ok":false,"why":"C'est au contraire un critère de mauvaise tolérance, traduisant une réserve contractile insuffisante."},{"t":"La survenue de troubles du rythme ventriculaire à l'effort est un critère rassurant.","ok":false,"why":"C'est au contraire un critère de mauvaise tolérance à l'effort."},{"t":"Une fréquence cardiaque maximale atteinte précocement est le seul critère retenu.","ok":false,"why":"Ce n'est pas le critère principal ; la capacité d'effort, la dyspnée et les troubles du rythme priment."}],"explanation":"Les critères de mauvaise tolérance à l'effort dans l'IA sont l'arrêt pour dyspnée (et non épuisement musculaire), une capacité < 80-85 % de la théorique, un plafonnement du pouls d'O2, un défaut de réserve contractile et des troubles du rythme ventriculaire.","src":"p. 236"},{"id":"233-qru-304","type":"QRU","rank":"B","objective":"233-obj-06","tags":["paraclinique"],"difficulty":1,"stem":"Concernant l'imagerie en coupes (scanner, IRM) dans l'insuffisance aortique, quelle proposition est exacte ?","options":[{"t":"Le scanner a l'avantage d'être largement disponible mais l'inconvénient d'être irradiant.","ok":true,"why":"C'est le compromis classique du scanner par rapport à l'IRM, non irradiante mais moins disponible."},{"t":"L'IRM est plus disponible que le scanner en pratique courante.","ok":false,"why":"C'est l'inverse : l'IRM est moins disponible que le scanner, bien que non irradiante."},{"t":"L'IRM peut être utilisée sans restriction chez l'insuffisant rénal sévère.","ok":false,"why":"Elle nécessite l'injection de gadolinium, contre-indiquée en cas d'insuffisance rénale sévère."},{"t":"L'angiographie sus-sigmoïdienne est désormais l'examen de première intention pour quantifier la fuite.","ok":false,"why":"Elle est au contraire devenue exceptionnelle, réservée aux difficultés de quantification échographique."},{"t":"Le scanner est irradiant mais indisponible en pratique courante.","ok":false,"why":"Le scanner est au contraire largement disponible ; c'est son irradiation qui en limite la répétition."}],"explanation":"Le scanner, disponible mais irradiant, et l'IRM, non irradiante mais limitée par le gadolinium chez l'insuffisant rénal sévère, servent surtout à préciser les dimensions de l'aorte ascendante dans le suivi de l'IA.","src":"p. 236-237"},{"id":"233-qru-301","type":"QRU","rank":"A","objective":"233-obj-04","tags":["diagnostic","pièges"],"difficulty":1,"stem":"Concernant le diagnostic différentiel d'un souffle diastolique, quelle proposition est exacte ?","options":[{"t":"Le principal diagnostic différentiel de l'IA est l'insuffisance pulmonaire.","ok":true,"why":"C'est la principale cause à distinguer, dans un contexte en général différent de cardiopathie congénitale connue."},{"t":"Un souffle continu évoque toujours une insuffisance aortique typique.","ok":false,"why":"Un souffle continu oriente plutôt vers un canal artériel persistant ou une fistule coronarienne."},{"t":"Un frottement péricardique ne peut jamais être confondu avec un souffle d'IA.","ok":false,"why":"Le frottement péricardique fait partie des diagnostics différentiels cités devant un souffle diastolique."},{"t":"La radiographie thoracique permet de trancher entre ces diagnostics différentiels.","ok":false,"why":"C'est l'échocardiographie qui permet habituellement d'établir le bon diagnostic, pas la radiographie."},{"t":"Un double souffle évoque une insuffisance mitrale isolée.","ok":false,"why":"Un double souffle évoque plutôt la rupture d'un sinus aortique, pas une IM isolée."}],"explanation":"Devant un souffle diastolique, le principal diagnostic différentiel de l'IA est l'insuffisance pulmonaire ; un souffle continu évoque un canal artériel ou une fistule coronarienne, un double souffle une rupture de sinus aortique, et l'échocardiographie tranche habituellement.","src":"p. 237"},{"id":"233-qcm-306","type":"QRM","rank":"A","objective":"233-obj-07","tags":["complications","suivi"],"difficulty":2,"stem":"Concernant l'évolution de l'insuffisance aortique chronique significative (grades 3-4), quelles propositions sont exactes ?","options":[{"t":"Elle peut rester longtemps asymptomatique.","ok":true,"why":"L'IA chronique significative peut être bien tolérée pendant de nombreuses années."},{"t":"L'apparition de symptômes marque un tournant évolutif avec altération du pronostic.","ok":true,"why":"Les symptômes signent un changement de phase défavorable dans l'histoire naturelle."},{"t":"Les lésions myocardiques associées au remodelage sont toujours totalement réversibles après chirurgie.","ok":false,"why":"Elles peuvent au contraire être irréversibles, ce qui justifie une indication opératoire précoce chez l'asymptomatique."},{"t":"Elle impose une surveillance étroite des patients ayant une IA de grade 3-4.","ok":true,"why":"Le caractère potentiellement irréversible du remodelage impose ce suivi rapproché."},{"t":"Le risque de dissection ou de rupture aortique ne concerne que les IA sur valve normale.","ok":false,"why":"Ce risque concerne surtout les IA sur dilatation de la racine aortique, quelle que soit la valve."}],"explanation":"L'IA significative (grade 3-4) peut rester longtemps asymptomatique, mais l'apparition de symptômes est un tournant de mauvais pronostic ; le remodelage myocardique pouvant être irréversible, une surveillance étroite est nécessaire, notamment du fait du risque de dissection aortique.","src":"p. 238"},{"id":"233-qcm-307","type":"QRM","rank":"A","objective":"233-obj-07","tags":["complications","pièges"],"difficulty":2,"stem":"Concernant le risque aortique de l'insuffisance aortique par dilatation de la racine, quelles propositions sont exactes ?","options":[{"t":"Le diamètre aortique doit être surveillé annuellement par échographie.","ok":true,"why":"Une surveillance annuelle du diamètre aortique est recommandée en cas de dilatation."},{"t":"Dans la bicuspidie, le risque de dissection est un peu augmenté par rapport à la population générale mais reste faible comparé au Marfan.","ok":true,"why":"C'est la nuance donnée entre les deux situations à risque aortique."},{"t":"Le dépistage familial n'est nécessaire qu'en cas de bicuspidie, jamais dans le syndrome de Marfan.","ok":false,"why":"C'est l'inverse : le dépistage des apparentés du 1er degré est nécessaire dans le Marfan, et seulement proposé dans la bicuspidie."},{"t":"Le risque de récurrence familiale de la bicuspidie est estimé à environ 10 %.","ok":true,"why":"Ce chiffre justifie de proposer un dépistage familial en cas de bicuspidie."},{"t":"Un scanner ou une IRM peuvent compléter l'échographie de temps à autre pour surveiller l'aorte.","ok":true,"why":"Ces examens en coupes s'ajoutent à l'échographie en cas de dilatation notable."}],"explanation":"La surveillance annuelle du diamètre aortique (écho, complétée de temps à autre par IRM ou scanner) est essentielle ; le risque de dissection est un peu augmenté dans la bicuspidie (récurrence familiale 10 %) mais reste modéré comparé au Marfan, où le dépistage familial est indispensable.","src":"p. 238"},{"id":"233-qru-303","type":"QRU","rank":"B","objective":"233-obj-07","tags":["complications"],"difficulty":1,"stem":"Concernant la mort subite au cours de l'insuffisance aortique chronique, quelle proposition est exacte ?","options":[{"t":"C'est une complication fréquente et précoce, dès le début de la maladie.","ok":false,"why":"C'est au contraire une complication rare, survenant surtout dans les formes évoluées."},{"t":"Elle peut résulter d'un trouble du rythme dans les formes évoluées ou d'une rupture aortique associée.","ok":true,"why":"Ce sont les deux mécanismes cités pour cette complication rare mais grave."},{"t":"Elle ne concerne que les IA aiguës, jamais les formes chroniques.","ok":false,"why":"Elle est décrite, bien que rare, aussi dans l'évolution des formes chroniques évoluées."},{"t":"Elle est systématiquement prévenue par le seul traitement médical.","ok":false,"why":"Aucun traitement médicamenteux n'a démontré de bénéfice sur l'IA ; seule la chirurgie à temps prévient ce risque."},{"t":"Elle est plus fréquente que l'insuffisance cardiaque parmi les complications de l'IA.","ok":false,"why":"L'insuffisance cardiaque tardive est une complication plus fréquente que la mort subite, qui reste rare."}],"explanation":"La mort subite est une complication rare de l'IA chronique, survenant surtout dans les formes évoluées par trouble du rythme ou par rupture aortique associée, moins fréquente que l'insuffisance cardiaque tardive.","src":"p. 238"},{"id":"233-qcm-309","type":"QRM","rank":"B","objective":"233-obj-07","tags":["suivi"],"difficulty":2,"stem":"Concernant la surveillance de l'insuffisance aortique chronique, quelles propositions sont exactes ?","options":[{"t":"Le rythme de suivi est de 1 à 2 fois par an en cas de fuite sévère.","ok":true,"why":"C'est le rythme recommandé pour les fuites sévères."},{"t":"En cas de fuite modérée à moyenne, le suivi est proposé tous les 2 à 3 ans.","ok":true,"why":"Ce rythme espacé convient aux fuites de moindre importance."},{"t":"Le test d'effort ou l'échographie d'effort, quand ils sont réalisés, peuvent l'être jusqu'à 1 fois par an dans les formes sévères.","ok":true,"why":"C'est la fréquence maximale proposée pour ce type d'examen dans le suivi."},{"t":"La surveillance dentaire n'est recommandée qu'une fois par an.","ok":false,"why":"Une surveillance dentaire biannuelle (2 fois par an) est recommandée."},{"t":"Une IRM ou un scanner peuvent être proposés en cas de dilatation aortique importante ou progressive.","ok":true,"why":"Ces examens en coupes complètent l'échographie dans cette situation."}],"explanation":"Le suivi de l'IA chronique associe examen clinique, ECG et ETT à un rythme de 1-2 fois/an (sévère) ou 2-3 ans (modérée), un test d'effort au maximum annuel si sévère, une surveillance dentaire biannuelle, et une imagerie en coupes si l'aorte se dilate.","src":"p. 238-239"},{"id":"233-qcm-310","type":"QRM","rank":"B","objective":"233-obj-12","tags":["traitement","pièges"],"difficulty":2,"stem":"Concernant le traitement médical de l'insuffisance aortique, quelles propositions sont exactes ?","options":[{"t":"Aucun traitement médicamenteux n'a démontré de bénéfice spécifique dans l'IA.","ok":true,"why":"C'est le message central du traitement médical de l'IA."},{"t":"Les IEC sont recommandés pour prévenir le remodelage cardiaque dans l'IA modérée à sévère.","ok":false,"why":"Ils ne sont au contraire pas recommandés dans cette indication faute de bénéfice démontré."},{"t":"Les bêtabloquants sont classiquement contre-indiqués dans l'IA décompensée car ils allongent la diastole et aggravent la fuite.","ok":true,"why":"C'est le mécanisme expliquant cette contre-indication relative."},{"t":"Dans le syndrome de Marfan, les bêtabloquants sont le traitement validé pour protéger l'aorte.","ok":true,"why":"C'est une exception notable à la contre-indication habituelle, spécifique à la protection aortique."},{"t":"Les ARA2 sont proposés en 1re intention avant les bêtabloquants dans le Marfan.","ok":false,"why":"Les ARA2 ne sont utilisés qu'en cas d'intolérance aux bêtabloquants, qui restent le traitement de référence."}],"explanation":"Aucun médicament n'est efficace sur l'IA elle-même (IEC non recommandés) ; les bêtabloquants, contre-indiqués dans l'IA décompensée car ils aggravent la fuite, sont au contraire le traitement validé pour protéger l'aorte dans le Marfan, les ARA2 n'étant utilisés qu'en cas d'intolérance.","src":"p. 239-240","trap":"Ne pas généraliser la contre-indication des bêtabloquants à toutes les IA : ils sont au contraire recommandés dans le Marfan pour protéger l'aorte."},{"id":"233-qcm-311","type":"QRM","rank":"B","objective":"233-obj-08","tags":["traitement"],"difficulty":2,"stem":"Concernant les modalités du traitement chirurgical de l'insuffisance aortique, quelles propositions sont exactes ?","options":[{"t":"L'IA isolée est traitée par un remplacement valvulaire aortique simple.","ok":true,"why":"C'est le traitement de référence en l'absence de dilatation aortique associée."},{"t":"En cas de dilatation aortique associée, l'intervention de Bentall associe remplacement valvulaire et remplacement de l'aorte ascendante avec réimplantation des coronaires.","ok":true,"why":"C'est la définition de l'intervention de Bentall."},{"t":"La plastie aortique conservatrice est réalisable par tout chirurgien cardiaque sans expérience particulière.","ok":false,"why":"Elle n'est pratiquée que par des chirurgiens entraînés, dans des situations sélectionnées (feuillets peu altérés)."},{"t":"L'intervention de Ross utilise la valve pulmonaire du patient pour remplacer la valve aortique.","ok":true,"why":"C'est le principe de l'autogreffe pulmonaire en position aortique."},{"t":"Le choix final de la prothèse revient toujours au chirurgien, indépendamment de l'avis du patient.","ok":false,"why":"Le choix final revient au patient, sauf contre-indication claire à l'un des types de prothèse."}],"explanation":"L'IA isolée relève d'un RVA simple, l'IA avec dilatation aortique d'un Bentall (RVA + tube aortique avec réimplantation coronaire) ou d'une plastie conservatrice chez des chirurgiens entraînés ; le choix de prothèse revient au patient, sauf contre-indication.","src":"p. 240"},{"id":"233-qcm-312","type":"QRM","rank":"B","objective":"233-obj-10","tags":["traitement","pièges"],"difficulty":3,"stem":"Concernant les indications chirurgicales de l'insuffisance aortique sévère, quelles propositions sont exactes ?","options":[{"t":"Chez un patient symptomatique, l'indication opératoire est formelle.","ok":true,"why":"Les symptômes (dyspnée, angor, IC) constituent une indication formelle de chirurgie."},{"t":"Chez l'asymptomatique, un diamètre télésystolique du VG > 50 mm ou > 25 mm/m² est une indication formelle.","ok":true,"why":"C'est l'un des critères de retentissement imposant l'intervention chez l'asymptomatique."},{"t":"Chez l'asymptomatique à bas risque chirurgical, un seuil de FEVG ≤ 55 % (au lieu de 50 %) peut faire poser l'indication.","ok":true,"why":"Le seuil est abaissé chez les patients à bas risque opératoire pour intervenir plus précocement."},{"t":"Une chirurgie cardiaque prévue pour une autre raison (pontage, autre valve) rend l'indication de traiter l'IA sévère associée facultative.","ok":false,"why":"Dans ce cas l'indication à traiter l'IA sévère associée est au contraire formelle, profitant du même temps opératoire."},{"t":"Chez le patient atteint de syndrome de Marfan, le seuil aortique opératoire est le même que dans la population générale (55 mm).","ok":false,"why":"Il est abaissé à 50 mm dans le Marfan, voire 45 mm en présence de facteurs de risque supplémentaires."}],"explanation":"L'indication opératoire de l'IA sévère est formelle chez le symptomatique, en cas de DTS > 50 mm (25 mm/m²) ou FEVG ≤ 50 %, ou lorsqu'une autre chirurgie cardiaque est prévue ; à bas risque, le seuil de FEVG est abaissé à 55 %, et le seuil aortique du Marfan à 50 mm.","src":"p. 240-241"},{"id":"233-qcm-313","type":"QRM","rank":"B","objective":"233-obj-10","tags":["traitement"],"difficulty":2,"stem":"Concernant les facteurs de risque abaissant le seuil de diamètre aortique opératoire (Marfan, bicuspidie), quelles propositions sont exactes ?","options":[{"t":"Une histoire familiale ou personnelle de dissection aortique en fait partie.","ok":true,"why":"C'est l'un des facteurs de risque cités abaissant le seuil opératoire."},{"t":"Une progression du diamètre aortique supérieure à 3 mm par an en fait partie.","ok":true,"why":"Une progression rapide constitue un facteur de risque supplémentaire."},{"t":"Une hypertension artérielle bien contrôlée en fait partie.","ok":false,"why":"C'est au contraire l'HTA non contrôlée qui est citée comme facteur de risque."},{"t":"Une insuffisance mitrale ou aortique sévère associée en fait partie.","ok":true,"why":"La présence d'une autre valvulopathie sévère est un facteur de risque additionnel."},{"t":"Le désir de grossesse en fait partie.","ok":true,"why":"Il est cité parmi les facteurs de risque justifiant d'abaisser le seuil opératoire."}],"explanation":"Les facteurs de risque abaissant le seuil aortique opératoire sont : antécédent personnel ou familial de dissection, progression > 3 mm/an, HTA non contrôlée, IA ou IM sévère associée, et désir de grossesse.","src":"p. 240-241"},{"id":"233-qcm-314","type":"QRM","rank":"B","objective":"233-obj-10","tags":["traitement"],"difficulty":1,"stem":"Concernant le bilan préopératoire et les résultats de la chirurgie de l'insuffisance aortique, quelles propositions sont exactes ?","options":[{"t":"Le bilan comporte une imagerie des coronaires par coroscanner ou coronarographie.","ok":true,"why":"C'est un élément systématique du bilan préopératoire d'une valvulopathie."},{"t":"Un angioscanner ou une ARM aortique est réalisé en cas de dilatation de l'aorte.","ok":true,"why":"Cette imagerie précise les dimensions exactes pour planifier le geste."},{"t":"Un avis gériatrique est recherché chez le patient fragile de plus de 75 ans.","ok":true,"why":"Il permet de peser le rapport bénéfice/risque de l'intervention chez le sujet âgé fragile."},{"t":"La mortalité périopératoire d'un RVA isolé chez l'asymptomatique dépasse habituellement 15 %.","ok":false,"why":"Elle est en réalité de 1 à 3 % chez l'asymptomatique opéré pour un RVA isolé."},{"t":"La mortalité augmente en cas de chirurgie associée de l'aorte ascendante ou de pontages coronariens.","ok":true,"why":"Elle atteint alors 3 à 10 % selon le contexte."}],"explanation":"Le bilan préopératoire (coronaires, aorte si dilatation, avis gériatrique si fragile) prépare une chirurgie dont la mortalité reste faible (1-3 % pour un RVA isolé asymptomatique), mais augmente (3-10 %) si un geste associé sur l'aorte ou les coronaires est nécessaire.","src":"p. 241-242"},{"id":"233-qru-305","type":"QRU","rank":"B","objective":"233-obj-09","tags":["traitement"],"difficulty":2,"stem":"Concernant le TAVI (remplacement valvulaire percutané) dans l'insuffisance aortique, quelle proposition est exacte ?","options":[{"t":"Il constitue le traitement de référence de l'IA chez le sujet jeune.","ok":false,"why":"Le traitement de référence reste le remplacement chirurgical ; le TAVI n'est qu'une option marginale à haut risque."},{"t":"Il est recommandé en présence d'une endocardite infectieuse active.","ok":false,"why":"Il est au contraire proposé en l'absence d'endocardite infectieuse."},{"t":"Il peut être proposé chez des patients à très haut risque chirurgical ou contre-indiqués à la chirurgie.","ok":true,"why":"C'est l'indication marginale actuellement retenue pour le TAVI dans l'IA."},{"t":"Les prothèses actuelles sont spécifiquement conçues pour s'ancrer dans l'IA, sans risque particulier.","ok":false,"why":"Elles ne sont pas conçues pour cette pathologie, s'accrochant sur des calcifications absentes dans l'IA pure, avec un risque de migration."},{"t":"Il remplace désormais la chirurgie dans la majorité des cas d'IA sévère.","ok":false,"why":"Il reste une solution très marginale, la chirurgie restant le traitement de référence dans la grande majorité des cas."}],"explanation":"Le TAVI n'est qu'une option marginale dans l'IA, réservée aux patients à très haut risque ou inopérables, en l'absence d'endocardite, car les prothèses actuelles ne sont pas conçues pour cette pathologie (risque de migration).","src":"p. 242"},{"id":"233-qcm-316","type":"QRM","rank":"B","objective":"233-obj-06","tags":["paraclinique"],"difficulty":1,"stem":"Concernant la coronarographie préopératoire dans l'insuffisance aortique, quelles propositions sont exactes ?","options":[{"t":"Elle peut être demandée chez les hommes de plus de 40 ans en cas de chirurgie envisagée.","ok":true,"why":"C'est le seuil d'âge cité chez l'homme pour discuter une coronarographie préopératoire."},{"t":"Elle peut être demandée chez les femmes de plus de 50 ans en cas de chirurgie envisagée.","ok":true,"why":"C'est le seuil d'âge cité chez la femme, différent de celui retenu pour le RA."},{"t":"Elle est systématique chez tout patient candidat à la chirurgie, quel que soit l'âge ou le risque cardiovasculaire.","ok":false,"why":"Elle est surtout discutée selon l'âge, les facteurs de risque, ou un coroscanner non concluant."},{"t":"Un coroscanner non concluant peut justifier de compléter par une coronarographie.","ok":true,"why":"C'est l'une des indications résiduelles de la coronarographie face au développement du coroscanner."},{"t":"La présence de facteurs de risque cardiovasculaire est un argument pour la demander.","ok":true,"why":"Les facteurs de risque cardiovasculaire renforcent l'indication d'une évaluation coronaire avant chirurgie."}],"explanation":"La coronarographie préopératoire de l'IA est discutée chez l'homme > 40 ans, la femme > 50 ans, en présence de facteurs de risque cardiovasculaire, ou quand le coroscanner montre une sténose ou n'est pas concluant.","src":"p. 236"},{"id":"233-qcm-317","type":"QRM","rank":"B","objective":"233-obj-07","tags":["complications"],"difficulty":2,"stem":"Concernant les complications de l'insuffisance aortique, quelles propositions sont exactes ?","options":[{"t":"L'IA chronique expose à un faible surrisque d'endocardite infectieuse, comme toute valvulopathie.","ok":true,"why":"C'est précisé pour l'IA chronique, au même titre que les autres valvulopathies."},{"t":"Dans l'IA chronique, l'insuffisance cardiaque gauche ou globale est une complication tardive, quand la dilatation VG est majeure et la fonction altérée.","ok":true,"why":"C'est la traduction d'un remodelage VG dépassé par la surcharge chronique."},{"t":"Dans l'IA aiguë, l'insuffisance cardiaque peut survenir sans dilatation ni baisse de FE du VG.","ok":true,"why":"Le VG non préparé ne peut s'adapter à la surcharge brutale, d'où une IC sans dilatation ni baisse de FE."},{"t":"La dissection ou la rupture aortique ne complique jamais l'IA chronique.","ok":false,"why":"C'est au contraire une complication reconnue, en lien avec la dilatation de la racine aortique."},{"t":"Ces complications sont identiques, qu'il s'agisse d'une IA aiguë ou chronique.","ok":false,"why":"Le mode et le mécanisme des complications diffèrent nettement entre les formes aiguë et chronique."}],"explanation":"L'IA chronique expose à un faible surrisque d'EI et à une IC tardive quand le remodelage VG est dépassé, alors que l'IA aiguë peut donner une IC sans dilatation ni baisse de FE ; la dissection/rupture aortique reste une complication possible des deux formes.","src":"p. 238"},{"id":"233-qcm-318","type":"QRM","rank":"B","objective":"233-obj-10","tags":["traitement","urgence"],"difficulty":2,"stem":"Concernant l'indication chirurgicale de l'endocardite infectieuse compliquant une insuffisance aortique, quelles propositions sont exactes ?","options":[{"t":"L'indication chirurgicale n'est pas systématique en cas d'endocardite sur valve native ou sur prothèse.","ok":true,"why":"Contrairement à d'autres situations d'IA, la chirurgie d'endocardite se discute au cas par cas."},{"t":"Elle est notamment discutée en présence d'un sepsis non maîtrisé.","ok":true,"why":"Un sepsis non contrôlé malgré l'antibiothérapie est un argument fort pour opérer."},{"t":"Elle est notamment discutée en cas d'insuffisance cardiaque.","ok":true,"why":"L'IC est l'une des situations poussant vers une chirurgie d'endocardite."},{"t":"Elle est notamment discutée en cas de risque embolique majeur devant de très volumineuses végétations.","ok":true,"why":"Le risque embolique lié à des végétations volumineuses est un argument opératoire classique."},{"t":"L'IA aiguë sur endocardite est toujours traitée médicalement, la chirurgie étant contre-indiquée en contexte septique.","ok":false,"why":"Une chirurgie précoce est au contraire souvent nécessaire dans l'IA aiguë sur endocardite, malgré le contexte infectieux."}],"explanation":"L'indication chirurgicale de l'endocardite (valve native ou prothèse) n'est pas systématique ; elle est discutée en cas de sepsis non maîtrisé, d'insuffisance cardiaque ou de risque embolique majeur devant des végétations volumineuses.","src":"p. 241"},{"id":"233-qroc-301","type":"QROC","rank":"A","objective":"233-obj-04","tags":["paraclinique"],"difficulty":2,"question":"Quel seuil de débit dans la chambre de chasse du VG est en faveur d'une insuffisance aortique volumétriquement significative ?","answer":"Supérieur à 4 L/min/m²","accept":["> 4 L/min/m2","4 litres par minute par m2"],"keywords":["4","L/min/m2","hyperdébit"],"explanation":"Un hyperdébit supérieur à 4 L/min/m² dans la chambre de chasse du ventricule gauche est un critère indirect en faveur d'une fuite aortique de grade 3 ou 4.","src":"p. 235"},{"id":"233-qroc-302","type":"QROC","rank":"B","objective":"233-obj-04","tags":["paraclinique"],"difficulty":2,"question":"Quelle méthode échographique de quantification s'intéresse au flux en amont de l'orifice régurgitant plutôt qu'au jet lui-même ?","answer":"La méthode PISA (zone de convergence proximale)","accept":["PISA","proximal isovelocity surface area"],"keywords":["PISA","convergence"],"explanation":"La méthode PISA (proximal isovelocity surface area) analyse le flux convergeant en amont de l'orifice régurgitant pour calculer la surface de l'orifice et le volume régurgité, applicable dans l'IA comme dans l'IM.","src":"p. 235"},{"id":"233-qroc-303","type":"QROC","rank":"B","objective":"233-obj-04","tags":["imagerie","étiologie"],"difficulty":2,"question":"Quel aspect de la racine aortique en imagerie évoque une maladie annuloectasiante ?","answer":"Aspect piriforme ou en bulbe d'oignon","accept":["bulbe d'oignon","piriforme"],"keywords":["piriforme","bulbe","oignon"],"explanation":"Une racine aortique dilatée avec un aspect « piriforme » ou « en bulbe d'oignon », prédominant sur l'anneau et les sinus, est caractéristique d'une maladie annuloectasiante (Marfan et apparentés).","src":"p. 235"},{"id":"233-qroc-304","type":"QROC","rank":"B","objective":"233-obj-06","tags":["diagnostic"],"difficulty":1,"question":"Quel signe à l'épreuve d'effort traduit une mauvaise tolérance fonctionnelle de l'insuffisance aortique ?","answer":"Arrêt de l'effort pour dyspnée avec capacité < 80-85 % de la valeur théorique","accept":["dyspnée à l'effort","capacité diminuée"],"keywords":["dyspnée","80","théorique"],"explanation":"La mauvaise tolérance à l'effort se traduit par un arrêt pour dyspnée (et non pour épuisement musculaire), une capacité d'effort inférieure à 80-85 % de la théorique, un plafonnement du pouls d'O2 ou des troubles du rythme ventriculaire.","src":"p. 236"},{"id":"233-qroc-305","type":"QROC","rank":"A","objective":"233-obj-04","tags":["diagnostic"],"difficulty":1,"question":"Quel est le principal diagnostic différentiel d'un souffle diastolique de type insuffisance aortique ?","answer":"L'insuffisance pulmonaire","accept":["IP","insuffisance valve pulmonaire"],"keywords":["insuffisance pulmonaire"],"explanation":"Le principal diagnostic différentiel d'un souffle diastolique est l'insuffisance pulmonaire, dans un contexte le plus souvent différent de cardiopathie congénitale connue ; l'échocardiographie permet de trancher.","src":"p. 237"},{"id":"233-qroc-306","type":"QROC","rank":"B","objective":"233-obj-07","tags":["complications"],"difficulty":2,"question":"Quel pourcentage de récurrence familiale de bicuspidie justifie de proposer un dépistage chez les apparentés d'un patient bicuspide ?","answer":"Environ 10 %","accept":["10 pourcent","10%"],"keywords":["10","récurrence","bicuspidie"],"explanation":"Le risque de récurrence familiale de la bicuspidie aortique est estimé à environ 10 %, ce qui justifie de proposer, sans l'imposer comme dans le Marfan, un dépistage des apparentés.","src":"p. 238"},{"id":"233-qroc-307","type":"QROC","rank":"B","objective":"233-obj-07","tags":["suivi"],"difficulty":1,"question":"À quel rythme surveille-t-on cliniquement et échographiquement une insuffisance aortique modérée à moyenne ?","answer":"Tous les 2 à 3 ans","accept":["2-3 ans"],"keywords":["2","3","ans"],"explanation":"Une fuite modérée à moyenne est suivie tous les 2 à 3 ans, contre 1 à 2 fois par an pour une fuite sévère.","src":"p. 238-239"},{"id":"233-qroc-308","type":"QROC","rank":"A","objective":"233-obj-12","tags":["traitement","pièges"],"difficulty":2,"question":"Quelle classe médicamenteuse est classiquement contre-indiquée dans l'insuffisance aortique décompensée, en dehors du contexte du Marfan ?","answer":"Les bêtabloquants","accept":["bêta-bloquants","BB"],"keywords":["bêtabloquants"],"explanation":"Les bêtabloquants sont classiquement contre-indiqués dans l'IA décompensée car ils allongent la diastole et aggravent le volume régurgité, sauf dans le Marfan où ils sont au contraire le traitement de référence pour protéger l'aorte.","src":"p. 239"},{"id":"233-qroc-309","type":"QROC","rank":"A","objective":"233-obj-12","tags":["prévention"],"difficulty":1,"question":"Dans quelles situations une antibioprophylaxie de l'endocardite est-elle recommandée chez un porteur d'insuffisance aortique ?","answer":"Antécédent d'endocardite, prothèse valvulaire, ou cardiopathie cyanogène","accept":["antécédent EI prothèse cyanogène"],"keywords":["antécédent","prothèse","cyanogène"],"explanation":"L'antibioprophylaxie n'est plus systématique sur valve native ; elle est réservée aux patients ayant un antécédent d'endocardite infectieuse, une prothèse valvulaire ou une cardiopathie cyanogène.","src":"p. 239-240"},{"id":"233-qroc-310","type":"QROC","rank":"B","objective":"233-obj-08","tags":["traitement"],"difficulty":2,"question":"Comment se nomme l'intervention associant remplacement valvulaire aortique et remplacement de l'aorte ascendante avec réimplantation des coronaires ?","answer":"Intervention de Bentall","accept":["Bentall"],"keywords":["Bentall"],"explanation":"L'intervention de Bentall associe un remplacement valvulaire aortique par prothèse à un tube prothétique remplaçant l'aorte ascendante, avec réimplantation des artères coronaires sur le tube.","src":"p. 240"},{"id":"233-qroc-311","type":"QROC","rank":"B","objective":"233-obj-10","tags":["traitement"],"difficulty":2,"question":"Quel diamètre de l'aorte ascendante impose une indication chirurgicale formelle chez un patient porteur d'un syndrome de Marfan, quel que soit le grade de l'IA ?","answer":"50 mm","accept":["≥ 50 mm"],"keywords":["50","mm","Marfan"],"explanation":"Chez le patient Marfan, le seuil opératoire aortique formel est abaissé à 50 mm (contre 55 mm en population générale), voire 45 mm en présence de facteurs de risque supplémentaires.","src":"p. 240-241"},{"id":"233-qroc-312","type":"QROC","rank":"B","objective":"233-obj-09","tags":["traitement"],"difficulty":1,"question":"Pourquoi le TAVI reste-t-il une solution marginale dans l'insuffisance aortique ?","answer":"Les prothèses ne sont pas conçues pour s'ancrer en l'absence de calcifications, avec un risque de migration","accept":["risque de migration absence de calcification"],"keywords":["migration","calcification"],"explanation":"Les prothèses TAVI s'ancrent habituellement sur les calcifications valvulaires, souvent absentes ou minimes dans l'IA pure, ce qui expose à un risque de migration de la prothèse après implantation.","src":"p. 242"},{"id":"233-open-31","type":"OPEN","rank":"A","objective":"233-obj-10","tags":["traitement"],"difficulty":2,"prompt":"Un patient de 58 ans, porteur d'une insuffisance aortique sévère connue, reste totalement asymptomatique. Son échocardiographie de suivi montre un diamètre télésystolique du VG à 53 mm et une FEVG à 58 %. Discutez la conduite à tenir et justifiez.","rubric":[{"point":"Identifier que le patient est resté « à risque » malgré l'absence de symptômes","weight":1},{"point":"Reconnaître un DTS > 50 mm comme critère formel d'indication opératoire chez l'asymptomatique","weight":3},{"point":"Préciser que la FEVG à 58 % ne contre-indique pas l'intervention, l'indication étant déjà posée sur le DTS","weight":2},{"point":"Conclure à une indication chirurgicale formelle malgré l'absence de symptômes","weight":2}],"model":"Bien que ce patient soit asymptomatique, son diamètre télésystolique du VG à 53 mm dépasse le seuil de 50 mm qui constitue, à lui seul, une indication chirurgicale formelle dans l'IA sévère asymptomatique. La FEVG à 58 % est encore conservée et ne modifie pas cette indication, qui repose ici uniquement sur la dilatation ventriculaire. Il ne faut pas attendre l'apparition de symptômes ou une altération plus marquée de la FEVG pour proposer le remplacement valvulaire aortique, car le remodelage ventriculaire pourrait alors devenir partiellement irréversible.","src":"p. 240-241"},{"id":"233-open-32","type":"OPEN","rank":"B","objective":"233-obj-07","tags":["complications","suivi"],"difficulty":2,"prompt":"Expliquez pourquoi l'indication opératoire de l'insuffisance aortique chronique sévère est souvent posée chez un patient encore asymptomatique.","rubric":[{"point":"Rappeler que l'IA chronique peut rester longtemps silencieuse malgré un retentissement VG déjà significatif","weight":2},{"point":"Expliquer que le remodelage VG (fibrose, dysfonction) peut devenir irréversible s'il est trop avancé","weight":3},{"point":"Relier ceci à la nécessité d'une surveillance échographique régulière pour détecter précocement ce retentissement","weight":2},{"point":"Citer les critères objectifs utilisés (dilatation VG, FEVG, diamètre aortique)","weight":2}],"model":"L'IA chronique peut rester asymptomatique pendant de nombreuses années malgré un retentissement déjà installé sur le ventricule gauche, car ce dernier s'adapte progressivement par un remodelage excentrique compliant. Le problème est que ce remodelage, lorsqu'il devient trop marqué, entraîne des lésions myocardiques (fibrose) potentiellement irréversibles, qui ne régressent pas complètement après la chirurgie. C'est pourquoi l'indication opératoire ne peut pas attendre l'apparition des symptômes : elle repose sur une surveillance échographique régulière recherchant des critères objectifs de retentissement (dilatation du VG en systole, baisse de la FEVG) ou une dilatation aortique atteignant les seuils opératoires, afin d'opérer avant que les lésions ne deviennent définitives.","src":"p. 238, 240-241"},{"id":"233-open-33","type":"OPEN","rank":"B","objective":"233-obj-12","tags":["traitement","pièges"],"difficulty":2,"prompt":"Un patient porteur d'un syndrome de Marfan avec dilatation de l'aorte ascendante vous demande s'il peut prendre un bêtabloquant qu'un ami lui a conseillé pour son cœur. Que lui répondez-vous et pourquoi ?","rubric":[{"point":"Confirmer que les bêtabloquants sont justement le traitement validé pour protéger l'aorte dans le Marfan","weight":3},{"point":"Distinguer cette situation de l'IA sévère décompensée où les bêtabloquants sont classiquement contre-indiqués","weight":2},{"point":"Mentionner l'alternative des ARA2 en cas d'intolérance aux bêtabloquants","weight":2},{"point":"Rappeler l'importance du dépistage familial et de la surveillance aortique associée","weight":1}],"model":"Dans le contexte du syndrome de Marfan, contrairement à l'idée reçue selon laquelle les bêtabloquants seraient à éviter dans l'insuffisance aortique, ils constituent au contraire le traitement médicamenteux validé pour ralentir la dilatation aortique et protéger la paroi du risque de dissection. Cette recommandation ne s'applique pas à l'IA sévère décompensée en insuffisance cardiaque congestive, où les bêtabloquants restent classiquement contre-indiqués car ils allongent la diastole et aggravent la fuite. En cas d'intolérance aux bêtabloquants, les ARA2 peuvent être utilisés en alternative. Il convient également de rappeler l'intérêt d'un dépistage familial et d'une surveillance régulière du diamètre aortique.","src":"p. 239-240"},{"id":"233-open-34","type":"OPEN","rank":"B","objective":"233-obj-08","tags":["traitement","suivi"],"difficulty":3,"prompt":"Comparez les indications respectives du remplacement valvulaire aortique isolé, du Bentall et de la plastie aortique conservatrice dans la prise en charge chirurgicale de l'insuffisance aortique.","rubric":[{"point":"RVA isolé : IA sans dilatation aortique significative associée","weight":2},{"point":"Bentall : IA avec dilatation de l'aorte ascendante, remplacement du tube avec réimplantation des coronaires","weight":3},{"point":"Plastie conservatrice : chirurgiens entraînés, feuillets peu altérés ou bicuspidie peu dégradée, racine dilatée","weight":3},{"point":"Souligner que le choix dépend de l'état des feuillets et de l'aorte, pas seulement de la sévérité de la fuite","weight":1}],"model":"Lorsque l'insuffisance aortique est isolée, sans dilatation significative de la racine ou de l'aorte ascendante, un remplacement valvulaire aortique simple par prothèse mécanique ou biologique suffit. Lorsqu'une dilatation aortique est associée, l'intervention de Bentall remplace à la fois la valve et l'aorte ascendante par un tube prothétique sur lequel sont réimplantées les artères coronaires, ou plus rarement un tube sus-coronaire est utilisé si les coronaires n'ont pas à être réimplantées. La plastie aortique conservatrice (techniques de Tirone David ou Yacoub), qui préserve la valve native du patient tout en remplaçant l'aorte initiale avec réimplantation coronaire, n'est réalisée que par des chirurgiens entraînés, chez des patients dont les feuillets sont normaux ou une bicuspidie peu altérée, lorsque la fuite est principalement due à la dilatation de la racine. Le choix ne dépend donc pas seulement du grade de la fuite mais de l'état des feuillets valvulaires et du diamètre de l'aorte.","src":"p. 240"}],"edn":[{"id":"233-kfp-01","type":"KFP","rank":"A","objective":"233-obj-04","difficulty":2,"scenario":"M. R., 74 ans, hypertendu, consulte pour une dyspnée d'effort progressive depuis six mois et des malaises en montant les escaliers. L'auscultation retrouve un souffle systolique rugueux 3/6 au foyer aortique irradiant vers les carotides, avec un B2 aboli. L'échocardiographie transthoracique montre une valve aortique calcifiée, une vitesse maximale transvalvulaire à 4,6 m/s, un gradient moyen à 52 mmHg et une surface aortique estimée à 0,7 cm². La fraction d'éjection ventriculaire gauche est à 60 %.","questions":[{"stem":"Quel(s) élément(s) de ce dossier permettent d'affirmer le caractère serré du rétrécissement aortique ?","max":3,"options":["Vitesse maximale transvalvulaire à 4,6 m/s","Gradient moyen à 52 mmHg","Surface aortique estimée à 0,7 cm²","Fraction d'éjection ventriculaire gauche à 60 %","Irradiation du souffle vers les carotides","Abolition du B2","Âge du patient (74 ans)","Dyspnée d'effort rapportée par le patient"],"correct":[0,1,2],"explanation":"Les trois critères échocardiographiques du RA serré sont une Vmax > 4 m/s, un gradient moyen > 40 mmHg et une surface < 1 cm² (ou < 0,6 cm²/m²) : les trois sont réunis ici. La FEVG, l'irradiation carotidienne, l'abolition de B2, l'âge et la dyspnée sont des éléments cliniques ou de retentissement mais pas des critères de sévérité échographique."},{"stem":"Quel(s) symptôme(s) évocateur(s) d'un tournant évolutif faut-il rechercher activement à l'interrogatoire chez ce patient ?","max":3,"options":["Dyspnée d'effort","Angor d'effort","Syncope d'effort","Palpitations isolées","Œdèmes des membres inférieurs isolés","Douleur thoracique de repos","Vertiges positionnels","Hémoptysie"],"correct":[0,1,2],"explanation":"Dyspnée, angor et syncope d'effort sont les trois symptômes cardinaux du RA : leur apparition marque une rupture évolutive de mauvais pronostic et doit faire poser une indication de traitement. Les autres propositions ne sont pas des symptômes typiques du RA."},{"stem":"Compte tenu de ce tableau de RA serré très probablement symptomatique, quelle prise en charge est adaptée ?","max":2,"options":["Remplacement valvulaire aortique chirurgical ou TAVI, indiqué du fait du caractère serré et symptomatique","Surveillance simple avec échocardiographie annuelle, sans geste","Traitement diurétique isolé au long cours","Valvuloplastie percutanée en première intention","Réalisation d'une épreuve d'effort pour confirmer l'indication opératoire","Introduction d'un bêtabloquant au long cours","Discussion pluridisciplinaire en Heart Team pour choisir entre chirurgie conventionnelle et TAVI","Antibioprophylaxie systématique avant tout soin dentaire"],"correct":[0,6],"explanation":"Tout RA serré symptomatique doit être traité (chirurgie ou TAVI), quasiment sans limite d'âge si l'état général le permet. Le choix entre les deux techniques repose sur une discussion pluridisciplinaire (Heart Team). L'épreuve d'effort est réservée aux patients réellement asymptomatiques, la valvuloplastie percutanée est quasi abandonnée sauf urgence non cardiaque, et il n'existe pas de traitement médicamenteux spécifique du RA."}],"src":"p. 199-206"},{"id":"233-kfp-02","type":"KFP","rank":"B","objective":"233-obj-08","difficulty":2,"scenario":"Mme L., 58 ans, sportive, est adressée pour un souffle systolique découvert lors d'une visite de médecine du sport, associé à une dyspnée d'effort modérée depuis quelques mois. L'auscultation retrouve un souffle holosystolique 3/6 maximal à la pointe, irradiant vers l'aisselle. L'échocardiographie objective un prolapsus du feuillet postérieur par rupture de cordage, un diamètre télésystolique du ventricule gauche à 44 mm, une fraction d'éjection à 62 %, une surface de l'orifice régurgitant à 45 mm² et un volume régurgité de 65 mL par battement.","questions":[{"stem":"Quel(s) élément(s) du mécanisme sont compatibles avec ce tableau ?","max":3,"options":["Prolapsus valvulaire (type II de Carpentier)","Rupture de cordage","Jeu valvulaire restreint (type III de Carpentier)","Dilatation isolée de l'anneau par fibrillation atriale (type I)","Origine ischémique par akinésie inférieure","Insuffisance mitrale primaire (organique)","Insuffisance mitrale secondaire (fonctionnelle)","Atteinte des piliers par dilatation ventriculaire"],"correct":[0,1,5],"explanation":"Le prolapsus avec rupture de cordage correspond au type II de Carpentier et relève d'une IM primaire (organique), la valve elle-même étant lésée. Les types I et III, ainsi que les mécanismes ischémiques ou par dilatation ventriculaire, correspondent aux IM secondaires et ne s'appliquent pas ici."},{"stem":"Quel est le grade de sévérité de cette insuffisance mitrale d'après les données échocardiographiques ?","max":1,"options":["Grade I : IM minime","Grade II : IM modérée","Grade III : IM moyenne","Grade IV : IM importante","Grade non quantifiable en échocardiographie transthoracique","IM fonctionnelle non gradée","Grade I à II selon le seul volume régurgité","Grade III selon la seule surface de l'orifice régurgitant"],"correct":[3],"explanation":"Une surface d'orifice régurgitant ≥ 40 mm² et un volume régurgité ≥ 60 mL par battement définissent le grade IV (IM importante) selon la classification en quatre grades des IM primaires."},{"stem":"Compte tenu de la sévérité (grade IV) et du retentissement (DTS 44 mm > 40 mm), quelle prise en charge proposez-vous ?","max":2,"options":["Chirurgie réparatrice (plastie mitrale), l'IM primaire étant importante avec un DTS > 40 mm","Surveillance simple sans geste ni rapprochement du suivi","Remplacement valvulaire mécanique d'emblée sans tenter la plastie","Traitement médical de l'insuffisance cardiaque en première intention","Réparation percutanée bord à bord en première intention chez cette patiente opérable","Antibioprophylaxie systématique avant tout soin dentaire","Bilan préopératoire comportant une imagerie des coronaires","Absence d'indication tant qu'elle reste peu symptomatique"],"correct":[0,6],"explanation":"Une IM primaire de grade III-IV avec retentissement (DTS > 40 mm) relève d'une chirurgie, en privilégiant la plastie reconstructrice sur prolapsus, précédée d'un bilan préopératoire incluant l'exploration coronaire. Le traitement percutané est réservé aux patients à haut risque chirurgical, et l'antibioprophylaxie systématique n'est plus recommandée."}],"src":"p. 209-222"},{"id":"233-kfp-03","type":"KFP","rank":"B","objective":"233-obj-05","difficulty":3,"scenario":"M. T., 45 ans, suivi pour une bicuspidie aortique connue depuis l'enfance, consulte pour une dyspnée d'effort d'aggravation progressive. La pression artérielle est à 148/54 mmHg avec une hyperpulsatilité des pouls périphériques. L'auscultation retrouve un souffle diastolique holodiastolique au bord gauche du sternum. L'échocardiographie montre un diamètre télésystolique du ventricule gauche à 52 mm, une fraction d'éjection à 48 % et une aorte ascendante mesurée à 42 mm.","questions":[{"stem":"Quel(s) mécanisme(s) physiopathologique(s) explique(nt) ce tableau clinique ?","max":4,"options":["Surcharge volumétrique du ventricule gauche par régurgitation diastolique","Surcharge barométrique par augmentation du volume d'éjection systolique dans l'aorte","Hypertrophie concentrique isolée du ventricule gauche","Élargissement de la pression artérielle différentielle par abaissement de la pression diastolique","Sténose de la chambre de chasse du ventricule gauche","Obstacle à l'éjection ventriculaire gauche en systole","Remodelage de type hypertrophie excentrique du ventricule gauche","Dysfonction diastolique isolée sans dilatation ventriculaire"],"correct":[0,1,3,6],"explanation":"L'IA chronique associe une surcharge mixte, volumétrique (régurgitation diastolique) et barométrique (volume d'éjection augmenté dans l'aorte), aboutissant à un remodelage de type hypertrophie excentrique et à un élargissement de la différentielle tensionnelle. Il n'y a ni obstacle à l'éjection ni hypertrophie purement concentrique, ceci caractérisant le rétrécissement aortique."},{"stem":"Quel(s) élément(s) de ce dossier justifie(nt) une indication chirurgicale formelle ?","max":3,"options":["Dyspnée d'effort (patient symptomatique)","Fraction d'éjection ventriculaire gauche à 48 % (≤ 50 %)","Diamètre télésystolique du VG à 52 mm (> 50 mm)","Diamètre de l'aorte ascendante à 42 mm","Hyperpulsatilité isolée des pouls périphériques","Élargissement isolé de la différentielle tensionnelle","Bicuspidie aortique connue, en l'absence d'autre critère","Souffle diastolique isolé, en l'absence d'autre critère"],"correct":[0,1,2],"explanation":"La présence de symptômes, une FEVG ≤ 50 % et un DTS du VG > 50 mm sont chacun des critères formels d'indication chirurgicale dans l'IA sévère. Le diamètre aortique à 42 mm reste en revanche très en deçà des seuils opératoires (55 mm, ou 50 mm dans le Marfan)."},{"stem":"Quelle prise en charge proposez-vous à ce patient ?","max":3,"options":["Remplacement valvulaire aortique chirurgical","Traitement médicamenteux spécifique de l'IA en première intention","Bêtabloquant systématique car il ralentirait l'aggravation de la fuite","TAVI en première intention chez ce patient de 45 ans","Surveillance simple, la chirurgie n'étant pas indiquée","Bilan préopératoire comportant une imagerie des coronaires","Surveillance échographique de l'aorte ascendante, y compris après la chirurgie valvulaire","Antibioprophylaxie systématique avant tout soin dentaire"],"correct":[0,5,6],"explanation":"L'IA sévère symptomatique avec FEVG abaissée et VG dilaté impose un remplacement valvulaire chirurgical, précédé d'un bilan préopératoire (imagerie coronaire). Il n'existe pas de traitement médicamenteux spécifique de l'IA, et les bêtabloquants sont classiquement contre-indiqués car ils allongent la diastole et aggravent la fuite ; la surveillance de l'aorte ascendante doit se poursuivre après l'intervention."}],"src":"p. 226-241"},{"id":"233-tcs-01","type":"TCS","rank":"A","objective":"233-obj-04","difficulty":2,"vignette":"Un homme de 68 ans, hypertendu, consulte pour un souffle systolique découvert à l'auscultation lors d'une visite de routine. Il ne rapporte spontanément aucun symptôme mais reconnaît, à l'interrogatoire, avoir réduit ses activités physiques ces derniers mois. L'échocardiographie retrouve une valve aortique calcifiée, une vitesse maximale transvalvulaire à 4,2 m/s et une surface aortique à 0,9 cm², avec une fraction d'éjection normale.","items":[{"hypothesis":"Si vous pensiez à un rétrécissement aortique serré asymptomatique à surveiller simplement","newInfo":"et que l'épreuve d'effort révèle une chute de la pression artérielle à l'effort","panel":[10,4,1,0,0],"explanation":"Une réponse tensionnelle anormale à l'effort est un critère reconnu d'indication chirurgicale même chez un patient qui se dit asymptomatique : cette découverte affaiblit fortement l'hypothèse d'une simple surveillance, qui doit céder la place à une indication opératoire."},{"hypothesis":"Si vous pensiez à une indication opératoire du fait de symptômes réels sous-estimés","newInfo":"et que l'interrogatoire minutieux confirme une dyspnée nette limitant la marche depuis plusieurs semaines","panel":[0,0,2,4,9],"explanation":"L'apparition de symptômes, même minimisés par le patient qui a réduit ses efforts, signe un tournant évolutif du RA serré et impose le traitement : cette découverte conforte fortement l'hypothèse d'une indication opératoire."},{"hypothesis":"Si vous pensiez que ce patient relève d'une indication chirurgicale formelle immédiate","newInfo":"et que la FEVG est mesurée à 62 % sans symptôme ni anomalie de l'épreuve d'effort","panel":[8,5,1,1,0],"explanation":"Un RA serré vraiment asymptomatique, avec FEVG normale et épreuve d'effort normale, relève d'une surveillance et non d'une chirurgie immédiate : cette donnée affaiblit fortement l'hypothèse d'une indication formelle."},{"hypothesis":"Si vous pensiez à une étiologie dégénérative (maladie de Mönckeberg)","newInfo":"et que le patient a 68 ans, sans antécédent de rhumatisme articulaire aigu ni de migration récente","panel":[0,1,3,8,3],"explanation":"Le RA dégénératif du sujet de plus de 65-70 ans est de loin l'étiologie la plus fréquente en l'absence de contexte rhumatismal : cette information renforce modérément l'hypothèse dégénérative."}],"src":"p. 197-206"},{"id":"233-tcs-02","type":"TCS","rank":"B","objective":"233-obj-08","difficulty":2,"vignette":"Une femme de 55 ans, sans antécédent particulier, est explorée pour un souffle systolique apexien 2/6 découvert fortuitement lors d'un bilan systématique. Elle ne rapporte aucun symptôme. L'échocardiographie objective une insuffisance mitrale par prolapsus du feuillet antérieur, avec une surface de l'orifice régurgitant à 25 mm² et un diamètre télésystolique du ventricule gauche à 36 mm.","items":[{"hypothesis":"Si vous pensiez à une indication chirurgicale immédiate","newInfo":"et que la patiente reste strictement asymptomatique, avec une IM de grade II et un ventricule gauche non dilaté","panel":[9,4,1,1,0],"explanation":"Une IM primaire de grade II, sans retentissement ventriculaire ni symptôme, relève d'une simple surveillance : cette donnée affaiblit fortement l'hypothèse d'une chirurgie immédiate."},{"hypothesis":"Si vous pensiez qu'il s'agit d'une IM primaire (organique)","newInfo":"et que l'échocardiographie confirme un prolapsus par excès de tissu valvulaire, sans anomalie ventriculaire sous-jacente","panel":[0,0,1,4,10],"explanation":"Le prolapsus par excès de tissu correspond au type II de Carpentier, mécanisme caractéristique de l'IM primaire (valve pathologique, ventricule sain) : cette information renforce fortement l'hypothèse d'une IM primaire."},{"hypothesis":"Si vous pensiez qu'une plastie mitrale serait préférable à un remplacement valvulaire en cas de chirurgie","newInfo":"et que le prolapsus touche isolément le feuillet antérieur, de façon techniquement réparable, chez une patiente encore jeune","panel":[0,0,2,4,9],"explanation":"La plastie reconstructrice est le traitement de référence des IM sur prolapsus quand elle est techniquement réalisable, avec une moindre morbimortalité qu'un remplacement : ce contexte renforce fortement cette hypothèse."},{"hypothesis":"Si vous pensiez qu'une indication opératoire deviendrait nécessaire à court terme","newInfo":"et que la surface de l'orifice régurgitant reste stable à 25 mm² sur deux échocardiographies annuelles successives, sans dilatation ventriculaire","panel":[9,4,1,1,0],"explanation":"L'absence de progression de la fuite et de retentissement ventriculaire ne justifie pas d'intervention à court terme, seule une surveillance semestrielle étant requise : cette stabilité affaiblit fortement l'hypothèse d'une indication opératoire imminente."}],"src":"p. 217-222"},{"id":"233-tcs-03","type":"TCS","rank":"B","objective":"233-obj-10","difficulty":3,"vignette":"Un homme de 34 ans, porteur d'une bicuspidie aortique diagnostiquée dans l'enfance, est suivi annuellement. Il est totalement asymptomatique et pratique la course à pied en loisir. L'échocardiographie de suivi retrouve une insuffisance aortique modérée à moyenne et une aorte ascendante à 47 mm, stable par rapport à l'examen précédent.","items":[{"hypothesis":"Si vous pensiez à une indication opératoire formelle sur l'aorte ascendante","newInfo":"et que le diamètre aortique reste stable à 47 mm, sans facteur de risque associé","panel":[9,4,1,1,0],"explanation":"Un diamètre de 47 mm reste inférieur au seuil de 55 mm (ou 50 mm en cas de facteur de risque chez le bicuspide), et sa stabilité écarte une progression rapide : cette donnée affaiblit fortement l'hypothèse d'une chirurgie formelle sur l'aorte."},{"hypothesis":"Si vous pensiez pouvoir autoriser la poursuite du sport de loisir en endurance","newInfo":"et que l'insuffisance aortique reste de grade modéré à moyen, sans dilatation du ventricule gauche","panel":[0,0,1,4,10],"explanation":"Le sport de loisir en endurance est encouragé tant que l'IA n'est pas sévère ; seul le sport de compétition est contre-indiqué en cas d'IA sévère : cette donnée renforce fortement l'hypothèse d'une poursuite autorisée."},{"hypothesis":"Si vous pensiez qu'un dépistage familial de la bicuspidie serait justifié","newInfo":"et que le patient rapporte un frère porteur d'une bicuspidie aortique compliquée d'une dissection à 40 ans","panel":[0,0,1,3,11],"explanation":"Un antécédent familial de dissection sur bicuspidie est un facteur de risque reconnu justifiant le dépistage des apparentés du premier degré : cette information renforce très fortement l'hypothèse d'un dépistage familial."},{"hypothesis":"Si vous pensiez qu'un seuil opératoire abaissé à 50 mm devrait s'appliquer à ce patient","newInfo":"et que le contrôle échographique annuel objective une progression du diamètre aortique de 4 mm en un an","panel":[0,0,1,4,10],"explanation":"Une progression de plus de 3 mm par an constitue un facteur de risque reconnu qui abaisse le seuil opératoire à 50 mm chez le patient bicuspide : cette donnée renforce fortement l'hypothèse d'un seuil abaissé."}],"src":"p. 238-241"},{"id":"233-tcs-04","type":"TCS","rank":"B","objective":"233-obj-07","difficulty":3,"vignette":"Une femme de 42 ans, porteuse connue d'un prolapsus mitral avec insuffisance mitrale minime, consulte pour une fièvre à 38,5 °C évoluant depuis dix jours, associée à une asthénie. Elle n'a bénéficié d'aucun soin dentaire récent. L'auscultation retrouve un souffle systolique apexien qui vous paraît inchangé par rapport aux examens antérieurs.","items":[{"hypothesis":"Si vous pensiez à une endocardite infectieuse sur ce terrain de valvulopathie","newInfo":"et que des hémocultures répétées reviennent positives à streptocoque","panel":[0,0,1,3,11],"explanation":"Des hémocultures positives chez une patiente fébrile porteuse d'une valvulopathie sont très évocatrices d'endocardite infectieuse et renforcent très fortement cette hypothèse, qu'il faut systématiquement évoquer devant une fièvre chez un valvulopathe."},{"hypothesis":"Si vous pensiez à une fièvre isolée sans rapport avec la valvulopathie mitrale","newInfo":"et que le souffle mitral devient nettement plus intense qu'aux examens précédents","panel":[9,4,1,1,0],"explanation":"La modification récente d'un souffle connu chez un patient fébrile doit faire évoquer en priorité une endocardite infectieuse : cette aggravation affaiblit fortement l'hypothèse d'une fièvre sans rapport avec la valve."},{"hypothesis":"Si vous pensiez qu'une échocardiographie transœsophagienne serait nécessaire","newInfo":"et que l'échocardiographie transthoracique ne retrouve pas clairement de végétation malgré une forte suspicion clinique","panel":[0,0,1,4,10],"explanation":"L'ETO est l'examen de référence, obligatoire pour le diagnostic d'endocardite sur valve mitrale car elle détecte des végétations parfois trop fines pour l'ETT : cette situation renforce fortement l'indication d'une ETO."},{"hypothesis":"Si vous pensiez que cette patiente aurait dû bénéficier d'une antibioprophylaxie systématique avant tout soin dentaire","newInfo":"et qu'elle n'a ni prothèse valvulaire, ni antécédent d'endocardite, ni cardiopathie cyanogène","panel":[9,4,1,1,0],"explanation":"En l'absence de prothèse valvulaire, d'antécédent d'endocardite ou de cardiopathie cyanogène, l'antibioprophylaxie systématique avant un soin dentaire n'est pas recommandée sur valve native : cette donnée affaiblit fortement l'hypothèse d'une antibioprophylaxie obligatoire."}],"src":"p. 204-222"}],"trees":[{"id":"233-tree-01","title":"Souffle systolique éjectionnel : suspecter et confirmer un RA","rank":"A","objective":"233-obj-03","intro":"Devant un souffle râpeux au foyer aortique, la démarche clinique oriente vers le rétrécissement aortique avant l'échocardiographie.","root":"n1","nodes":{"n1":{"type":"question","text":"Souffle mésosystolique, rude, maximal au 2e EIC droit, irradiant aux carotides ?","options":[{"label":"Oui","to":"n2"},{"label":"Non, holosystolique apexo-axillaire","to":"n8"}]},"n2":{"type":"question","text":"Le souffle se renforce-t-il après une diastole longue (pause, ESV) ?","note":"Signe évocateur du caractère éjectionnel du souffle.","options":[{"label":"Oui","to":"n3"},{"label":"Non","to":"n9"}]},"n3":{"type":"question","text":"B2 est-il aboli à l'auscultation ?","note":"Abolition de B2 = argument pour un RA serré calcifié.","options":[{"label":"Oui","to":"n4"},{"label":"B2 conservé","to":"n5"}]},"n4":{"type":"action","text":"Prescrire une ETT en urgence relative : forte suspicion de RA serré","to":"n6"},"n5":{"type":"action","text":"Prescrire une ETT de confirmation et de quantification","to":"n6"},"n6":{"type":"question","text":"Rechercher un frémissement palpatoire au foyer aortique (souffle 4/6) ?","options":[{"label":"Présent","to":"n7"},{"label":"Absent","to":"n10"}]},"n7":{"type":"end","tone":"warn","text":"RA hémodynamiquement significatif probable — adresser au cardiologue avec l'ETT"},"n10":{"type":"end","tone":"info","text":"Souffle sans frémissement — l'ETT tranche sur la sévérité, un souffle faible n'exclut pas un RA serré à bas débit"},"n8":{"type":"end","tone":"info","text":"Souffle apexo-axillaire non renforcé après diastole longue : orienter vers une insuffisance mitrale"},"n9":{"type":"end","tone":"info","text":"Souffle éjectionnel non renforcé : réévaluer le foyer et l'irradiation, envisager un souffle d'hyperdébit ou une autre étiologie"}},"src":"p. 198-200"},{"id":"233-tree-02","title":"Décision thérapeutique devant un RA serré","rank":"B","objective":"233-obj-10","intro":"Une fois le RA confirmé serré à l'ETT, la stratégie dépend des symptômes puis, chez l'asymptomatique, de critères de gravité échographique et fonctionnelle.","root":"n1","nodes":{"n1":{"type":"question","text":"Le patient est-il symptomatique (dyspnée, angor ou syncope d'effort) ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"n3"}]},"n2":{"type":"action","text":"Indication formelle de traitement (RVA ou TAVI), pratiquement sans limite d'âge si l'état général le permet","to":"n9"},"n3":{"type":"question","text":"FEVG < 55 % ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"n4"}]},"n4":{"type":"question","text":"Vmax > 5 m/s (RA très serré) ou aggravation rapide de la sténose ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"n5"}]},"n5":{"type":"action","text":"Réaliser une épreuve d'effort chez cet asymptomatique déclaré","to":"n6"},"n6":{"type":"question","text":"Épreuve d'effort anormale (symptômes, chute ou élévation inadéquate de la PA) ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"n7"}]},"n7":{"type":"end","tone":"ok","text":"Surveillance clinique et échographique régulière, pas d'indication opératoire immédiate"},"n9":{"type":"question","text":"Risque chirurgical élevé/intermédiaire ou âge > 75 ans avec voie fémorale possible ?","options":[{"label":"Oui","to":"n10"},{"label":"Non, faible risque","to":"n11"}]},"n10":{"type":"end","tone":"warn","text":"TAVI en 1re intention, décision en Heart Team"},"n11":{"type":"end","tone":"warn","text":"RVA chirurgical (mécanique si jeune, bioprothèse si > 65 ans), après bilan préopératoire complet"}},"src":"p. 204-206"},{"id":"233-tree-03","title":"IM primaire importante : opérer ou surveiller ?","rank":"B","objective":"233-obj-10","intro":"La décision d'opérer une insuffisance mitrale primaire de grade III-IV dépend d'abord des symptômes, puis chez l'asymptomatique de quatre critères de retentissement.","root":"n1","nodes":{"n1":{"type":"question","text":"IM primaire grade III-IV symptomatique ?","options":[{"label":"Oui","to":"n2"},{"label":"Non (asymptomatique)","to":"n3"}]},"n2":{"type":"question","text":"Plastie mitrale techniquement réalisable ?","options":[{"label":"Oui","to":"n7"},{"label":"Non","to":"n4"}]},"n3":{"type":"question","text":"DTS VG > 40 mm, FEVG < 60 %, PAPs > 50 mmHg ou FA (même paroxystique) ou AG > 60 mL/m² ?","options":[{"label":"Au moins un critère présent","to":"n2"},{"label":"Aucun critère","to":"n8"}]},"n4":{"type":"question","text":"FEVG > 30 % ?","options":[{"label":"Oui","to":"n5"},{"label":"Non, FE < 30 %","to":"n6"}]},"n5":{"type":"action","text":"Remplacement valvulaire mitral (bioprothèse si > 70 ans, mécanique si < 65 ans)","to":"n9"},"n6":{"type":"end","tone":"danger","text":"Remplacement contre-indiqué (chute de FE postopératoire) : traitement médical, discuter clip ou transplantation si jeune"},"n7":{"type":"action","text":"Plastie reconstructrice mitrale, traitement de référence","to":"n9"},"n8":{"type":"end","tone":"ok","text":"Surveillance clinique et échographique tous les 6 mois"},"n9":{"type":"end","tone":"warn","text":"Chirurgie programmée avec bilan préopératoire (coronaires, TSA, foyers infectieux, comorbidités)"}},"src":"p. 219-222"},{"id":"233-tree-04","title":"Orientation d'une IM secondaire (fonctionnelle)","rank":"B","objective":"233-obj-11","intro":"L'IM secondaire relève d'une stratégie différente de l'IM primaire : elle traduit une maladie du ventricule ou de l'anneau, pas de la valve elle-même.","root":"n1","nodes":{"n1":{"type":"action","text":"Optimiser le traitement médical de l'insuffisance cardiaque (± resynchronisation si QRS larges)","to":"n2"},"n2":{"type":"question","text":"Réévaluer l'IM après optimisation : reste-t-elle importante (SOR ≥ 30 mm²) et l'IC est-elle contrôlée sans être trop avancée ?","options":[{"label":"Oui","to":"n3"},{"label":"Fuite réduite sous traitement","to":"n5"}]},"n3":{"type":"question","text":"Patient à haut risque chirurgical ou contre-indication à la chirurgie ?","options":[{"label":"Oui","to":"n4"},{"label":"Non","to":"n6"}]},"n4":{"type":"end","tone":"warn","text":"Discuter un clip bord à bord percutané en Heart Team"},"n5":{"type":"end","tone":"ok","text":"Poursuivre le traitement médical et la surveillance échographique répétée (fuite « accordéon » selon la volémie)"},"n6":{"type":"end","tone":"warn","text":"Discuter une chirurgie mitrale associée en Heart Team"}},"src":"p. 220-223"},{"id":"233-tree-05","title":"Souffle diastolique au foyer aortique : évaluer une IA","rank":"A","objective":"233-obj-03","intro":"Un souffle diastolique du bord gauche du sternum impose une démarche clinique puis échographique pour confirmer et quantifier une insuffisance aortique.","root":"n1","nodes":{"n1":{"type":"question","text":"Souffle diastolique mieux perçu penché en avant, en expiration bloquée, le long du bord gauche du sternum ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"n7"}]},"n2":{"type":"question","text":"Recherche de signes périphériques : hyperpulsatilité des pouls, PA différentielle élargie avec PAD basse ?","options":[{"label":"Présents","to":"n3"},{"label":"Absents","to":"n4"}]},"n3":{"type":"action","text":"Suspecter une IA sévère : prescrire une ETT en priorité","to":"n5"},"n4":{"type":"action","text":"Prescrire une ETT de confirmation et de quantification","to":"n5"},"n5":{"type":"question","text":"Contexte fébrile, douleur thoracique brutale ou souffle apparu rapidement ?","note":"Orienter vers une IA aiguë : endocardite ou dissection aortique.","options":[{"label":"Oui","to":"n6"},{"label":"Non, tableau chronique","to":"n8"}]},"n6":{"type":"end","tone":"danger","text":"Évoquer IA aiguë (endocardite, dissection) : hospitalisation urgente, ETO au moindre doute"},"n8":{"type":"end","tone":"info","text":"IA chronique probable : poursuivre le bilan étiologique (valve, racine aortique) et le retentissement"},"n7":{"type":"end","tone":"info","text":"Pas de souffle diastolique typique : reconsidérer le diagnostic (souffle systolique d'accompagnement possible en cas d'hyperdébit)"}},"src":"p. 232-233"},{"id":"233-tree-06","title":"Indication opératoire dans l'IA sévère","rank":"B","objective":"233-obj-10","intro":"Dans l'IA sévère, l'indication chirurgicale repose sur les symptômes, le retentissement VG et, indépendamment, le diamètre de l'aorte ascendante.","root":"n1","nodes":{"n1":{"type":"question","text":"IA sévère symptomatique (dyspnée, angor, IC) ?","options":[{"label":"Oui","to":"n6"},{"label":"Non","to":"n2"}]},"n2":{"type":"question","text":"DTS VG > 50 mm (ou > 25 mm/m²) ou FEVG ≤ 50 % ?","options":[{"label":"Oui","to":"n6"},{"label":"Non","to":"n3"}]},"n3":{"type":"question","text":"Chirurgie à bas risque envisageable et DTS > 20 mm/m² ou FEVG ≤ 55 % ?","options":[{"label":"Oui","to":"n6"},{"label":"Non","to":"n4"}]},"n4":{"type":"question","text":"Aorte ascendante ≥ 55 mm (ou seuils abaissés : 50 mm si Marfan, 45 mm si Marfan à risque, 50 mm si bicuspidie à risque) ?","options":[{"label":"Oui","to":"n6"},{"label":"Non","to":"n5"}]},"n5":{"type":"end","tone":"ok","text":"Surveillance : 1-2 fois/an si sévère, tous les 2-3 ans si modérée, suivi annuel de l'aorte"},"n6":{"type":"action","text":"Indication opératoire : RVA ± remplacement de l'aorte ascendante (Bentall) selon la dilatation","to":"n7"},"n7":{"type":"end","tone":"warn","text":"Chirurgie programmée après bilan préopératoire (coronaires, TSA, foyers infectieux, aorte en imagerie)"}},"src":"p. 240-241"},{"id":"233-tree-07","title":"Bilan étiologique devant une valvulopathie aortique","rank":"A","objective":"233-obj-02","intro":"Face à un RA ou une IA nouvellement diagnostiqués, l'orientation étiologique guide le bilan complémentaire, en particulier la mesure de l'aorte.","root":"n1","nodes":{"n1":{"type":"question","text":"Patient âgé de plus de 65-70 ans avec valve tricuspide calcifiée en 2D ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"n3"}]},"n2":{"type":"end","tone":"info","text":"RA dégénératif (Mönckeberg) probable, cause la plus fréquente après 65-70 ans"},"n3":{"type":"question","text":"Valve bicuspide identifiée en écho ?","options":[{"label":"Oui","to":"n4"},{"label":"Non","to":"n5"}]},"n4":{"type":"action","text":"Mesurer l'aorte ascendante (dilatée dans ~50 % des cas) et proposer un dépistage familial du 1er degré","to":"n8"},"n5":{"type":"question","text":"Contexte évocateur de rhumatisme articulaire aigu (migrant, atteinte mitrale associée) ?","options":[{"label":"Oui","to":"n6"},{"label":"Non","to":"n7"}]},"n6":{"type":"end","tone":"info","text":"RA/IA post-rhumatismal : rechercher une maladie mitrale associée (RM + IM)"},"n7":{"type":"end","tone":"info","text":"Rechercher une cause de dilatation de la racine (Marfan, aortite) ou une endocardite selon le contexte clinique"},"n8":{"type":"end","tone":"ok","text":"Bicuspidie confirmée : surveillance combinée de la valve et de l'aorte"}},"src":"p. 197-198, 228-232"}],"treatments":{"data":[{"id":"233-tx-01","rank":"B","class":"Remplacement valvulaire par prothèse mécanique","molecules":[],"context":"RA serré ou IM/IA sévères nécessitant un remplacement chez un patient plutôt jeune","indications":["Sujet jeune (mitrale : plutôt < 65 ans)","Longue durabilité recherchée, pas de dégénérescence"],"contraindications":["Désir de grossesse (anticoagulation difficile à gérer)","Contre-indication aux anticoagulants au long cours"],"sideEffects":["Risque hémorragique et thrombotique lié à l'anticoagulation à vie"],"monitoring":["Anticoagulation par AVK à vie","Suivi des porteurs de prothèse (cf. item dédié)"],"interactions":[],"pearls":["Pas de dégénérescence structurelle contrairement à la bioprothèse","Nécessite une observance stricte du traitement anticoagulant"],"src":"p. 205, 221"},{"id":"233-tx-02","rank":"B","class":"Remplacement valvulaire par bioprothèse","molecules":[],"context":"RA serré ou IM/IA sévères nécessitant un remplacement chez un patient plutôt âgé","indications":["Patient > 65-70 ans (mitrale : plutôt > 70 ans)","Contre-indication aux anticoagulants","Désir de grossesse"],"contraindications":["Sujet jeune si durabilité prioritaire (risque de réintervention précoce)"],"sideEffects":["Dégénérescence structurelle en 10-15 ans exposant à une réintervention"],"monitoring":["Pas d'anticoagulant au long cours nécessaire","Surveillance échographique de la dégénérescence"],"interactions":[],"pearls":["Évite la contrainte de l'anticoagulation à vie","Une fuite paraprothétique minime précoce est possible hors sepsis, à surveiller"],"src":"p. 205, 221, 240"},{"id":"233-tx-03","rank":"B","class":"TAVI (implantation valvulaire aortique par voie percutanée)","molecules":[],"context":"Alternative percutanée au RVA chirurgical dans le RA serré","indications":["RA serré inopérable ou à risque chirurgical élevé/intermédiaire, quel que soit l'âge","1re intention après 75 ans si voie fémorale possible"],"contraindications":["Décision hors Heart Team","Anatomie vasculaire ne permettant aucune voie d'abord adaptée"],"sideEffects":["Complications vasculaires liées à la voie d'abord fémorale, apicale ou alternative"],"monitoring":["Scanner cardiaque systématique avant la procédure (anneau, culot aortique, ostia coronaires, axes vasculaires)"],"interactions":[],"pearls":["Décision obligatoire en Heart Team tenant compte de l'âge, de la fragilité, des comorbidités et des souhaits du patient","Dépasse désormais la chirurgie en nombre de procédures en France"],"src":"p. 204-205"},{"id":"233-tx-04","rank":"B","class":"Valvuloplastie aortique au ballon","molecules":[],"context":"Dilatation de la valve aortique sans mise en place de prothèse","indications":["RA serré symptomatique devant une chirurgie non cardiaque urgente à risque","Geste d'attente avant un traitement définitif"],"contraindications":["Traitement de fond du RA (resténose précoce)"],"sideEffects":["Resténose rapide"],"monitoring":[],"interactions":[],"pearls":["Technique quasi abandonnée comme traitement définitif du fait de la resténose précoce"],"src":"p. 205"},{"id":"233-tx-05","rank":"B","class":"Plastie mitrale reconstructrice","molecules":[],"context":"Traitement chirurgical de référence de l'insuffisance mitrale primaire, notamment sur prolapsus","indications":["IM primaire grade III-IV symptomatique, plastie privilégiée quand elle est réalisable","IM primaire importante asymptomatique avec critère de retentissement"],"contraindications":["Valve trop remaniée rendant la réparation impossible (remplacement alors nécessaire)"],"sideEffects":["Léger risque de récidive de la fuite à long terme"],"monitoring":["Pas d'anticoagulation nécessaire au long cours"],"interactions":[],"pearls":["Respecte l'appareil sous-valvulaire : moins de dysfonction VG postopératoire, moindre morbimortalité et moindre risque d'endocardite que le remplacement","Réalisable même en cas de dysfonction VG, contrairement au remplacement en cas de FE < 30 %","Possible mais plus difficile dans les IM rhumatismales ou ischémiques"],"src":"p. 220, 222-223"},{"id":"233-tx-06","rank":"B","class":"Remplacement valvulaire mitral","molecules":[],"context":"Traitement de l'IM primaire quand la plastie n'est pas réalisable","indications":["IM primaire grade III-IV symptomatique avec valve trop remaniée pour une plastie","FEVG > 30 % requise"],"contraindications":["FE < 30 % : remplacement contre-indiqué (la plastie reste envisageable)"],"sideEffects":["Chute de FE de 10 à 15 % en postopératoire"],"monitoring":["Anticoagulation à vie si prothèse mécanique"],"interactions":[],"pearls":["Bioprothèse après 70 ans, prothèse mécanique avant 65 ans"],"src":"p. 221-222"},{"id":"233-tx-07","rank":"B","class":"Réparation percutanée bord à bord (clip mitral)","molecules":[],"context":"Traitement percutané de l'IM primaire ou secondaire, alternative à la chirurgie","indications":["IM primaire ou secondaire chez un patient à haut risque chirurgical ou avec contre-indication à la chirurgie","IM secondaire persistant sous traitement optimal de l'IC, si l'IC n'est pas trop avancée"],"contraindications":["Procédure non futile requise : ne pas proposer si l'espérance fonctionnelle est nulle"],"sideEffects":[],"monitoring":["Décision en clinique des valves et Heart Team pluridisciplinaire"],"interactions":[],"pearls":["Développement récent (recommandation ESC 2021) réservé aux centres expérimentés"],"src":"p. 220-221, 223"},{"id":"233-tx-08","rank":"A","class":"Traitement médical de l'insuffisance cardiaque dans l'IM secondaire","molecules":[],"context":"Première étape thérapeutique de l'IM secondaire (fonctionnelle), avant toute discussion invasive","indications":["IM secondaire (fonctionnelle) sur cardiopathie dilatée ou ischémique"],"contraindications":[],"sideEffects":[],"monitoring":["Réévaluation de la sévérité de la fuite après optimisation, la fuite variant avec la volémie"],"interactions":[],"pearls":["Resynchronisation cardiaque si QRS larges","Chirurgie ou clip discutés seulement en cas d'échec du traitement médical optimal"],"src":"p. 220, 223"},{"id":"233-tx-09","rank":"A","class":"Bêtabloquants dans l'insuffisance aortique","molecules":[],"context":"Seule classe médicamenteuse validée dans l'IA, réservée au contexte de dilatation aortique (Marfan)","indications":["Syndrome de Marfan (et plus largement dilatation aortique) : protection de l'aorte"],"contraindications":["IA sévère décompensée en insuffisance cardiaque : allongent la diastole et aggravent la fuite"],"sideEffects":["Aggravation hémodynamique de l'IA en décompensation"],"monitoring":[],"interactions":[],"pearls":["ARA2 en alternative seulement en cas d'intolérance aux bêtabloquants"],"src":"p. 239"},{"id":"233-tx-10","rank":"A","class":"Diurétiques et vasodilatateurs dans l'IA en attente de chirurgie","molecules":["IEC (non recommandés spécifiquement pour prévenir le remodelage)"],"context":"Traitement d'attente de l'IA sévère avec insuffisance cardiaque congestive, avant la chirurgie","indications":["IA sévère avec signes congestifs, dans l'attente du geste chirurgical"],"contraindications":["Ne doit jamais retarder l'indication chirurgicale même en cas d'amélioration clinique"],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Aucun médicament n'a démontré de bénéfice sur l'évolution naturelle de l'IA"],"src":"p. 239"},{"id":"233-tx-11","rank":"A","class":"Chirurgie de la racine aortique associée (Bentall, plastie conservatrice)","molecules":[],"context":"Traitement chirurgical de l'IA avec dilatation de l'aorte ascendante","indications":["IA avec dilatation aortique répondant aux seuils opératoires (55 mm, ou seuils abaissés si Marfan ou bicuspidie à risque)","Bicuspidie avec anévrisme de l'aorte ascendante associé"],"contraindications":[],"sideEffects":["Mortalité périopératoire 3-10 % quand associée à un geste sur l'aorte ou des pontages"],"monitoring":["Surveillance annuelle du diamètre aortique après chirurgie conservatrice"],"interactions":[],"pearls":["Bentall = tube prothétique avec réimplantation des artères coronaires","Plastie conservatrice (Tirone David, Yacoub) réservée aux chirurgiens entraînés, feuillets peu altérés"],"src":"p. 240-244"},{"id":"233-tx-12","rank":"A","class":"Antibioprophylaxie de l'endocardite infectieuse","molecules":[],"context":"Mesure de prévention chez tout patient porteur d'une valvulopathie","indications":["Antécédent d'endocardite infectieuse","Prothèse valvulaire","Cardiopathie cyanogène"],"contraindications":["Valve native sans antécédent d'EI : pas d'antibioprophylaxie systématique"],"sideEffects":[],"monitoring":["Hygiène cutanée et buccodentaire systématique","Examen dentaire deux fois par an"],"interactions":[],"pearls":["Prescrire une antibioprophylaxie systématique sur valve native est une erreur classique à éviter"],"src":"p. 222, 238-240"}],"strategies":[{"id":"233-strat-01","rank":"B","title":"Stratégie thérapeutique du rétrécissement aortique serré","content":"### Symptomatique\n\nTout RA serré **symptomatique** (dyspnée, angor ou syncope d'effort) relève d'un traitement, **pratiquement sans limite d'âge** si l'état général et l'espérance de vie le permettent.\n\n### Choix de la technique\n\n- Risque chirurgical **faible** → RVA chirurgical (prothèse mécanique si jeune, bioprothèse après 65 ans).\n- Risque **élevé ou intermédiaire**, ou âge **> 75 ans** avec voie fémorale possible → **TAVI** en 1re intention, décidé en **Heart Team**.\n- **Valvuloplastie au ballon** : geste d'attente seulement, avant une chirurgie non cardiaque urgente.\n\n### Asymptomatique\n\nSurveillance sauf si : épreuve d'effort anormale, **Vmax > 5 m/s**, aggravation rapide de la sténose ou **FEVG < 55 %** → traitement.\n\n### Cas particulier du bas débit\n\nDevant un RA à gradient bas (VES ≤ 35 mL/m²), une échographie sous faible dose de dobutamine distingue le RA serré vrai (traiter) de la pseudosténose (traiter comme une insuffisance cardiaque).\n\n### Bilan préopératoire\n\nSystématique avant tout geste : imagerie coronaire, aorte si bicuspidie, échodoppler des troncs supra-aortiques, foyers infectieux ORL et dentaires, comorbidités, avis gériatrique si patient âgé.","src":"p. 203-207"},{"id":"233-strat-02","rank":"B","title":"Stratégie thérapeutique de l'insuffisance mitrale primaire","content":"### Grade I-II\n\n**Non-intervention** : surveillance clinique et échographique régulière, prévention de l'endocardite par l'hygiène (pas d'antibioprophylaxie systématique).\n\n### Grade III-IV symptomatique\n\nIndication chirurgicale : **plastie reconstructrice privilégiée** dès que possible. Si la plastie est impossible, remplacement valvulaire envisageable seulement si **FE > 30 %** ; en dessous, le remplacement est **contre-indiqué** (traitement médical, clip si inopérable, ou transplantation chez le sujet jeune).\n\n### Grade III-IV asymptomatique\n\nChirurgie si au moins un signe de retentissement : **DTS VG > 40 mm** (avec rupture de cordage), **FEVG < 60 %**, **PAPs > 50 mmHg**, **fibrillation atriale** (même paroxystique) ou **AG > 60 mL/m²**. En l'absence de ces critères : surveillance clinique et échographique **tous les 6 mois**.\n\n### IM aiguë\n\n**Urgence chirurgicale** en cas de mauvaise tolérance hémodynamique (rupture de cordage ou de pilier, endocardite).","src":"p. 219-223"},{"id":"233-strat-03","rank":"B","title":"Stratégie thérapeutique de l'insuffisance mitrale secondaire","content":"### Première étape : traiter la cardiopathie sous-jacente\n\nL'IM secondaire (fonctionnelle) traduit une maladie du ventricule ou de l'anneau, pas de la valve. Le traitement débute par l'**optimisation du traitement médical de l'insuffisance cardiaque**, avec resynchronisation si les QRS sont larges.\n\n### Réévaluation\n\nLa sévérité de la fuite doit être réévaluée **après optimisation**, car elle varie avec la volémie (fuite « accordéon »). Le seuil de sévérité pour l'IM secondaire est plus bas que pour l'IM primaire : **SOR ≥ 30 mm²**.\n\n### En cas d'échec\n\nSi la fuite reste importante et l'insuffisance cardiaque n'est pas trop avancée, discuter un **clip percutané bord à bord** (technique privilégiée) ou une chirurgie mitrale, en **Heart Team**.","src":"p. 220, 223"},{"id":"233-strat-04","rank":"B","title":"Stratégie thérapeutique de l'insuffisance aortique chronique","content":"### Traitement médical\n\n**Aucun médicament** n'a démontré de bénéfice sur l'évolution de l'IA ; les IEC ne sont pas recommandés pour prévenir le remodelage. En cas d'IA sévère avec insuffisance cardiaque congestive : diurétiques et vasodilatateurs **dans l'attente de la chirurgie**, sans jamais retarder celle-ci. Les **bêtabloquants sont classiquement contre-indiqués** (allongent la diastole, aggravent la fuite), sauf dans le cadre du **Marfan** où ils protègent l'aorte (ARA2 si intolérance).\n\n### Indication chirurgicale\n\nFormelle si **IA sévère symptomatique**, ou asymptomatique avec **DTS > 50 mm (> 25 mm/m²)** ou **FEVG ≤ 50 %** ; à bas risque chirurgical, seuils abaissés à **DTS > 20 mm/m²** ou **FEVG ≤ 55 %**.\n\n### Indication portée sur l'aorte\n\nIndépendamment du grade de la fuite : aorte ascendante **≥ 55 mm**, ou seuils abaissés (**50 mm si Marfan**, **45 mm si Marfan à risque**, **50 mm si bicuspidie à risque**) ; remplacement de l'aorte associé si **≥ 45 mm** lors de la chirurgie pour IA sévère.\n\n### Technique\n\n**RVA isolé** si valve seule en cause ; **Bentall** (tube + réimplantation coronaire) ou **plastie conservatrice** (Tirone David, Yacoub) si dilatation aortique associée.\n\n### IA aiguë\n\nChirurgie **urgente si dissection** ; un peu différée si endocardite ou traumatisme selon la tolérance hémodynamique.","src":"p. 239-244"}]},"cases":[{"id":"233-case-01","title":"M. Vasseur, 71 ans, dyspnée d'effort et malaise au jardinage","rank":"A","summary":"Rétrécissement aortique dégénératif du sujet âgé, de la suspicion clinique au traitement.","difficulty":2,"timeline":["Présentation initiale","Examen clinique","Bilan de 1re intention","Confirmation échographique","Bilan préopératoire et décision","Suivi"],"steps":[{"id":"233-case-01-s01","phase":0,"narrative":"M. Vasseur, 71 ans, ancien menuisier, vous consulte car il s'essouffle depuis plusieurs mois en jardinant, un effort qu'il réalisait sans peine auparavant. La semaine dernière, en portant des sacs de terreau, il a ressenti un voile noir passager sans perte de connaissance complète. Il n'a pas d'antécédent cardiovasculaire connu en dehors d'une hypertension traitée.","question":{"type":"QRM","stem":"Quels éléments de l'interrogatoire recherchez-vous en priorité devant ce tableau ?","options":[{"t":"Une réduction progressive des activités que le patient aurait minimisée","ok":true,"why":"Les patients limitent souvent spontanément leurs efforts et se déclarent à tort asymptomatiques."},{"t":"La notion d'un souffle cardiaque déjà connu","ok":true,"why":"Un souffle systolique ancien oriente vers une valvulopathie évolutive."},{"t":"Un angor d'effort associé","ok":true,"why":"L'angor d'effort est un des trois maîtres symptômes du RA."},{"t":"Un contexte de piqûre de tique récente","ok":false,"why":"Sans rapport avec le tableau évoqué."},{"t":"Un voyage récent en zone tropicale","ok":false,"why":"Sans lien avec une suspicion de valvulopathie dégénérative."}],"explanation":"Devant une dyspnée d'effort et un malaise à l'effort chez un patient âgé, l'interrogatoire minutieux recherche les trois maîtres symptômes du RA (dyspnée, angor, syncope d'effort) et un souffle connu, en insistant sur la réduction insidieuse des activités."},"reveal":"Vous apprenez qu'il a effectivement réduit ses activités de jardinage depuis l'hiver et qu'un souffle avait été signalé « à surveiller » deux ans plus tôt sans consultation cardiologique depuis.","src":"p. 199"},{"id":"233-case-01-s02","phase":0,"narrative":"Le malaise du jardin ressemblait à une syncope brève sans prodrome marqué, survenue en plein effort, avec récupération rapide et sans morsure de langue ni perte d'urines.","question":{"type":"QROC","question":"Dans le contexte de ce patient, quel type de syncope ce malaise à l'effort évoque-t-il en priorité ?","answer":"Syncope d'effort (cardiaque, en rapport avec une valvulopathie obstructive telle qu'un rétrécissement aortique)","accept":["syncope d'effort","syncope à l'effort","syncope cardiaque d'effort"],"keywords":["syncope","effort","cardiaque"],"explanation":"Une syncope survenant en plein effort, chez un patient avec souffle systolique connu, est un signe d'alarme classique du RA serré et impose une évaluation cardiologique rapide."},"reveal":"Vous décidez de l'examiner sans délai plutôt que d'attendre un rendez-vous programmé, compte tenu de la valeur pronostique péjorative de ce symptôme.","src":"p. 199"},{"id":"233-case-01-s03","phase":1,"narrative":"À l'examen, la pression artérielle est à 128/78 mmHg, la fréquence cardiaque à 72/min régulière. Vous auscultez un souffle intense au 2e espace intercostal droit.","question":{"type":"QRM","stem":"Quelles caractéristiques du souffle, si elles sont présentes, sont en faveur d'un rétrécissement aortique ?","options":[{"t":"Souffle mésosystolique, rude et râpeux","ok":true,"why":"Caractère typique du souffle éjectionnel du RA."},{"t":"Irradiation vers les vaisseaux du cou","ok":true,"why":"Irradiation carotidienne classique du RA."},{"t":"Renforcement après une diastole longue","ok":true,"why":"Signe typique des souffles éjectionnels comme celui du RA."},{"t":"Irradiation vers l'aisselle en jet de vapeur","ok":false,"why":"C'est la description du souffle d'insuffisance mitrale, pas du RA."},{"t":"Abolition de B2","ok":true,"why":"L'abolition de B2 est un argument pour un RA serré calcifié."}],"explanation":"Le souffle du RA est mésosystolique, éjectionnel, rude, maximal au 2e EIC droit, irradiant aux carotides, renforcé après une diastole longue ; B2 peut être aboli si le RA est serré et calcifié."},"reveal":"L'auscultation retrouve exactement ce tableau : souffle 3/6 mésosystolique râpeux irradiant aux carotides, B2 difficilement perçu.","src":"p. 199"},{"id":"233-case-01-s04","phase":1,"narrative":"Vous complétez l'examen par la palpation du foyer aortique, patient penché en avant en fin d'expiration.","question":{"type":"QRU","stem":"Vous percevez un frémissement au foyer aortique. Que traduit ce signe ?","options":[{"t":"Un rétrécissement aortique hémodynamiquement significatif avec souffle d'intensité 4/6","ok":true,"why":"C'est la signification classique du frémissement palpatoire au foyer aortique."},{"t":"Une insuffisance mitrale sévère","ok":false,"why":"Le frémissement décrit ici est spécifique du foyer aortique et du RA."},{"t":"Une péricardite constrictive","ok":false,"why":"Sans rapport avec ce signe palpatoire."},{"t":"Un flutter atrial","ok":false,"why":"Trouble du rythme, pas un signe palpatoire valvulaire."},{"t":"Une hypertension pulmonaire isolée","ok":false,"why":"Le frémissement décrit n'est pas spécifique de l'HTP."}],"explanation":"Le frémissement palpatoire au foyer aortique, perçu patient penché en avant en fin d'expiration, traduit un RA hémodynamiquement significatif avec un souffle d'intensité 4/6."},"reveal":"Vous notez ce frémissement dans le dossier et décidez de prescrire un bilan de première intention.","src":"p. 199"},{"id":"233-case-01-s05","phase":2,"narrative":"Vous prescrivez un ECG et une radiographie thoracique avant d'adresser le patient au cardiologue.","question":{"type":"QRM","stem":"Quels résultats seraient évocateurs d'un RA serré sur ces examens de 1re intention ?","options":[{"t":"HVG de type surcharge systolique à l'ECG","ok":true,"why":"Signe classique du RA serré, bien que son absence n'élimine pas le diagnostic."},{"t":"Un ECG parfaitement normal élimine un RA serré","ok":false,"why":"L'absence d'HVG électrique n'exclut pas un RA serré."},{"t":"Cardiomégalie avec surcharge pulmonaire sur la radiographie si RA évolué","ok":true,"why":"Traduit un RA évolué avec dilatation du VG et insuffisance cardiaque gauche débutante."},{"t":"Troubles de conduction type BBG ou BAV du 1er degré","ok":true,"why":"Peuvent accompagner un RA serré évolué."},{"t":"Une radiographie normale élimine un RA","ok":false,"why":"La radiographie peut être strictement normale même en cas de RA."}],"explanation":"L'ECG et la radiographie sont des examens d'orientation, ni sensibles ni spécifiques : leur normalité n'élimine jamais un RA serré, seule l'échocardiographie tranche."},"reveal":"L'ECG montre une HVG avec T négatives asymétriques en précordiales gauches ; la radiographie est peu contributive, sans cardiomégalie franche.","src":"p. 200"},{"id":"233-case-01-s06","phase":2,"narrative":"Le cardiologue reçoit le patient une semaine plus tard.","question":{"type":"QROC","question":"Quel examen complémentaire est l'examen clé pour confirmer, quantifier et apprécier le retentissement de cette valvulopathie ?","answer":"L'échocardiographie doppler transthoracique (ETT)","accept":["ETT","échographie cardiaque transthoracique","échocardiographie transthoracique"],"keywords":["échocardiographie","doppler","transthoracique"],"explanation":"L'ETT est l'examen clé de toute valvulopathie : elle confirme le diagnostic, quantifie la sévérité et apprécie le retentissement ventriculaire et hémodynamique."},"reveal":"Une ETT est programmée en urgence relative compte tenu de la syncope d'effort récente.","src":"p. 200"},{"id":"233-case-01-s07","phase":3,"narrative":"L'ETT retrouve une valve aortique tricuspide, remaniée et calcifiée, une Vmax à 4,3 m/s, un gradient moyen à 45 mmHg et une surface aortique calculée à 0,8 cm².","question":{"type":"QRM","stem":"Que concluez-vous de ces résultats ?","options":[{"t":"Il s'agit d'un RA serré","ok":true,"why":"Vmax > 4 m/s, gradient moyen > 40 mmHg et surface < 1 cm² définissent tous les trois un RA serré."},{"t":"La surface est compatible avec un RA critique","ok":false,"why":"Le seuil de RA critique est ≤ 0,75 cm² ou < 0,4 cm²/m² ; 0,8 cm² est serré mais pas défini comme critique dans ces données."},{"t":"Ces valeurs suffisent, sans autre élément, à qualifier le RA de serré","ok":true,"why":"Les trois critères de sévérité (Vmax, gradient, surface) sont concordants et suffisants pour affirmer le caractère serré."},{"t":"Un tel tableau exclut la nécessité d'une évaluation du retentissement VG","ok":false,"why":"Le retentissement (hypertrophie, FEVG, autres valves, aorte) doit toujours être précisé."},{"t":"La surface valvulaire normale se situe entre 2 et 3,5 cm²","ok":true,"why":"Rappel exact de la surface aortique normale mentionnée dans le compte rendu."}],"explanation":"Les trois critères échographiques de sévérité concordent (Vmax > 4 m/s, gradient moyen > 40 mmHg, surface < 1 cm²) : ce RA est serré. Il reste à évaluer le retentissement ventriculaire et les autres valves."},"reveal":"Le compte rendu précise en outre une hypertrophie concentrique modérée du VG avec une FEVG à 58 %, sans dilatation ventriculaire.","src":"p. 201-202"},{"id":"233-case-01-s08","phase":3,"narrative":"Le patient rapporte désormais très clairement sa dyspnée et sa syncope d'effort lors de la consultation cardiologique, sans les minimiser cette fois.","question":{"type":"QRU","stem":"Compte tenu du caractère symptomatique de ce RA serré, quelle est l'attitude thérapeutique de principe ?","options":[{"t":"Indication de traitement (RVA ou TAVI), pratiquement sans limite d'âge si l'état général le permet","ok":true,"why":"Un RA serré symptomatique se traite systématiquement quel que soit l'âge, sauf pathologie limitant le pronostic à court terme."},{"t":"Simple surveillance annuelle sans traitement","ok":false,"why":"Réservée au RA serré asymptomatique sans critère de gravité."},{"t":"Traitement médical seul par diurétiques au long cours","ok":false,"why":"Aucun traitement médical ne remplace le traitement mécanique du RA serré symptomatique."},{"t":"Attendre l'aggravation avant toute décision","ok":false,"why":"L'apparition des symptômes marque une cassure évolutive de mauvais pronostic sans traitement."},{"t":"Récuser toute intervention en raison de l'âge de 71 ans","ok":false,"why":"L'âge seul n'est pas une contre-indication au traitement du RA serré symptomatique."}],"explanation":"Le RA serré symptomatique impose une indication thérapeutique quasi systématique, sans limite d'âge stricte, dès lors que l'état général le permet."},"reveal":"Le cardiologue programme un bilan préopératoire et une discussion en Heart Team.","src":"p. 206"},{"id":"233-case-01-s09","phase":4,"narrative":"Le bilan préopératoire est organisé : imagerie coronaire, échodoppler des troncs supra-aortiques, recherche de foyers infectieux.","question":{"type":"QROC","question":"Quel examen invasif ou non invasif est requis chez cet homme de 71 ans pour évaluer les artères coronaires avant l'intervention ?","answer":"Une coronarographie (ou un coroscanner) préopératoire","accept":["coronarographie","coroscanner"],"keywords":["coronarographie","préopératoire"],"explanation":"Une coronarographie préopératoire est requise chez tout homme de plus de 40 ans avant un geste sur le RA, y compris en l'absence de facteur de risque."},"reveal":"La coronarographie ne montre pas de lésion significative ; le bilan dentaire et ORL est également négatif.","src":"p. 203"},{"id":"233-case-01-s10","phase":4,"narrative":"La Heart Team discute du choix entre chirurgie conventionnelle et TAVI chez ce patient de 71 ans sans comorbidité majeure ni contre-indication chirurgicale, jugé à faible risque opératoire.","question":{"type":"OPEN","prompt":"Argumentez le choix thérapeutique le plus adapté à ce patient en tenant compte de son âge et de son risque opératoire, en citant les critères qui orientent vers la chirurgie ou vers le TAVI.","rubric":[{"point":"Cite l'âge < 75 ans et le faible risque opératoire comme argument en faveur de la chirurgie conventionnelle","weight":2},{"point":"Rappelle que le TAVI est recommandé en 1re intention après 75 ans, ou à tout âge si risque élevé/inopérable","weight":2},{"point":"Mentionne la décision obligatoire en Heart Team intégrant fragilité et comorbidités","weight":1}],"model":"Chez ce patient de 71 ans, sans comorbidité limitante et à faible risque chirurgical, la chirurgie conventionnelle (RVA) reste l'option de référence : le TAVI est recommandé en 1re intention seulement après 75 ans, ou à tout âge en cas de risque chirurgical élevé ou de contre-indication opératoire. La décision finale se prend en Heart Team, en tenant compte de la fragilité, des comorbidités et des souhaits du patient."},"reveal":"La Heart Team retient une indication de RVA chirurgical conventionnel.","src":"p. 205"},{"id":"233-case-01-s11","phase":5,"narrative":"Le choix du type de prothèse est discuté avec le patient avant l'intervention.","question":{"type":"QRM","stem":"Concernant le choix de la prothèse chez ce patient de 71 ans, quelles affirmations sont exactes ?","options":[{"t":"Une bioprothèse est envisageable, évitant une anticoagulation au long cours","ok":true,"why":"Le seuil habituel pour la bioprothèse est un âge supérieur à 65 ans."},{"t":"Une prothèse mécanique impose une anticoagulation par AVK à vie","ok":true,"why":"C'est l'inconvénient classique de la prothèse mécanique."},{"t":"La bioprothèse se dégrade en général en 10 à 15 ans","ok":true,"why":"Durabilité classique d'une bioprothèse, à discuter avec un patient de cet âge."},{"t":"La prothèse mécanique ne nécessite aucun suivi biologique","ok":false,"why":"Elle impose au contraire une surveillance stricte de l'anticoagulation."},{"t":"Le choix final revient exclusivement au chirurgien sans en discuter avec le patient","ok":false,"why":"Le choix se discute avec le patient, sauf contre-indication formelle à l'une des options."}],"explanation":"Chez un patient de 71 ans, la bioprothèse (pas d'anticoagulant, dégénérescence en 10-15 ans) est généralement privilégiée, mais le choix reste discuté avec le patient."},"reveal":"M. Vasseur opte pour une bioprothèse, souhaitant éviter la contrainte des anticoagulants.","src":"p. 205"},{"id":"233-case-01-s12","phase":5,"narrative":"Six mois après l'intervention, le patient revient en consultation de suivi, très amélioré sur le plan fonctionnel, et vous interroge sur la prévention des complications infectieuses avant ses prochains soins dentaires.","question":{"type":"QRM","stem":"Quelles mesures de prévention de l'endocardite infectieuse lui recommandez-vous ?","options":[{"t":"Une hygiène buccodentaire rigoureuse et un suivi dentaire régulier","ok":true,"why":"Mesure de prévention systématique chez tout porteur de valvulopathie ou de prothèse."},{"t":"Une antibioprophylaxie systématique avant tout soin dentaire","ok":true,"why":"Recommandée chez les porteurs de prothèse valvulaire, ce qui est désormais son cas."},{"t":"Aucune précaution particulière n'est nécessaire du fait de la bioprothèse","ok":false,"why":"Le port d'une prothèse valvulaire, biologique ou mécanique, justifie au contraire une antibioprophylaxie ciblée."},{"t":"Consulter en urgence en cas de fièvre inexpliquée","ok":true,"why":"Une fièvre chez un porteur de prothèse valvulaire doit toujours faire évoquer une endocardite."},{"t":"Un suivi cardiologique n'est plus utile après le remplacement valvulaire","ok":false,"why":"Un suivi régulier reste nécessaire pour surveiller la prothèse et dépister une dégénérescence future."}],"explanation":"Contrairement à la valve native, la prothèse valvulaire fait partie des situations justifiant une antibioprophylaxie de l'endocardite, en plus de l'hygiène buccodentaire et d'un suivi cardiologique régulier."},"reveal":"Vous lui remettez une carte de porteur de prothèse valvulaire et organisez le suivi annuel avec son cardiologue.","src":"p. 206-207, 238-240"}]},{"id":"233-case-02","title":"Mme Perrin, 55 ans, souffle connu et dyspnée d'aggravation brutale","rank":"A","summary":"Insuffisance mitrale par prolapsus valvulaire, surveillée puis compliquée d'une rupture de cordage.","difficulty":3,"timeline":["Découverte","Bilan initial et surveillance","Aggravation brutale","Prise en charge chirurgicale","Suivi"],"steps":[{"id":"233-case-02-s01","phase":0,"narrative":"Mme Perrin, 55 ans, sportive amatrice, est adressée pour un souffle systolique découvert lors d'une visite de médecine du travail. Elle ne rapporte aucun symptôme particulier, ni dyspnée ni palpitations.","question":{"type":"QRM","stem":"Quels éléments de l'auscultation orienteraient vers une insuffisance mitrale plutôt qu'un rétrécissement aortique ?","options":[{"t":"Souffle holosystolique maximal à la pointe","ok":true,"why":"Foyer typique de l'IM, à l'apex."},{"t":"Irradiation vers l'aisselle","ok":true,"why":"Irradiation classique du souffle d'IM, en jet de vapeur."},{"t":"Souffle renforcé après une diastole longue","ok":false,"why":"C'est une caractéristique du souffle éjectionnel du RA, pas de l'IM."},{"t":"Présence possible d'un clic mésosystolique","ok":true,"why":"Évocateur d'un prolapsus de la valve mitrale, avec mise en tension des cordages."},{"t":"Maximal au 2e espace intercostal droit","ok":false,"why":"C'est le foyer du souffle de RA, pas celui de l'IM."}],"explanation":"Le souffle d'IM est holosystolique, apexo-axillaire, en jet de vapeur, irradiant à l'aisselle, sans renforcement après une diastole longue ; un clic mésosystolique évoque un prolapsus."},"reveal":"Vous entendez effectivement un souffle 2/6 holosystolique à l'apex irradiant vers l'aisselle, avec un clic mésosystolique.","src":"p. 214-215"},{"id":"233-case-02-s02","phase":0,"narrative":"Vous complétez l'interrogatoire à la recherche d'antécédents personnels ou familiaux.","question":{"type":"QROC","question":"Quelle maladie du tissu conjonctif, associée à un prolapsus valvulaire mitral par dégénérescence myxoïde, recherchez-vous systématiquement à l'interrogatoire et à l'examen morphotype ?","answer":"La maladie de Barlow (dégénérescence myxoïde)","accept":["maladie de Barlow","syndrome de Barlow","dégénérescence myxoïde"],"keywords":["Barlow","myxoïde","prolapsus"],"explanation":"La dégénérescence myxoïde (maladie de Barlow) est une cause classique de prolapsus mitral, avec valves redondantes et hypermobiles exposées à la rupture de cordages."},"reveal":"L'interrogatoire ne retrouve pas de contexte évocateur particulier ; il s'agit probablement d'une forme isolée.","src":"p. 212"},{"id":"233-case-02-s03","phase":1,"narrative":"Une ETT est réalisée pour préciser le mécanisme et la sévérité de cette fuite.","question":{"type":"QRM","stem":"Quels résultats de l'ETT permettraient d'affirmer une IM primaire par prolapsus significative (grade III-IV) ?","options":[{"t":"Une surface de l'orifice régurgitant (SOR) supérieure ou égale à 40 mm²","ok":true,"why":"Correspond au grade IV (importante) selon la classification donnée."},{"t":"Un volume régurgité de 15 mL","ok":false,"why":"Ce volume correspond à une fuite minime (grade I)."},{"t":"Un bombement systolique d'un feuillet mitral dépassant le plan de l'anneau vers l'atrium gauche","ok":true,"why":"Définition échographique du prolapsus (Carpentier type II)."},{"t":"Une SOR de 35 mm², compatible avec un grade III (moyenne)","ok":true,"why":"Une SOR entre 30 et 39 mm² correspond au grade III, déjà considéré comme significatif."},{"t":"Une dilatation isolée du ventricule droit sans anomalie mitrale visible","ok":false,"why":"Sans rapport avec la quantification de l'IM par prolapsus mitral."}],"explanation":"L'IM primaire est quantifiée par la méthode PISA en 4 grades (SOR et volume régurgité) ; une IM significative correspond aux grades III (moyenne) ou IV (importante)."},"reveal":"Le compte rendu conclut à un prolapsus du feuillet postérieur avec IM grade II (SOR 25 mm²), sans dilatation ventriculaire gauche, FEVG à 65 %.","src":"p. 217-218"},{"id":"233-case-02-s04","phase":1,"narrative":"Compte tenu de ce grade modéré, vous discutez la conduite à tenir avec la patiente asymptomatique.","question":{"type":"QRU","stem":"Quelle est l'attitude adaptée devant cette IM primaire de grade II asymptomatique ?","options":[{"t":"Surveillance clinique et échographique régulière, sans indication chirurgicale","ok":true,"why":"Une IM de grade I-II ne relève pas d'un traitement invasif ; seule la surveillance est justifiée."},{"t":"Chirurgie de plastie mitrale immédiate","ok":false,"why":"Non indiquée pour un grade modéré asymptomatique sans critère de retentissement."},{"t":"Remplacement valvulaire d'emblée","ok":false,"why":"Non indiqué à ce stade, d'autant que la plastie serait de toute façon préférée si un geste devenait nécessaire."},{"t":"Antibioprophylaxie systématique avant tout soin dentaire","ok":false,"why":"Non recommandée sur valve native sans antécédent d'endocardite, prothèse ou cardiopathie cyanogène."},{"t":"Aucun suivi n'est nécessaire compte tenu de l'absence de symptôme","ok":false,"why":"Un suivi régulier reste nécessaire pour dépister une évolution de la fuite."}],"explanation":"Une IM primaire de grade I-II ne justifie qu'une surveillance clinique et échographique régulière ; l'antibioprophylaxie systématique sur valve native n'est pas recommandée."},"reveal":"Une surveillance annuelle est programmée. Mme Perrin reste asymptomatique pendant trois ans.","src":"p. 220, 222"},{"id":"233-case-02-s05","phase":2,"narrative":"Trois ans plus tard, Mme Perrin consulte en urgence : depuis 48 heures, elle présente une dyspnée brutale de repos avec orthopnée, sans fièvre ni douleur thoracique.","question":{"type":"QRM","stem":"Devant cette dyspnée aiguë chez une patiente porteuse d'un prolapsus mitral connu, quelles hypothèses évoquez-vous en priorité ?","options":[{"t":"Une rupture de cordage responsable d'une IM aiguë","ok":true,"why":"Complication classique du prolapsus mitral, pouvant survenir sans facteur déclenchant évident."},{"t":"Une endocardite infectieuse compliquant le prolapsus","ok":true,"why":"L'endocardite doit toujours être évoquée devant une aggravation d'une valvulopathie connue, même sans fièvre au premier plan."},{"t":"Une simple crise d'angoisse sans cause organique","ok":false,"why":"Un tel diagnostic ne doit pas être retenu sans avoir éliminé une complication cardiaque chez une patiente valvulaire connue."},{"t":"Une aggravation de la fuite mitrale par dysfonction du VG isolée sans rapport avec la valve","ok":false,"why":"Le tableau brutal chez une patiente aux antécédents de prolapsus oriente d'abord vers une complication mécanique de la valve elle-même."},{"t":"Un œdème aigu du poumon en rapport avec l'aggravation de l'IM","ok":true,"why":"Conséquence hémodynamique possible d'une IM devenue aiguë et sévère."}],"explanation":"Chez une patiente porteuse d'un prolapsus mitral connu, une dyspnée aiguë de repos évoque avant tout une rupture de cordage (IM aiguë) ou une endocardite, toutes deux pouvant conduire à un OAP."},"reveal":"L'auscultation retrouve un souffle systolique beaucoup plus intense qu'auparavant, avec des crépitants bilatéraux. Aucune fièvre n'est mesurée.","src":"p. 213-215"},{"id":"233-case-02-s06","phase":2,"narrative":"Vous demandez une échocardiographie en urgence.","question":{"type":"QROC","question":"Quel mécanisme échographique, complication classique du prolapsus mitral, recherchez-vous en priorité pour expliquer cette aggravation brutale ?","answer":"Une rupture de cordage","accept":["rupture de cordage","rupture des cordages"],"keywords":["rupture","cordage"],"explanation":"La rupture de cordage est une complication classique du prolapsus mitral, responsable d'une IM aiguë sévère et parfois d'un OAP unilatéral par fuite directionnelle."},"reveal":"L'ETT en urgence confirme une rupture de cordage du feuillet postérieur avec IM devenue massive, atrium gauche non dilaté, signes d'OAP.","src":"p. 213-214"},{"id":"233-case-02-s07","phase":2,"narrative":"L'échocardiographiste insiste sur l'absence de dilatation de l'atrium gauche malgré la fuite majeure.","question":{"type":"QRU","stem":"Comment expliquez-vous que cette IM aiguë soit si mal tolérée malgré une fuite comparable en volume à des IM chroniques bien supportées ?","options":[{"t":"L'atrium gauche non dilaté a une compliance normale insuffisante pour absorber le volume régurgité, d'où une élévation brutale des pressions","ok":true,"why":"C'est le mécanisme physiopathologique propre à l'IM aiguë, à la différence de l'IM chronique où l'AG a eu le temps de se dilater et de devenir compliant."},{"t":"Le ventricule gauche est toujours plus dilaté dans l'IM aiguë que dans l'IM chronique","ok":false,"why":"C'est l'inverse : le VG n'a pas eu le temps de se dilater dans l'IM aiguë."},{"t":"La FEVG est toujours effondrée d'emblée dans l'IM aiguë","ok":false,"why":"Non, la mauvaise tolérance tient surtout à l'élévation brutale des pressions en amont, pas à une chute immédiate de la FEVG."},{"t":"L'IM aiguë s'accompagne toujours d'une hypertrophie concentrique protectrice","ok":false,"why":"Il n'y a pas de temps pour un remodelage compensateur dans un tableau aigu."},{"t":"La compliance pulmonaire augmente brutalement dans l'IM aiguë","ok":false,"why":"C'est au contraire l'élévation brutale des pressions pulmonaires qui explique l'OAP."}],"explanation":"Dans l'IM aiguë, l'atrium gauche non dilaté et de compliance normale ne peut absorber le volume régurgité : les pressions s'élèvent brutalement en amont, provoquant un OAP, contrairement à l'IM chronique où l'AG dilaté et compliant amortit longtemps la surcharge."},"reveal":"Une prise en charge en urgence est décidée devant ce tableau hémodynamique mal toléré.","src":"p. 210-211"},{"id":"233-case-02-s08","phase":3,"narrative":"L'équipe médicochirurgicale évalue l'indication opératoire en urgence.","question":{"type":"QRU","stem":"Quelle est la conduite thérapeutique adaptée devant cette IM aiguë sur rupture de cordage mal tolérée ?","options":[{"t":"Chirurgie urgente","ok":true,"why":"L'IM aiguë mal tolérée est une urgence chirurgicale formelle."},{"t":"Traitement médical seul, chirurgie différée à distance","ok":false,"why":"Non adapté à une IM aiguë mal tolérée, qui impose un geste urgent."},{"t":"Simple surveillance en hospitalisation conventionnelle","ok":false,"why":"Insuffisant devant un tableau d'OAP sur IM aiguë sévère."},{"t":"Antibiothérapie probabiliste sans autre geste","ok":false,"why":"Il n'y a pas d'argument pour une endocardite dans ce contexte, et le tableau reste une urgence chirurgicale mécanique."},{"t":"Attendre un geste percutané en ambulatoire","ok":false,"why":"Le clip percutané n'est pas la solution d'une urgence chirurgicale vitale."}],"explanation":"Toute IM aiguë mal tolérée sur le plan hémodynamique constitue une urgence chirurgicale formelle."},"reveal":"La patiente est opérée en urgence dans les 24 heures.","src":"p. 214, 223"},{"id":"233-case-02-s09","phase":3,"narrative":"Au bloc, le chirurgien constate une atteinte localisée du feuillet postérieur avec cordages rompus, sans destruction valvulaire étendue.","question":{"type":"QRM","stem":"Quels arguments plaident pour privilégier une plastie reconstructrice plutôt qu'un remplacement valvulaire chez cette patiente ?","options":[{"t":"Une lésion localisée sur prolapsus est une situation typique où la plastie est réalisable","ok":true,"why":"Le prolapsus, notamment localisé, est l'indication de choix de la plastie reconstructrice."},{"t":"La plastie entraîne moins de dysfonction VG postopératoire que le remplacement","ok":true,"why":"Argument classique en faveur de la plastie, qui respecte l'appareil sous-valvulaire."},{"t":"La plastie expose à un moindre risque d'endocardite que le remplacement","ok":true,"why":"Avantage classique de la réparation valvulaire par rapport à une prothèse."},{"t":"La plastie impose systématiquement une anticoagulation à vie","ok":false,"why":"C'est l'inverse : la plastie ne nécessite pas d'anticoagulation au long cours."},{"t":"La plastie est impossible en cas de rupture de cordage","ok":false,"why":"Au contraire, la rupture de cordage sur prolapsus est une indication classique de plastie."}],"explanation":"La plastie reconstructrice est le traitement de référence des IM sur prolapsus, y compris compliquées de rupture de cordage, avec moins de dysfonction VG, moindre morbimortalité et moindre risque d'endocardite que le remplacement."},"reveal":"Une plastie mitrale est réalisée avec succès, sans nécessité de remplacement valvulaire.","src":"p. 220"},{"id":"233-case-02-s10","phase":4,"narrative":"Les suites opératoires sont simples. Mme Perrin sort à J7 avec un contrôle échographique satisfaisant montrant une plastie compétente.","question":{"type":"QRM","stem":"Quelles sont les modalités de surveillance et de prévention à mettre en place au décours ?","options":[{"t":"Pas d'anticoagulation au long cours nécessaire après une plastie","ok":true,"why":"Contrairement au remplacement par prothèse mécanique, la plastie ne requiert pas d'anticoagulation à vie."},{"t":"Surveillance échographique à distance pour dépister une récidive de la fuite","ok":true,"why":"Un léger risque de récidive à long terme justifie un suivi échographique."},{"t":"Hygiène buccodentaire et suivi dentaire réguliers","ok":true,"why":"Mesure de prévention de l'endocardite recommandée chez tout patient valvulaire opéré."},{"t":"Antibioprophylaxie systématique avant tout soin dentaire","ok":false,"why":"Non indiquée après une plastie sur valve native sans antécédent d'endocardite."},{"t":"Aucun suivi cardiologique n'est plus nécessaire après la chirurgie","ok":false,"why":"Un suivi cardiologique régulier reste indispensable après une chirurgie valvulaire."}],"explanation":"Après une plastie mitrale, ni anticoagulation ni antibioprophylaxie systématique ne sont nécessaires, mais l'hygiène buccodentaire, le suivi dentaire et le suivi cardiologique régulier restent recommandés."},"reveal":"Un suivi annuel est programmé ; la patiente reprend une activité sportive de loisir progressive.","src":"p. 220, 238-240"}]},{"id":"233-case-03","title":"M. Duchêne, 42 ans, souffle diastolique découvert lors d'un bilan sportif","rank":"B","summary":"Insuffisance aortique sur bicuspidie, du diagnostic étiologique à l'indication chirurgicale portée sur l'aorte.","difficulty":3,"timeline":["Découverte","Bilan étiologique et quantification","Surveillance","Aggravation et indication opératoire","Suivi postopératoire"],"steps":[{"id":"233-case-03-s01","phase":0,"narrative":"M. Duchêne, 42 ans, cycliste amateur, consulte pour la délivrance d'un certificat de non contre-indication au sport. Il est totalement asymptomatique. L'auscultation retrouve un souffle diastolique doux au bord gauche du sternum, mieux perçu penché en avant en expiration bloquée, ainsi qu'un souffle systolique éjectionnel discret associé.","question":{"type":"QRM","stem":"Quelles hypothèses évoquez-vous devant cette auscultation ?","options":[{"t":"Une insuffisance aortique","ok":true,"why":"Le souffle diastolique décrit, mieux entendu penché en avant, est caractéristique d'une IA."},{"t":"Un souffle systolique d'accompagnement par hyperdébit dans la chambre de chasse","ok":true,"why":"Fréquemment associé à l'IA, sans signifier une sténose aortique associée."},{"t":"Une maladie aortique (RA + IA)","ok":false,"why":"Rien n'indique à ce stade un obstacle éjectionnel associé ; le souffle systolique décrit est un souffle d'hyperdébit, pas de sténose."},{"t":"Un rétrécissement mitral isolé","ok":false,"why":"Le souffle décrit n'est pas localisé à l'apex et ne correspond pas à ce tableau."},{"t":"Un frottement péricardique","ok":false,"why":"Le caractère et la localisation du souffle ne correspondent pas à un frottement péricardique."}],"explanation":"Un souffle diastolique du bord gauche du sternum, mieux perçu en position penchée en avant, associé à un souffle systolique d'accompagnement (hyperdébit), est le tableau typique d'une insuffisance aortique."},"reveal":"Vous complétez l'examen par la recherche de signes périphériques d'hyperpulsatilité, absents pour l'instant.","src":"p. 232-233"},{"id":"233-case-03-s02","phase":0,"narrative":"La pression artérielle mesurée est à 142/58 mmHg.","question":{"type":"QROC","question":"Comment appelle-t-on l'élargissement de la différentielle tensionnelle avec pression diastolique abaissée que l'on retrouve ici, en faveur d'une IA significative ?","answer":"Hyperpulsatilité artérielle (élargissement de la pression pulsée)","accept":["hyperpulsatilité artérielle","élargissement de la pression pulsée","pression pulsée élargie"],"keywords":["hyperpulsatilité","pression","pulsée"],"explanation":"L'élargissement de la différentielle avec PAD abaissée traduit une hyperpulsatilité artérielle, signe périphérique classique d'une insuffisance aortique significative."},"reveal":"Vous décidez de prescrire une échocardiographie avant toute décision d'aptitude sportive.","src":"p. 233"},{"id":"233-case-03-s03","phase":1,"narrative":"En attendant l'échocardiographie, vous réalisez un ECG et une radiographie thoracique.","question":{"type":"QRM","stem":"Quelles propositions concernant l'ECG et la radiographie thoracique dans l'IA sont exactes ?","options":[{"t":"L'ECG peut être normal malgré une IA significative","ok":true,"why":"Un ECG normal en rythme sinusal est fréquent, en particulier dans les IA peu évoluées."},{"t":"Une hypertrophie ventriculaire gauche de type diastolique (R amples, T positives) peut être observée","ok":true,"why":"Anomalie électrique classique de l'IA chronique."},{"t":"Ni l'ECG ni la radiographie ne permettent d'affirmer le diagnostic d'IA","ok":true,"why":"Seule l'échocardiographie confirme le diagnostic ; ces examens ne sont qu'orientatifs."},{"t":"La radiographie thoracique est toujours pathologique dans l'IA, même minime","ok":false,"why":"Une petite IA peut s'accompagner d'une radiographie strictement normale."},{"t":"La présence d'une fibrillation atriale serait un facteur de bon pronostic","ok":false,"why":"La FA ou les extrasystoles ventriculaires sont au contraire des éléments de mauvais pronostic dans l'IA."}],"explanation":"L'ECG et la radiographie ne permettent pas d'affirmer le diagnostic d'IA, qui repose sur l'échocardiographie ; ils peuvent cependant montrer une HVG de type diastolique ou rester normaux."},"reveal":"L'ECG est en rythme sinusal avec quelques signes d'hypertrophie ventriculaire gauche diastolique ; la radiographie est sans anomalie notable.","src":"p. 235"},{"id":"233-case-03-s04","phase":1,"narrative":"L'ETT confirme un reflux diastolique aorte-VG en doppler couleur. La valve aortique apparaît constituée de deux cusps.","question":{"type":"QRM","stem":"Devant cette bicuspidie aortique découverte à l'occasion de cette IA, quelles mesures complémentaires sont indiquées ?","options":[{"t":"Mesurer précisément les diamètres de l'aorte ascendante","ok":true,"why":"La bicuspidie s'associe à une dilatation de l'aorte ascendante dans environ 50 % des cas."},{"t":"Proposer un dépistage échographique chez les apparentés du 1er degré","ok":true,"why":"La bicuspidie justifie un dépistage familial, avec une récurrence d'environ 10 %."},{"t":"Rechercher une coarctation associée","ok":true,"why":"Association plus rare mais classique à la bicuspidie, à ne pas négliger."},{"t":"Aucune surveillance particulière de l'aorte n'est nécessaire chez un patient jeune","ok":false,"why":"Au contraire, la surveillance de l'aorte est indispensable en cas de bicuspidie, quel que soit l'âge."},{"t":"La bicuspidie est une anomalie acquise du sujet âgé","ok":false,"why":"Il s'agit d'une anomalie congénitale, présente dès la naissance."}],"explanation":"La bicuspidie aortique impose la mesure systématique de l'aorte ascendante (dilatée dans environ 50 % des cas), la recherche d'une coarctation et un dépistage échographique des apparentés du 1er degré."},"reveal":"L'aorte ascendante mesure 42 mm, sans coarctation associée. Vous organisez un dépistage familial.","src":"p. 235-238"},{"id":"233-case-03-s05","phase":1,"narrative":"Le compte rendu échographique quantifie la fuite : vena contracta large, hyperdébit dans la chambre de chasse à 5,2 L/min/m², volume régurgité estimé à 65 mL.","question":{"type":"QRU","stem":"Selon la classification en 4 grades de l'IA, à quel grade correspond ce volume régurgité ?","options":[{"t":"Grade 4 (sévère)","ok":true,"why":"Un volume régurgité ≥ 60 mL correspond au grade 4 (sévère) de la classification."},{"t":"Grade 1 (minime)","ok":false,"why":"Le grade 1 correspond à un volume régurgité < 30 mL."},{"t":"Grade 2 (minime à modérée)","ok":false,"why":"Le grade 2 correspond à 30-44 mL."},{"t":"Grade 3 (modérée à moyenne)","ok":false,"why":"Le grade 3 correspond à 45-59 mL."},{"t":"La classification en grades ne s'applique pas à l'IA","ok":false,"why":"La classification en 4 grades s'applique bien à l'IA, comme à l'IM."}],"explanation":"Un volume régurgité ≥ 60 mL, associé ici à un hyperdébit > 4 L/min/m², correspond à une IA sévère de grade 4."},"reveal":"Le VG reste de taille normale avec une FEVG à 62 %.","src":"p. 233-234"},{"id":"233-case-03-s06","phase":2,"narrative":"Devant cette IA sévère mais sans dilatation VG ni baisse de FEVG, et une aorte à 42 mm ne justifiant pas de geste immédiat, vous organisez un programme de surveillance.","question":{"type":"QRM","stem":"Quelles modalités de surveillance mettez-vous en place chez ce patient asymptomatique ?","options":[{"t":"Clinique et ETT une à deux fois par an, compte tenu de la sévérité de la fuite","ok":true,"why":"Rythme recommandé pour une fuite sévère, même asymptomatique."},{"t":"Surveillance de l'aorte ascendante en imagerie, au moins annuelle","ok":true,"why":"La dilatation aortique associée à la bicuspidie impose un suivi régulier du diamètre."},{"t":"Suivi dentaire biannuel","ok":true,"why":"Mesure de prévention de l'endocardite recommandée chez tout patient valvulaire."},{"t":"Prescription de bêtabloquants au long cours dès maintenant","ok":false,"why":"Aucun bénéfice médicamenteux démontré dans l'IA en dehors du contexte de Marfan ; les bêtabloquants ne sont pas systématiques ici."},{"t":"Contre-indication formelle et définitive au sport de loisir","ok":false,"why":"Seul le sport de compétition est contre-indiqué en cas d'IA sévère ; le sport de loisir d'endurance modéré reste encouragé."}],"explanation":"Une IA sévère asymptomatique sans critère opératoire justifie une surveillance rapprochée (clinique, ETT 1-2 fois/an), un suivi de l'aorte, un suivi dentaire biannuel ; le sport de loisir modéré reste autorisé, seul le sport de compétition étant contre-indiqué."},"reveal":"Vous délivrez une contre-indication au cyclisme de compétition mais autorisez la pratique de loisir, et programmez le suivi.","src":"p. 239"},{"id":"233-case-03-s07","phase":3,"narrative":"Dix-huit mois plus tard, M. Duchêne rapporte une dyspnée d'effort nouvelle en montant les escaliers, absente auparavant.","question":{"type":"QRU","stem":"Que traduit l'apparition de ce symptôme chez ce patient porteur d'une IA sévère suivie ?","options":[{"t":"Un tournant évolutif qui impose une indication chirurgicale formelle","ok":true,"why":"L'IA sévère devenue symptomatique relève d'une indication chirurgicale formelle, sans attendre d'autre critère."},{"t":"Un symptôme sans valeur, à réévaluer dans un an","ok":false,"why":"Les symptômes marquent au contraire un tournant pronostique majeur dans l'IA sévère."},{"t":"Une indication à renforcer uniquement le traitement diurétique au long cours","ok":false,"why":"Le traitement médical n'est qu'un pont vers la chirurgie, jamais une alternative à celle-ci."},{"t":"Un critère insuffisant tant que la FEVG reste normale","ok":false,"why":"La seule apparition de symptômes suffit à poser l'indication opératoire dans l'IA sévère, indépendamment de la FEVG."},{"t":"Un signe évoquant surtout un problème pulmonaire sans rapport avec la valve","ok":false,"why":"Chez un patient valvulaire suivi pour IA sévère, ce symptôme nouveau doit d'abord être rattaché à la valvulopathie."}],"explanation":"L'apparition de symptômes chez un patient porteur d'une IA sévère constitue une indication chirurgicale formelle, indépendamment des autres critères échographiques."},"reveal":"Une nouvelle ETT confirme la persistance d'une IA sévère avec un VG désormais discrètement dilaté et une aorte ascendante à 47 mm.","src":"p. 240"},{"id":"233-case-03-s08","phase":3,"narrative":"L'équipe chirurgicale évalue la nécessité d'un geste combiné sur la valve et sur l'aorte.","question":{"type":"QROC","question":"Quel type d'intervention associant remplacement valvulaire aortique et remplacement de l'aorte ascendante avec réimplantation des artères coronaires est classiquement proposé dans cette situation ?","answer":"Une intervention de Bentall","accept":["Bentall","intervention de Bentall","chirurgie de Bentall"],"keywords":["Bentall"],"explanation":"L'intervention de Bentall associe un remplacement valvulaire aortique à un tube prothétique remplaçant l'aorte ascendante avec réimplantation des ostia coronaires, indiquée en cas d'IA avec dilatation significative de la racine aortique."},"reveal":"Une intervention de Bentall est programmée, avec RVA mécanique compte tenu de son âge.","src":"p. 240-244"},{"id":"233-case-03-s09","phase":4,"narrative":"L'intervention se déroule sans complication. À J8, M. Duchêne est revu en consultation postopératoire.","question":{"type":"QRM","stem":"Quelles recommandations lui donnez-vous pour le suivi à long terme ?","options":[{"t":"Anticoagulation par AVK à vie compte tenu de la prothèse mécanique","ok":true,"why":"Conséquence obligatoire du choix d'une prothèse mécanique."},{"t":"Antibioprophylaxie de l'endocardite avant les soins dentaires, désormais indiquée","ok":true,"why":"Le port d'une prothèse valvulaire fait partie des indications formelles d'antibioprophylaxie."},{"t":"Suivi régulier du reste de l'aorte thoracique après remplacement partiel","ok":true,"why":"Un suivi d'imagerie reste utile même après remplacement de la portion la plus dilatée."},{"t":"Reprise du sport de compétition sans restriction dès la cicatrisation","ok":false,"why":"Le sport de compétition reste à rediscuter au cas par cas après une chirurgie de l'aorte et sous anticoagulants ; il n'est pas repris sans restriction."},{"t":"Aucune surveillance cardiologique n'est plus nécessaire après ce type de chirurgie","ok":false,"why":"Un suivi cardiologique régulier, y compris de la prothèse, reste indispensable au long cours."}],"explanation":"Après une chirurgie de Bentall avec prothèse mécanique, le suivi associe anticoagulation à vie, antibioprophylaxie de l'endocardite, surveillance du reste de l'aorte et suivi cardiologique régulier ; le sport de compétition n'est pas repris sans réévaluation prudente."},"reveal":"M. Duchêne reprend une activité de loisir modérée sous surveillance rapprochée de son traitement anticoagulant.","src":"p. 238-244"}]}],"ecg":{"data":[{"id":"233-ecg-01","title":"HVG de surcharge systolique (rétrécissement aortique serré)","rank":"B","objective":"233-obj-06","ecg":{"rhythm":"sinus","rate":75,"qrs":{"dur":0.1,"lvh":true},"t":{"inverted":["I","aVL","V5","V6"],"amp":-0.3},"notes":"Hypertrophie ventriculaire gauche de type surcharge systolique : ondes T négatives et asymétriques dans les précordiales gauches."},"findings":["Hypertrophie ventriculaire gauche électrique de type surcharge systolique","Ondes T négatives et asymétriques dans les précordiales gauches (V5-V6, I, aVL)","L'absence d'HVG électrique n'élimine pas un rétrécissement aortique (RA) serré : la corrélation est médiocre","Peut s'associer à une hypertrophie atriale gauche","Troubles de conduction possibles : bloc de branche gauche, bloc atrioventriculaire du 1er degré","Fibrillation atriale possible dans les formes évoluées, mais moins fréquente que dans les valvulopathies mitrales"],"diagnosis":"Hypertrophie ventriculaire gauche de type surcharge systolique, évocatrice d'un rétrécissement aortique serré","teaching":"L'ECG reste longtemps normal dans le RA peu évolué. Dans le RA serré, il montre le plus souvent une HVG dite « de surcharge systolique » : ondes T négatives et asymétriques dans les précordiales gauches. Ce pattern s'oppose à celui de l'insuffisance aortique (HVG « de surcharge diastolique » : ondes R amples avec T positives). Un ECG normal n'exclut jamais un RA serré : seule l'échocardiographie doppler confirme et quantifie la sténose. À rechercher aussi : hypertrophie atriale gauche, troubles de conduction (BBG, BAV 1) et fibrillation atriale, plus rare que dans les atteintes mitrales.","quiz":{"stem":"Chez un patient porteur d'un souffle systolique éjectionnel râpeux au foyer aortique, cet ECG oriente en premier lieu vers :","options":["Un rétrécissement aortique serré avec hypertrophie ventriculaire gauche de surcharge systolique","Une insuffisance aortique avec hypertrophie ventriculaire gauche de surcharge diastolique","Une insuffisance mitrale avec hypertrophie atriale gauche isolée","Un rythme normal excluant toute valvulopathie serrée"],"correct":0},"src":"p. 200"},{"id":"233-ecg-02","title":"Hypertrophie atriale gauche (insuffisance mitrale chronique)","rank":"B","objective":"233-obj-06","ecg":{"rhythm":"sinus","rate":75,"p":{"present":true,"amp":0.12,"dur":0.13,"biphasicV1":true,"wide":true},"notes":"Onde P élargie et souvent bifide en dérivations inférieures, composante terminale négative en V1 : hypertrophie atriale gauche liée à la dilatation de l'oreillette gauche de l'IM chronique."},"findings":["Onde P élargie (durée augmentée), parfois bifide, dans les dérivations inférieures","Composante négative de l'onde P en V1 traduisant la dilatation de l'oreillette gauche","L'ECG reste longtemps normal dans l'IM : ces anomalies apparaissent aux stades évolués","Peut s'associer à une hypertrophie ventriculaire gauche","Une hypertrophie ventriculaire droite peut s'y ajouter en cas d'HTP sévère"],"diagnosis":"Hypertrophie atriale gauche au cours d'une insuffisance mitrale chronique","teaching":"Dans l'IM, l'ECG et la radiographie n'apportent pas de signe spécifique et restent longtemps normaux. Aux stades évolués apparaissent : hypertrophie atriale gauche, hypertrophie ventriculaire gauche, fibrillation atriale, et hypertrophie ventriculaire droite si l'HTP est sévère. Ces anomalies traduisent le retentissement en amont (dilatation de l'oreillette gauche) et en aval (dilatation du VG) de la fuite mitrale, mais le diagnostic positif, étiologique et de sévérité repose sur l'échocardiographie.","quiz":{"stem":"Quelle anomalie électrique traduit la dilatation de l'oreillette gauche au cours d'une insuffisance mitrale évoluée ?","options":["Hypertrophie atriale gauche (onde P élargie, bifide, composante négative en V1)","Onde delta avec PR court","Sus-décalage du segment ST en dérivations inférieures","Bloc atrioventriculaire du 3e degré"],"correct":0},"src":"p. 215"},{"id":"233-ecg-03","title":"Fibrillation atriale compliquant une insuffisance mitrale","rank":"B","objective":"233-obj-07","ecg":{"rhythm":"af","irregular":true,"rate":100,"p":{"present":false}},"findings":["Absence d'ondes P organisées, trémulations irrégulières de la ligne de base","Espaces RR totalement irréguliers","Complication fréquente de la dilatation de l'oreillette gauche liée à l'IM chronique","Favorise la décompensation cardiaque et impose le plus souvent une anticoagulation"],"diagnosis":"Fibrillation atriale","teaching":"La fibrillation atriale (ou le flutter) fait partie des anomalies observables à l'ECG dans l'IM évoluée, favorisée par la dilatation de l'oreillette gauche. Elle peut précipiter une décompensation cardiaque et justifie, chez l'IM primaire importante asymptomatique, une chirurgie précoce (même paroxystique). Une anticoagulation est nécessaire si elle est présente.","quiz":{"stem":"Chez un patient porteur d'une insuffisance mitrale chronique avec dilatation de l'oreillette gauche, cet ECG montre :","options":["Une fibrillation atriale","Un bloc de branche gauche complet","Une tachycardie ventriculaire","Un rythme sinusal régulier"],"correct":0},"src":"p. 215, 219"},{"id":"233-ecg-04","title":"HVG de surcharge diastolique (insuffisance aortique chronique)","rank":"B","objective":"233-obj-06","ecg":{"rhythm":"sinus","rate":75,"qrs":{"dur":0.09,"lvh":true,"pathologicR":["V5","V6"]},"t":{"inverted":[],"amp":0.5}},"findings":["Ondes R très amples dans les précordiales gauches (V5-V6)","Ondes T positives concordantes : hypertrophie ventriculaire gauche de type diastolique","Rythme le plus souvent sinusal","Parfois aspect systolique associé : discret sous-décalage de ST et inversion des ondes T en précordiales gauches","La survenue d'une fibrillation atriale ou d'extrasystoles ventriculaires est un élément de mauvais pronostic"],"diagnosis":"Hypertrophie ventriculaire gauche de type diastolique, évocatrice d'une insuffisance aortique chronique","teaching":"Dans l'IA, l'ECG peut être normal. Le rythme est en général sinusal ; la survenue d'une FA ou d'ESV est de mauvais pronostic. L'aspect typique est une HVG de type diastolique (ondes R amples en précordiales gauches avec ondes T positives), différente de l'HVG systolique du RA (ondes T négatives asymétriques). Un aspect systolique avec sous-décalage de ST et inversion des ondes T en précordiales gauches peut s'observer aux stades plus évolués.","quiz":{"stem":"Un patient présente un souffle diastolique du foyer aortique irradiant le long du bord gauche du sternum et cet ECG. Quel est le diagnostic le plus probable ?","options":["Insuffisance aortique chronique avec HVG de type diastolique","Rétrécissement aortique serré avec HVG de type systolique","Péricardite chronique constrictive","Cardiomyopathie hypertrophique obstructive"],"correct":0},"src":"p. 233"}],"method":""},"echo":{"data":[{"id":"233-echo-01","title":"Bicuspidie aortique en échocardiographie transœsophagienne","rank":"A","objective":"233-obj-02","schematic":"psax","findings":["Valve aortique à 2 cusps (sigmoïdes) au lieu de 3, visible en coupe petit axe et en 3D","Étiologie congénitale la plus fréquente de rétrécissement aortique entre 30 et 65 ans","L'ETO confirme la bicuspidie et aide à mieux évaluer la taille de l'aorte","Impose de mesurer l'aorte ascendante (anévrisme associé fréquent) et de dépister les apparentés du 1er degré"],"measures":[],"description":"Vue petit axe transœsophagienne montrant une valve aortique bicuspide : au lieu des trois cusps normaux (antérodroite, antérogauche, non coronaire), on identifie deux feuillets, parfois avec un raphé de fusion (forme la plus fréquente). Cette anomalie congénitale, présente chez 1 à 2 % de la population, est la première cause de rétrécissement aortique chez le sujet de moins de 65-70 ans et s'associe souvent à un anévrisme de l'aorte ascendante qu'il faut systématiquement rechercher.","quiz":{"stem":"Quelle est la principale complication associée à retenir devant la découverte échographique d'une bicuspidie aortique ?","options":["Un anévrisme de l'aorte ascendante à rechercher systématiquement","Une communication interventriculaire","Une thrombose de l'oreillette gauche","Un canal artériel persistant"],"correct":0},"src":"p. 203"},{"id":"233-echo-02","title":"Valve aortique calcifiée et doppler transaortique du rétrécissement aortique","rank":"A","objective":"233-obj-04","schematic":"doppler","findings":["Valve remaniée, épaissie et calcifiée, avec ouverture réduite en 2D (coupes petit et grand axe)","Vitesse maximale transaortique augmentée en doppler continu","Le doppler pulsé en amont de la valve reflète le débit cardiaque, utile au calcul du gradient","Le grand axe permet aussi de mesurer le diamètre de l'anneau pour calculer la surface fonctionnelle"],"measures":[{"label":"Vitesse maximale (Vmax) transaortique","severe":"> 4 m/s (normale ≈ 1 m/s)","rank":"A"},{"label":"Gradient moyen VG-aorte","severe":"> 40 mmHg (normal 2-5 mmHg)","rank":"A"},{"label":"Surface aortique (planimétrie/continuité)","severe":"< 1 cm² ou < 0,6 cm²/m² (critique si ≤ 0,75 cm² ou < 0,4 cm²/m²)","rank":"A"}],"description":"L'échocardiographie doppler transthoracique est l'examen clé du rétrécissement aortique (RA) : elle confirme la valve remaniée et calcifiée en 2D, puis quantifie la sténose en combinant la vitesse maximale au doppler continu, le gradient moyen VG-aorte calculé par intégration des vitesses, et la surface aortique (par l'équation de continuité, utilisant le diamètre de l'anneau mesuré en grand axe). Ces trois paramètres, dépendants du débit, définissent le RA serré.","quiz":{"stem":"Quel seuil de vitesse maximale transaortique en doppler continu est en général associé à un rétrécissement aortique serré ?","options":["> 4 m/s","> 1 m/s","> 2 m/s","> 6 m/s"],"correct":0},"src":"p. 201-202"},{"id":"233-echo-03","title":"Prolapsus du feuillet postérieur avec rupture de cordage en incidence parasternale grand axe","rank":"A","objective":"233-obj-04","schematic":"plax","findings":["Feuillet postérieur dont l'extrémité passe en arrière du plan de l'anneau mitral en systole (prolapsus)","Aspect évocateur de rupture de cordage associée","Mécanisme de type II de la classification de Carpentier (jeu valvulaire exagéré)","Cause la plus fréquente des fuites mitrales sévères (dégénérescence myxoïde ou fibroélastique)"],"measures":[],"description":"Coupe parasternale grand axe en échocardiographie bidimensionnelle montrant un prolapsus du feuillet mitral postérieur avec probable rupture de cordage : le bord libre du feuillet dépasse le plan de l'anneau vers l'oreillette gauche en systole. C'est le mécanisme de l'IM dystrophique (Carpentier type II), première cause de fuite mitrale sévère, par dégénérescence myxoïde (maladie de Barlow) ou fibroélastique.","quiz":{"stem":"Le prolapsus valvulaire mitral avec rupture de cordage correspond à quel type de la classification de Carpentier ?","options":["Type II (jeu valvulaire exagéré)","Type I (jeu valvulaire normal)","Type IIIa (restriction systolo-diastolique)","Type IIIb (restriction systolique isolée)"],"correct":0},"src":"p. 216"},{"id":"233-echo-04","title":"Jet d'insuffisance mitrale excentré en doppler couleur","rank":"A","objective":"233-obj-04","schematic":"doppler","findings":["Jet de régurgitation mitrale visible en doppler couleur, dirigé vers la partie postérieure de l'oreillette gauche","Excentration du jet en rapport avec le prolapsus du feuillet postérieur","Signal holosystolique en arrière du plancher mitral, signe positif du diagnostic d'IM","La sévérité se quantifie par la méthode PISA (surface de l'orifice régurgitant, SOR)"],"measures":[{"label":"SOR (IM primaire, grade IV importante)","severe":"≥ 40 mm² (volume régurgité ≥ 60 mL)","rank":"A"}],"description":"En doppler couleur, incidence parasternale grand axe, le jet de régurgitation mitrale apparaît excentré vers la partie postérieure de l'oreillette gauche, en rapport avec le prolapsus du feuillet postérieur (le jet est dirigé à l'opposé du feuillet atteint). La quantification de la fuite repose sur la méthode PISA, qui permet de calculer la surface de l'orifice régurgitant et de classer l'IM en quatre grades croissants ; on parle d'IM significative à partir du grade moyen.","quiz":{"stem":"Dans un prolapsus du feuillet mitral postérieur, comment est le plus souvent orienté le jet de régurgitation en doppler couleur ?","options":["Excentré vers la partie postérieure de l'oreillette gauche","Centré, sans excentration","Dirigé vers la chambre de chasse du ventricule gauche","Toujours indétectable en doppler couleur"],"correct":0},"src":"p. 217"},{"id":"233-echo-05","title":"Végétation mitrale en échocardiographie transœsophagienne (endocardite)","rank":"A","objective":"233-obj-04","schematic":"a4c","findings":["Végétation visible sur la face atriale de la valve mitrale","L'ETO est l'examen obligatoire pour le diagnostic d'IM sur endocardite : elle détecte des végétations parfois trop fines pour l'ETT","L'ETO précise aussi les ruptures partielles de cordages et les segments valvulaires atteints, utiles au chirurgien","Plus de la moitié des endocardites mitrales surviennent sur une valve déjà lésée (prolapsus, autre IM)"],"measures":[],"description":"Échocardiographie transœsophagienne 3D depuis l'oreillette gauche : végétation visible sur la face atriale de la valve mitrale, typique d'une endocardite infectieuse. L'ETO est un examen fondamental et obligatoire dans cette indication car elle met en évidence des végétations parfois très fines, impossibles à voir en ETT, et précise les mécanismes lésionnels (rupture de cordage, perforation) qui guident la décision et la technique chirurgicales.","quiz":{"stem":"Devant une suspicion d'endocardite infectieuse sur la valve mitrale, quel examen échographique est obligatoire pour le diagnostic ?","options":["L'échocardiographie transœsophagienne (ETO)","L'échocardiographie de stress sous dobutamine","L'échocardiographie d'effort","Le mode TM seul"],"correct":0},"src":"p. 217"},{"id":"233-echo-06","title":"Quantification de l'insuffisance aortique par hyperdébit et méthode PISA","rank":"A","objective":"233-obj-04","schematic":"doppler","findings":["Hyperdébit dans la chambre de chasse du ventricule gauche, signant une IA volumétriquement significative (grade 3-4)","Zone de convergence proximale (PISA) mesurée pour calculer la surface de l'orifice régurgitant","Mesure du flux de régurgitation aortique en doppler","Combinaison des paramètres pour classer la fuite en 4 grades de sévérité croissante"],"measures":[{"label":"SOR (IA grade 4, sévère)","severe":"≥ 30 mm² (volume régurgité ≥ 60 mL)","rank":"A"},{"label":"Hyperdébit dans la chambre de chasse du VG","severe":"> 4 L/min/m²","rank":"B"},{"label":"Flux rétrograde télédiastolique dans l'isthme aortique","severe":"> 20 cm/s","rank":"B"}],"description":"L'évaluation doppler de l'insuffisance aortique combine plusieurs critères : l'hyperdébit dans la chambre de chasse du ventricule gauche (signe indirect d'une fuite volumétriquement significative), la méthode PISA (mesure de la zone de convergence proximale) et la mesure du flux de régurgitation, permettant de calculer la surface de l'orifice régurgitant et le volume régurgité — dans l'exemple du collège, 26 mm² et 65 mL, correspondant à une fuite sévère (grade 4).","quiz":{"stem":"Une surface de l'orifice régurgitant de 26 mm² avec un volume régurgité de 65 mL, mesurés par la méthode PISA dans une insuffisance aortique, correspondent à :","options":["Une fuite sévère (grade 4)","Une fuite minime (grade 1)","Une fuite minime à modérée (grade 2)","L'absence de fuite significative"],"correct":0},"src":"p. 235"},{"id":"233-echo-07","title":"Remodelage excentrique du VG en mode TM (insuffisance aortique)","rank":"A","objective":"233-obj-04","schematic":"mmode","findings":["Diamètre télédiastolique du VG mesuré en mode TM, exemple du collège à 63 mm","Diamètre télésystolique du VG mesuré en mode TM, exemple du collège à 44 mm","Ces mesures témoignent d'un remodelage excentrique typique de l'IA chronique","La FEVG (Simpson biplan) reste le plus souvent normale (> 50 %) dans les IA compensées"],"measures":[{"label":"Diamètre télésystolique du VG (indexé)","severe":"> 50 mm ou > 25 mm/m² (indication opératoire formelle si IA sévère asymptomatique)","rank":"B"},{"label":"FEVG","severe":"≤ 50 % (indication formelle) ; ≤ 55 % si chirurgie à bas risque","rank":"B"}],"description":"En mode TM (temps-mouvement), les diamètres du ventricule gauche sont mesurés en télédiastole et en télésystole (63 mm et 44 mm dans l'exemple du collège), témoignant du remodelage excentrique du VG dans l'insuffisance aortique chronique : la surcharge mixte, volumétrique et barométrique, dilate et hypertrophie le ventricule. Ces diamètres, indexés à la surface corporelle, ainsi que la FEVG mesurée par la méthode de Simpson biplan, sont les paramètres qui fondent les indications opératoires chez le patient asymptomatique.","quiz":{"stem":"Chez un patient porteur d'une insuffisance aortique sévère et asymptomatique, quel diamètre télésystolique du VG indexé impose formellement une indication opératoire ?","options":["> 25 mm/m²","> 15 mm/m²","> 10 mm/m²","> 35 mm/m²"],"correct":0},"src":"p. 236"}]}});
